// ─── [FIX-V9] Reload approvals + ledger balances from disk ───────────────────
let _reloadedApprovals = 0;
try {
  // Step A: restore ledger balances from snapshot
  if (fs.existsSync(LEDGER_SEED)) {
    const snap = JSON.parse(fs.readFileSync(LEDGER_SEED, 'utf8'));
    for (const { id, microcents } of (snap.accounts || [])) {
      ledger.ensureAccount(id);
      const current = ledger.balance(id);
      const target = BigInt(microcents);
      if (target > current) ledger.credit(id, target - current, { note: 'Restart restore' });
    }
    logger.info({ component: 'persist', accounts: snap.accounts?.length ?? 0 }, 'Restored ledger snapshot.');
  }

  // [V123-P14-03] Step A2: restore MMR state from DB (async; non-blocking)
  if (dbPool) {
    dbPool.query(`SELECT mmr_json FROM mmr_state WHERE mmr_id = 'default' LIMIT 1`)
      .then(result => {
        if (result.rows.length > 0) {
          try {
            const restored = MerkleMountainRange.fromJSON(
              typeof result.rows[0].mmr_json === 'string'
                ? JSON.parse(result.rows[0].mmr_json)
                : result.rows[0].mmr_json
            );
            // Restore peaks and leaf hashes into the singleton
            defaultMMR._peaks      = restored._peaks;
            defaultMMR._leafHashes = restored._leafHashes;
            defaultMMR._size       = restored._size;
            // Rebuild hash→leafIndex map
            seedHashMap(defaultMMR);
            logger.info({ component: 'mmr', leaves: defaultMMR._size }, '[V123] MMR state restored from DB.');
          } catch (parseErr) {
            logger.warn({ component: 'mmr' }, '[V123] MMR restore failed (starting fresh):', parseErr.message);
          }
        }
      })
      .catch(err => logger.warn({ component: 'mmr' }, '[V123] MMR state query failed (non-fatal):', err.message));
  }

  // [V124-P15-03] Step A3: load nonce counters from DB (async; non-blocking)
  if (dbPool) {
    _nonceTracker.setPool(dbPool);
    _nonceTracker.loadFromDB()
      .then(() => logger.info({ component: 'nonce' }, '[V124] Nonce counters loaded from DB.'))
      .catch(err => logger.warn({ component: 'nonce' }, '[V124] Nonce load failed (non-fatal):', err.message));
  }

  // [V134-RI-02] Step A3b: wire DB into rank system + load rank scores
  if (dbPool) {
    defaultUserRankSystem._db = dbPool;
    _commChannels._db         = dbPool;
    defaultUserRankSystem.loadFromDb()
      .then(r => logger.info({ component: 'rank', ...r }, '[V134] Rank scores loaded from DB.'))
      .catch(err => logger.warn({ component: 'rank' }, '[V134] Rank DB load failed (non-fatal):', err.message));
    // [V135-RH-04] Wire DB pool into engagementEngine for streak_events dedup (streak milestones)
    if (_v111 && _v111.engagementEngine) {
      _v111.engagementEngine._db = dbPool;
    }
    // [V143-AUTH-01] Wire DB pool into authService for persistent user/token storage
    try {
      const { defaultAuthService } = require('./lib/authService');
      defaultAuthService.setDb(dbPool);
      logger.info({ component: 'auth' }, '[V143] AuthService wired to DB pool');
    } catch (e) {
      logger.warn({ component: 'auth', err: e.message }, '[V143] AuthService DB wire failed (non-fatal)');
    }
    // [V136-NO] Wire DB pool into the rank notifier for notification persistence.
    _rankNotifier._db = dbPool;
    // [V139-MT01] Wire DB into message threading
    _messageThreading._db = dbPool;
    // [V139-RN01] Wire DB into reaction notifier for author lookup
    _reactionNotifier._db = dbPool;
    // [V140-EU-01] Wire DB + agentId into operator report
    _operatorReport._db = dbPool;
    _operatorReport._state.agentId = (typeof getAgentId === 'function') ? getAgentId() : null;
    _operatorReport._state.uptime  = () => process.uptime();
    // [V140-DL-01] Wire DB into delivery log retention + start daily purge
    _deliveryLogRetention._db = dbPool;
    if (process.env.ECOS_DELIVERY_LOG_RETENTION_ENABLED !== 'false') {
      _deliveryLogRetention.schedulePurge(); // 24h interval, unref'd
    }
    // [V137-ND-02] Load existing notifications from DB into memory (non-fatal).
    _rankNotifier.loadFromDb()
      .then(r => logger.info({ component: 'rank-notifier', ...r }, '[V137-ND-02] Notifications loaded from DB.'))
      .catch(err => logger.warn({ component: 'rank-notifier', err: err.message }, '[V137-ND-02] Notification DB load failed (non-fatal)'));
    // [V137-NC] Wire DB pool into notification prefs store.
    _notificationPrefs._db = dbPool;
    // [V138-ND01] Wire DB into WsHub for delivery log
    if (_notificationWsHub) _notificationWsHub._db = dbPool;

    // [V141-P31] Wire DB into V141 singletons
    _messageSearcher.setPool(dbPool);
    _reportMailer.setPool(dbPool);
    _onboardingChecker.setDeps({
      pool:        dbPool,
      railRegistry: typeof _railRegistry !== 'undefined' ? _railRegistry : null,
      auditLog:    defaultAuditLog,
      serverState: { version: 'V141' },
    });
  }

  // [V136-NO-02] Arm the daily streak-reminder sweep. Disabled by default; set
  // ECOS_STREAK_REMINDER_INTERVAL_MINUTES (e.g. 1440 for daily) to enable.
  // Non-fatal; handle is unref'd so it never blocks process exit.
  const _streakReminderMin = parseInt(process.env.ECOS_STREAK_REMINDER_INTERVAL_MINUTES, 10) || 0;
  if (_streakReminderMin > 0) {
    const _streakHandle = setInterval(() => {
      try {
        if (_v111 && _v111.engagementEngine) {
          const r = _rankNotifier.runStreakReminderSweep(_v111.engagementEngine);
          logger.info({ component: 'rank-notifier', ...r }, '[V136-NO-02] Daily streak reminder sweep ran');
        }
      } catch (err) {
        logger.warn({ component: 'rank-notifier', err: err.message }, '[V136-NO-02] Streak reminder sweep failed (non-fatal)');
      }
    }, _streakReminderMin * 60 * 1000);
    if (_streakHandle && _streakHandle.unref) _streakHandle.unref();
    logger.info({ component: 'rank-notifier', intervalMin: _streakReminderMin }, '[V136-NO-02] Streak reminder sweep armed');
  }

  // [V125-P16] Step A4: wire V125 singletons
  if (dbPool) {
    _mmrCompactor.setPool(dbPool);
    _auditBackfill.setDeps({ pool: dbPool, mmr: defaultMMR });
    _checkpointScheduler.setDeps({
      pool:               dbPool,
      mmr:                defaultMMR,
      mmrCheckpointLib:   { generateCheckpoint },
      agentId:            (typeof getAgentId === 'function' ? getAgentId() : 'unknown'),
    });
    _checkpointScheduler.loadConfig()
      .then(() => logger.info({ component: 'checkpoint-scheduler' }, '[V125] Checkpoint scheduler config loaded.'))
      .catch(err => logger.warn({ component: 'checkpoint-scheduler' }, '[V125] Scheduler config load failed (non-fatal):', err.message));
  }

  // [V126-P17-02] Wire checkpoint scheduler tick into MMR post-append callback
  registerPostAppendCallback((_leafIndex, leafCount) => {
    _checkpointScheduler.tick(leafCount).catch(() => {});
  });

  // [V126-P17-04] Optional audit backfill on startup (AUTO_BACKFILL=true)
  if (process.env.AUTO_BACKFILL === 'true' && dbPool) {
    _auditBackfill.run({ batchSize: 200, maxBatches: 20 })
      .then(r => logger.info({ component: 'audit-backfill', ...r }, '[V126] Startup audit backfill complete.'))
      .catch(err => logger.warn({ component: 'audit-backfill' }, '[V126] Startup backfill failed (non-fatal):', err.message));
  }

  // Step B: replay approval events to rebuild in-memory state
  if (fs.existsSync(APPROVALS_LOG)) {
    const lines = fs.readFileSync(APPROVALS_LOG, 'utf8').split('\n').filter(Boolean);
    for (const line of lines) {
      try {
        const ev = JSON.parse(line);
        const restored = hitlGate.restoreFromLog(ev.event, ev);
        if (ev.event === 'created' && restored) _reloadedApprovals++;
      } catch (_) { /* skip malformed lines */ }
    }
    logger.info({ component: 'persist', reloaded: _reloadedApprovals }, 'Reloaded approvals from log.');
  }
} catch (err) {
  logger.warn({ component: 'persist', err: err.message }, 'Startup reload failed (continuing fresh):', err.message);
}

// ─── Persistence helpers ──────────────────────────────────────────────────────
function _persistApprovalCreated(approval) {
  try {
    const line = JSON.stringify({
      event: 'created',
      id: approval.id,
      missionId: approval.missionId,
      clientAccountId: approval.clientAccountId,
      priceUsd: approval.priceUsd,
      aiOutput: approval.aiOutput,
      context: approval.context,
      confidence: approval.confidence,
      createdAt: approval.createdAt,
    }) + '\n';
    fs.appendFileSync(APPROVALS_LOG, line, 'utf8');
  } catch (e) { logger.warn({ component: 'persist' }, 'Failed to log approval.created:', e.message); }
  // [V84] Broadcast to connected validators
  if (hub) hub.onApprovalCreated(approval);

  // [V98] Record calibration sample (label not yet set)
  calibrationSamples.set(approval.id, {
    rawScore: typeof approval.confidence === 'number' ? approval.confidence : null,
    label:    null,
  });
}

function _persistApprovalResolved(approval) {
  try {
    const line = JSON.stringify({
      event: 'resolved',
      id: approval.id,
      status: approval.status,
      decision: approval.decision,
      validatorAccountId: approval.validatorAccountId,
      resolvedAt: approval.resolvedAt,
      finalOutput: approval.finalOutput,
    }) + '\n';
    fs.appendFileSync(APPROVALS_LOG, line, 'utf8');
  } catch (e) { logger.warn({ component: 'persist' }, 'Failed to log approval.resolved:', e.message); }
  // [V84] Broadcast to connected validators
  if (hub) hub.onApprovalResolved(approval);

  // [V98] Update calibration sample label
  const sample = calibrationSamples.get(approval.id);
  if (sample) {
    sample.label = approval.decision === 'approve' ? 1 : 0;
  }
  // Trigger auto-fit if threshold reached
  _maybeAutoFit();
}

// [V98] Auto-fit calibrator when 50+ labeled samples have accumulated
// and at least 10 minutes have passed since last fit.
function _maybeAutoFit() {
  const labeled = [...calibrationSamples.values()].filter(
    s => s.rawScore !== null && typeof s.label === 'number'
  );
  if (labeled.length < AUTO_FIT_THRESHOLD) return;
  const tenMinAgo = Date.now() - 10 * 60 * 1000;
  if (_lastAutoFit && new Date(_lastAutoFit).getTime() > tenMinAgo) return;
  try {
    calibrator.fit(labeled);
    _lastAutoFit = new Date().toISOString();
    logger.info({ component: 'calibrator', samples: labeled.length }, '[AutoFit] Calibrator auto-fitted');
    // Persist updated params
    const params = calibrator.serializeParams();
    if (params) {
      fs.writeFileSync(CALIBRATION_FILE, JSON.stringify(params, null, 2), 'utf8');
    }
  } catch (fitErr) {
    logger.warn({ component: 'calibrator', err: fitErr.message }, '[AutoFit] Auto-fit failed');
  }
}

function _snapshotLedger() {
  try {
    const accounts = ledger.listAccounts().map(a => ({
      id: a.id,
      microcents: a.microcents,
      usd: a.usd,
    }));
    fs.writeFileSync(LEDGER_SEED, JSON.stringify({ ts: new Date().toISOString(), accounts }, null, 2), 'utf8');
  } catch (e) { logger.warn({ component: 'persist' }, 'Failed to snapshot ledger:', e.message); }

  // [V123-P14-03] Persist MMR state to DB on each ledger snapshot
  if (dbPool) {
    try {
      const mmrJson = defaultMMR.toJSON();
      const mmrRoot = defaultMMR.root();
      const mmrSize = defaultMMR.stats ? defaultMMR.stats().size : (mmrJson.size || 0);
      dbPool.query(
        `INSERT INTO mmr_state (mmr_id, leaf_count, root_hash, mmr_json, updated_at)
         VALUES ('default', $1, $2, $3, NOW())
         ON CONFLICT (mmr_id) DO UPDATE
           SET leaf_count = EXCLUDED.leaf_count,
               root_hash  = EXCLUDED.root_hash,
               mmr_json   = EXCLUDED.mmr_json,
               updated_at = NOW()`,
        [mmrSize, mmrRoot, JSON.stringify(mmrJson)]
      ).catch(err => logger.warn({ component: 'mmr' },
        '[V123] MMR state persist failed (non-fatal):', err.message));
    } catch (mmrErr) {
      logger.warn({ component: 'mmr' }, '[V123] MMR snapshot prep failed (non-fatal):', mmrErr.message);
    }
  }

  // [V126-P17-01] Auto-compact MMR after every ledger snapshot (non-blocking)
  _mmrCompactor.maybeCompact(defaultMMR).then(r => {
    if (r.compacted) {
      logger.info({ component: 'mmr-compact', leavesArchived: r.leavesArchived, leavesRemaining: r.leavesRemaining },
        '[V126] MMR auto-compacted.');
    }
  }).catch(() => {});
}

// ─── Confidence Gate (inlined — no pg dep) ───────────────────────────────────
const AUTO_THRESHOLD = parseFloat(process.env.CONFIDENCE_AUTO || '0.70');
const HITL_THRESHOLD = parseFloat(process.env.CONFIDENCE_HITL || '0.50');

// [FIX-V17-GATE-ASSERT] Runtime assertion to prevent gate inversion and dead HITL_QUEUE (BUG-NO-GATE-ASSERT)
if (HITL_THRESHOLD >= AUTO_THRESHOLD) {
  throw new Error(
    `CRITICAL_CONFIG_ERROR: HITL_THRESHOLD (${HITL_THRESHOLD}) must be strictly less than AUTO_THRESHOLD (${AUTO_THRESHOLD}) to prevent gate inversion and dead HITL_QUEUE.`
  );
}

const MAX_PRICE_USD  = parseFloat(process.env.MAX_PRICE_USD   || '10000');
const MIN_PRICE_USD  = parseFloat(process.env.MIN_PRICE_USD   || '0.01');

function evaluateConfidenceGateStrict(body) {
  const { confidence, clientAccountId, priceUsd, aiOutput,
          context = {}, taskType = 'default', similarityKeys = [] } = body || {};

  if (confidence === null || confidence === undefined) {
    return { verdict: 'HARD_REJECT', confidence: null,
      reasons: ['confidence is null — calibrator not ready or provider returned null. Routing to HITL.'],
      sanitized: null };
  }
  const conf = typeof confidence === 'string' ? parseFloat(confidence) : confidence;
  if (!Number.isFinite(conf)) {
    return { verdict: 'HARD_REJECT', confidence: null,
      reasons: [`confidence "${confidence}" is not a finite number.`], sanitized: null };
  }

  const reasons = [];
  if (!clientAccountId)                         reasons.push('clientAccountId is required');
  if (priceUsd === undefined || priceUsd === null) reasons.push('priceUsd is required');
  if (aiOutput === undefined)                   reasons.push('aiOutput is required');
  if (reasons.length) return { verdict: 'HARD_REJECT', confidence: conf, reasons, sanitized: null };

  const priceN = parseFloat(priceUsd);
  if (!Number.isFinite(priceN))    reasons.push('priceUsd is not a finite number');
  else if (priceN < MIN_PRICE_USD) reasons.push(`priceUsd ${priceN} below minimum ${MIN_PRICE_USD}`);
  else if (priceN > MAX_PRICE_USD) reasons.push(`priceUsd ${priceN} exceeds maximum ${MAX_PRICE_USD}`);

  if (typeof aiOutput !== 'object' || aiOutput === null || !('result' in aiOutput))
    reasons.push('aiOutput must be a non-null object with a "result" key');

  if (conf < 0 || conf > 1) reasons.push(`confidence ${conf} out of range [0, 1]`);

  const sanitized = { clientAccountId, priceUsd: String(priceUsd), aiOutput,
                      context, confidence: conf, taskType, similarityKeys };

  if (reasons.length > 0 || conf < HITL_THRESHOLD) {
    if (conf < HITL_THRESHOLD && reasons.length === 0)
      reasons.push(`confidence ${conf.toFixed(4)} below HITL threshold ${HITL_THRESHOLD}`);
    return { verdict: 'HARD_REJECT', confidence: conf, reasons, sanitized: null };
  }
  if (conf >= AUTO_THRESHOLD)
    return { verdict: 'AUTO_FLOW', confidence: conf, reasons: [], sanitized };

  return { verdict: 'HITL_QUEUE', confidence: conf,
    reasons: [`confidence ${conf.toFixed(4)} in HITL band [${HITL_THRESHOLD}, ${AUTO_THRESHOLD})`],
    sanitized };
}

