// ─── [FIX-V61-P2] Rate limiting — POST /api/v1/validator/login ───────────────
// OWASP brute force protection: max 5 attempts per IP per 15 minutes.
// In-memory Map — no external dependency.
// Key: IP string. Value: { count, windowStart }.
// On 6th attempt: 429 Too Many Requests with Retry-After header.
// Window resets automatically after RATE_LIMIT_WINDOW_MS.
// Note: in-memory means limits reset on server restart — acceptable for V61.
// Production: add Redis-backed store or put nginx rate limiting in front.
const LOGIN_RATE_LIMIT_MAX      = parseInt(process.env.LOGIN_RATE_LIMIT_MAX      || '5',     10);
const LOGIN_RATE_LIMIT_WINDOW   = parseInt(process.env.LOGIN_RATE_LIMIT_WINDOW   || '900000', 10); // 15 min ms
const _loginAttempts = new Map(); // Map<ip, { count, windowStart }>

/**
 * Check and record a login attempt for a given IP.
 * Returns { allowed: true } or { allowed: false, retryAfterSec }.
 * @param {string} ip
 */
function _checkLoginRateLimit(ip) {
  const now    = Date.now();
  const entry  = _loginAttempts.get(ip);

  if (!entry || now - entry.windowStart >= LOGIN_RATE_LIMIT_WINDOW) {
    // New window — first attempt
    _loginAttempts.set(ip, { count: 1, windowStart: now });
    return { allowed: true };
  }

  if (entry.count >= LOGIN_RATE_LIMIT_MAX) {
    const retryAfterMs  = LOGIN_RATE_LIMIT_WINDOW - (now - entry.windowStart);
    const retryAfterSec = Math.ceil(retryAfterMs / 1000);
    return { allowed: false, retryAfterSec };
  }

  entry.count += 1;
  return { allowed: true };
}

/**
 * Reset login attempt counter for a given IP (called on successful login).
 * @param {string} ip
 */
function _resetLoginRateLimit(ip) {
  _loginAttempts.delete(ip);
}

