// [V154-SEC] Security headers middleware — applied globally
const _v154SecurityHeaders = (req, res, next) => {
  res.setHeader('X-Content-Type-Options',    'nosniff');
  res.setHeader('X-Frame-Options',           'DENY');
  res.setHeader('X-XSS-Protection',          '1; mode=block');
  res.setHeader('Referrer-Policy',           'strict-origin-when-cross-origin');
  res.setHeader('Permissions-Policy',        'geolocation=(), microphone=(), camera=()');
  if (typeof next === 'function') next(); else return;
};
// Attach globally to all responses
const _origSetHeader = app.response && app.response.setHeader;
app.use(_v154SecurityHeaders);

