// ── [V154-LB-01] GET /api/v1/leaderboard/extended ────────────────────────────
app.get('/api/v1/leaderboard/extended', async (req, res) => {
  try {
    let tiers = {};
    let topEarners = [];
    if (dbPool) {
      try {
        const r = await dbPool.query(
          "SELECT tier, COUNT(*) AS cnt FROM user_ranks GROUP BY tier ORDER BY cnt DESC LIMIT 10"
        );
        for (const row of r.rows) tiers[row.tier] = parseInt(row.cnt);
        const earners = await dbPool.query(
          "SELECT validator_id, SUM(validator_usd) AS earned FROM approvals WHERE status='resolved' GROUP BY validator_id ORDER BY earned DESC LIMIT 10"
        );
        topEarners = earners.rows.map(r => ({
          validatorId: r.validator_id,
          earned: parseFloat(r.earned || 0),
        }));
      } catch (e) { /* non-fatal */ }
    } else {
      const approvals = hitlGate?.listApprovals ? hitlGate.listApprovals() : [];
      const earnerMap = {};
      for (const a of approvals) {
        if (a.status !== 'resolved') continue;
        const vid = a.validatorId || 'unknown';
        earnerMap[vid] = (earnerMap[vid] || 0) + parseFloat(a.priceUsd || 0) * 0.4;
      }
      topEarners = Object.entries(earnerMap)
        .sort((a,b) => b[1]-a[1]).slice(0,10)
        .map(([validatorId, earned]) => ({ validatorId, earned: parseFloat(earned.toFixed(4)) }));
    }
    res.setHeader('Cache-Control', 'max-age=60, stale-while-revalidate=120');
    res.json({ tiers, topEarners, ecosVersion: 'V154' });
  } catch (e) {
    res.status(500).json({ error: e.message, ecosVersion: 'V154' });
  }
});

