// ── [V154-WH-02] POST /api/v1/withdrawals/history — record a withdrawal ──────
app.post('/api/v1/withdrawals/history', async (req, res) => {
  try {
    const body = typeof req.body === 'object' ? req.body : await (async () => {
      const chunks = [];
      for await (const c of req) chunks.push(c);
      return JSON.parse(Buffer.concat(chunks).toString() || '{}');
    })();
    if (!body.accountId || !body.reference) {
      return res.status(400).json({ error: 'accountId and reference required' });
    }
    await saveWithdrawal(body, dbPool);
    res.status(201).json({ ok: true, reference: body.reference, ecosVersion: 'V154' });
  } catch (e) {
    res.status(500).json({ error: e.message, ecosVersion: 'V154' });
  }
});

