app.patch('/api/v1/withdrawals/history/:ref', async (req, res) => {
  const reference = req.params.ref;
  try {
    const body = typeof req.body === 'object' ? req.body : await (async () => {
      const chunks = [];
      for await (const c of req) chunks.push(c);
      return JSON.parse(Buffer.concat(chunks).toString() || '{}');
    })();
    const status = body.status || 'confirmed';
    await updateWithdrawalStatusDB(reference, status, dbPool);
    res.json({ ok: true, reference, status, ecosVersion: 'V154' });
  } catch (e) {
    res.status(500).json({ error: e.message, ecosVersion: 'V154' });
  }
});

