  // Look up an audit entry by hash and return its provenance chain.
  app.get('/api/v1/audit/provenance/:traceHash', (req, res) => {
    try {
      const { traceHash } = req.params;
      if (!traceHash) return res.status(400).json({ ok: false, error: 'traceHash required' });
      const depth  = req.query.depth ? Math.max(1, Math.min(50, parseInt(req.query.depth))) : 5;
      const result = _v106.replayEngine.lookupProvenance(traceHash, { depth });
      if (!result.ok) return res.status(404).json(result);
      res.json(result);
    } catch (err) {
      logger.error({ err: err.message }, '[V106] audit/provenance error');
      res.status(500).json({ ok: false, error: err.message });
    }
  });

  // ── [V106] GET /api/v1/audit/dag ─────────────────────────────────────────────
  // Causal DAG of the N most recent audit entries.
  app.get('/api/v1/audit/dag', (req, res) => {
    try {
      const limit   = Math.min(500, parseInt(req.query.limit) || 50);
      const entries = auditLog.entries();
      const slice   = entries.slice(-limit);

      const nodes = slice.map(e => ({
        id:   `audit-${e.index}`,
        type: e.type,
        ts:   e.ts,
        hash: e.hash,
        hasProvenance: !!(e.payload && e.payload.inferenceProvenance),
      }));

      const edges = [];
      for (let i = 1; i < slice.length; i++) {
        edges.push({ from: `audit-${slice[i - 1].index}`, to: `audit-${slice[i].index}`, relation: 'prevHash' });
      }

      const provenanceEdges = slice
        .filter(e => e.payload && e.payload.inferenceProvenance)
        .map(e => ({
          from:     e.payload.inferenceProvenance.traceId,
          to:       `audit-${e.index}`,
          relation: 'inferenceProvenance',
          model:    e.payload.inferenceProvenance.model,
        }));

      res.json({ ok: true, nodeCount: nodes.length, nodes, edges, provenanceEdges });
    } catch (err) {
      logger.error({ err: err.message }, '[V106] audit/dag error');
      res.status(500).json({ ok: false, error: err.message });
    }
  });

