  // ── [V106] POST /api/v1/snapshot/restore ─────────────────────────────────────
  // Restore state from a snapshot.
  // Requires ECOS_DEPOSIT_API_KEY auth (same as /deposit) OR DEV mode.
  // dryRun=true in body: verifies without applying.
  app.post('/api/v1/snapshot/restore', async (req, res) => {
    try {
      // Auth gate: require API key or dev mode
      const apiKey      = process.env.ECOS_DEPOSIT_API_KEY;
      const reqKey      = req.headers['x-api-key'] || req.headers['authorization'];
      const isDev       = process.env.NODE_ENV !== 'production';
      if (apiKey && !isDev && reqKey !== apiKey && reqKey !== `Bearer ${apiKey}`) {
        return res.status(401).json({ ok: false, error: 'Unauthorized — x-api-key required for snapshot restore' });
      }

      const { snapshot, dryRun } = req.body || {};
      if (!snapshot) return res.status(400).json({ ok: false, error: 'snapshot required in body' });

      const result = await _v106.snapshotEngine.restore(snapshot, { dryRun: !!dryRun });
      if (!result.ok) return res.status(400).json(result);

      logger.info({ component: 'snapshot', dryRun: !!dryRun, label: snapshot.label },
        '[V106] Snapshot restore requested');

      res.json(result);
    } catch (err) {
      logger.error({ err: err.message }, '[V106] snapshot/restore error');
      res.status(500).json({ ok: false, error: err.message });
    }
  });

