  // ════════════════════════════════════════════════════════════════════════════
  //  [V107] P5-02/P5-03 — Inference Provenance Live Pipeline + Agent Bus
  // ════════════════════════════════════════════════════════════════════════════

  // V107 module initialization
  const _v107 = (() => {
    const { AgentBus, CHANNEL_TYPES } = require('./lib/agentBus');

    const bus = new AgentBus({
      ringSize:      1000,
      deadLetterMax: 500,
      logger: {
        info:  (obj, msg) => logger.info({ ...obj, component: 'agentBus' }, msg),
        warn:  (obj, msg) => logger.warn({ ...obj, component: 'agentBus' }, msg),
        error: (obj, msg) => logger.error({ ...obj, component: 'agentBus' }, msg),
      },
    });

    logger.info({ component: 'v107' }, '[V107] AgentBus initialized');

    return { bus, CHANNEL_TYPES };
  })();

  // ── [V107] POST /api/v1/memory/reembed ───────────────────────────────────────
  // Trigger a re-embedding run for knowledge patches that use heuristic embeddings.
  // Replaces heuristic vectors with real embeddings from the active provider.
  //
  // Body (all optional):
  //   provider  string  — force provider: 'ollama'|'openai'|'heuristic' (default: active)
  //   dryRun    bool    — if true: count candidates without writing to DB
  //   force     bool    — if true: re-embed ALL patches, not just heuristic ones
  //   batchSize number  — parallel embed batch size (default: 20, max: 100)
  //   limit     number  — max patches to process
  //   since     string  — ISO timestamp: only patches updated after this time
  app.post('/api/v1/memory/reembed', async (req, res) => {
    try {
      // Auth gate — require API key in production
      const apiKey = process.env.ECOS_DEPOSIT_API_KEY;
      const reqKey = req.headers['x-api-key'] || req.headers['authorization'];
      const isDev  = process.env.NODE_ENV !== 'production';
      if (apiKey && !isDev && reqKey !== apiKey && reqKey !== `Bearer ${apiKey}`) {
        return res.status(401).json({ ok: false, error: 'Unauthorized — x-api-key required for reembed' });
      }

      const {
        provider: forceProvider,
        dryRun    = false,
        force     = false,
        batchSize = 20,
        limit,
        since,
      } = req.body || {};

      // Validate batchSize
      const safeBatch = Math.max(1, Math.min(100, parseInt(batchSize) || 20));

      // Resolve embedding provider
      let provider = _v106.embeddingProvider;
      if (forceProvider && forceProvider !== provider.providerId) {
        const { buildDefaultProvider } = require('./lib/embeddingProvider');
        const origProvider = process.env.EMBEDDING_PROVIDER;
        process.env.EMBEDDING_PROVIDER = forceProvider;
        try {
          provider = buildDefaultProvider({ logger: { info: () => {}, warn: () => {} } });
        } finally {
          if (origProvider === undefined) delete process.env.EMBEDDING_PROVIDER;
          else process.env.EMBEDDING_PROVIDER = origProvider;
        }
      }

      // Fetch candidates from DB
      let db;
      try {
        const { Pool } = require('pg');
        db = new Pool({ connectionString: process.env.DATABASE_URL });
      } catch (e) {
        return res.status(503).json({ ok: false, error: 'DB unavailable: ' + e.message });
      }

      let query = `SELECT id, patch_body, embedding_type FROM knowledge_patches WHERE deleted_at IS NULL`;
      const params = [];
      if (!force) {
        query += ` AND (embedding_type IS NULL OR embedding_type = 'heuristic')`;
      }
      if (since) {
        params.push(since);
        query += ` AND updated_at >= $${params.length}`;
      }
      if (limit) {
        params.push(Math.max(1, parseInt(limit)));
        query += ` LIMIT $${params.length}`;
      }

      let patches;
      try {
        const result = await db.query(query, params);
        patches = result.rows;
      } catch (e) {
        await db.end().catch(() => {});
        return res.status(500).json({ ok: false, error: 'DB query failed: ' + e.message });
      }

      if (dryRun) {
        await db.end().catch(() => {});
        return res.json({
          ok:         true,
          dryRun:     true,
          candidates: patches.length,
          provider:   provider.providerId,
          isReal:     provider.isReal,
          message:    `Would re-embed ${patches.length} patches using provider '${provider.providerId}'.`,
        });
      }

      // Process batches
      const runId   = 'api-reembed-' + Date.now();
      let succeeded = 0;
      let failed    = 0;
      const errors  = [];

      for (let i = 0; i < patches.length; i += safeBatch) {
        const batch   = patches.slice(i, i + safeBatch);
        const results = await Promise.allSettled(batch.map(p => provider.embed(p.patch_body || '')));

        for (let j = 0; j < batch.length; j++) {
          const patch  = batch[j];
          const result = results[j];

          if (result.status === 'fulfilled') {
            const vector = result.value;
            try {
              await db.query(
                `UPDATE knowledge_patches
                 SET embedding_type = $1, embedding_dims = $2, updated_at = NOW()
                 WHERE id = $3`,
                [provider.providerId, vector.length, patch.id]
              );
              // Log to embedding_migration_log (idempotent, ignore if table missing)
              await db.query(
                `INSERT INTO embedding_migration_log
                   (run_id, patch_id, from_provider, to_provider, dims, status, created_at)
                 VALUES ($1,$2,$3,$4,$5,'ok',NOW()) ON CONFLICT DO NOTHING`,
                [runId, patch.id, patch.embedding_type || 'heuristic', provider.providerId, vector.length]
              ).catch(() => {});
              succeeded++;
            } catch (updateErr) {
              failed++;
              errors.push({ patchId: patch.id, error: updateErr.message });
            }
          } else {
            failed++;
            errors.push({ patchId: patch.id, error: result.reason?.message || 'embed failed' });
          }
        }
      }

      await db.end().catch(() => {});

      // Log to audit trail
      try {
        auditLog.append('MEMORY_REEMBEDDED', {
          runId, provider: provider.providerId,
          total: patches.length, succeeded, failed,
        });
      } catch (_) {}

      logger.info({ component: 'v107', runId, succeeded, failed },
        '[V107] POST /api/v1/memory/reembed complete');

      res.json({
        ok:        failed === 0,
        runId,
        provider:  provider.providerId,
        isReal:    provider.isReal,
        total:     patches.length,
        succeeded,
        failed,
        errors:    errors.slice(0, 10),
      });
    } catch (err) {
      logger.error({ err: err.message }, '[V107] memory/reembed error');
      res.status(500).json({ ok: false, error: err.message });
    }
  });

  // ── [V107] GET /api/v1/agent/bus/status ──────────────────────────────────────
  // Report AgentBus statistics: published/delivered/dead-letter counts, channels.
  app.get('/api/v1/agent/bus/status', (req, res) => {
    try {
      const stats = _v107.bus.stats();
      res.json({ ok: true, ...stats });
    } catch (err) {
      logger.error({ err: err.message }, '[V107] agent/bus/status error');
      res.status(500).json({ ok: false, error: err.message });
    }
  });

  // ── [V107] POST /api/v1/agent/bus/send ───────────────────────────────────────
  // Publish a message onto the inter-agent bus (for external orchestration / testing).
  // Body: { channel, from, to?, payload, parentId? }
  app.post('/api/v1/agent/bus/send', (req, res) => {
    try {
      const { channel, from, to = null, payload, parentId = null, meta = {} } = req.body || {};
      if (!channel) return res.status(400).json({ ok: false, error: 'channel is required' });
      if (!from)    return res.status(400).json({ ok: false, error: 'from (agentId) is required' });
      if (!payload) return res.status(400).json({ ok: false, error: 'payload is required' });

      const msg = _v107.bus.publish({ channel, from, to, payload, parentId, meta });
      res.json({ ok: true, messageId: msg.messageId, ts: msg.ts, channel, from, to });
    } catch (err) {
      logger.error({ err: err.message }, '[V107] agent/bus/send error');
      res.status(500).json({ ok: false, error: err.message });
    }
  });

  // ── [V107] GET /api/v1/agent/bus/replay ──────────────────────────────────────
  // Replay recent messages from the AgentBus ring buffer for a given channel.
  // Query: channel (required), limit (default 50), from, to, since (ISO timestamp)
  app.get('/api/v1/agent/bus/replay', (req, res) => {
    try {
      const { channel, from, to, since } = req.query;
      if (!channel) return res.status(400).json({ ok: false, error: 'channel query param is required' });
      const limit = Math.min(500, parseInt(req.query.limit) || 50);
      const messages = _v107.bus.replay(channel, { limit, from, to, since });
      res.json({ ok: true, channel, count: messages.length, messages });
    } catch (err) {
      logger.error({ err: err.message }, '[V107] agent/bus/replay error');
      res.status(500).json({ ok: false, error: err.message });
    }
  });

  // ── [V107] GET /api/v1/agent/bus/chain/:messageId ────────────────────────────
  // Return the causal ancestor chain for a given bus message (follows parentId).
  app.get('/api/v1/agent/bus/chain/:messageId', (req, res) => {
    try {
      const { messageId } = req.params;
      const depth  = Math.max(1, Math.min(50, parseInt(req.query.depth) || 10));
      const chain  = _v107.bus.getCausalChain(messageId, { depth });
      if (!chain.length) return res.status(404).json({ ok: false, error: 'messageId not found in index' });
      res.json({ ok: true, messageId, depth: chain.length, chain });
    } catch (err) {
      logger.error({ err: err.message }, '[V107] agent/bus/chain error');
      res.status(500).json({ ok: false, error: err.message });
    }
  });

  // ════════════════════════════════════════════════════════════════════════════
  //  [V108] P6 — Production Hardening
  //  P6-01: AgentBus × AgentRuntime Integration
  //  P6-03: Persistent AgentBus (DB-backed)
  //  P5-04: DB-backed Snapshot Persistence
  //  New endpoints: snapshot/db/save, snapshot/db/list, snapshot/db/restore
  //                 agent/bus/persist, agent/bus/load, agent/bus/dead-letters
  // ════════════════════════════════════════════════════════════════════════════

  // V108 module initialization
  const _v108 = (() => {
    const { AgentRuntime } = require('./lib/agentRuntime');

    // [P6-01] Wire the V107 AgentBus into a shared AgentRuntime singleton
    const runtime = new AgentRuntime({
      bus: _v107.bus,
    });

    // Inject pino logger into runtime
    runtime.setLogger({
      info:  (obj, msg) => logger.info({ ...obj, component: 'agentRuntime' }, msg),
      warn:  (obj, msg) => logger.warn({ ...obj, component: 'agentRuntime' }, msg),
      error: (obj, msg) => logger.error({ ...obj, component: 'agentRuntime' }, msg),
    });

    logger.info({ component: 'v108' }, '[V108] AgentRuntime wired with AgentBus (P6-01)');

    // [P5-04] Wire DB pool into SnapshotEngine for DB persistence
    if (dbPool) {
      logger.info({ component: 'v108' }, '[V108] SnapshotEngine DB persistence available (P5-04)');
    }

    return { runtime };
  })();

