  // ── [V108] GET /api/v1/agent/bus/dead-letters ────────────────────────────────
  // Inspect dead-letter queue (in-memory + optional DB drain).
  // Query: limit (default 50), persist=true to flush to DB
  app.get('/api/v1/agent/bus/dead-letters', async (req, res) => {
    try {
      const limit   = Math.min(200, parseInt(req.query.limit) || 50);
      const persist = req.query.persist === 'true';
      const entries = _v107.bus.drainDeadLetters(limit);

      let dbResult = null;
      if (persist && dbPool) {
        try {
          dbResult = await _v107.bus.persistDeadLettersToDB(dbPool, { limit });
        } catch (dbErr) {
          dbResult = { error: dbErr.message };
        }
      }

      res.json({
        ok:    true,
        count: entries.length,
        entries,
        db:    dbResult,
      });
    } catch (err) {
      logger.error({ err: err.message }, '[V108] agent/bus/dead-letters error');
      res.status(500).json({ ok: false, error: err.message });
    }
  });

  // ── [V108] POST /api/v1/agent/bus/prune ──────────────────────────────────────
  // Prune old agent_bus_messages from DB (retention policy).
  // Body: { retainDays } (default: 30)
  // Requires ECOS_DEPOSIT_API_KEY in production.
  app.post('/api/v1/agent/bus/prune', async (req, res) => {
    try {
      const apiKey = process.env.ECOS_DEPOSIT_API_KEY;
      const reqKey = req.headers['x-api-key'] || req.headers['authorization'];
      const isDev  = process.env.NODE_ENV !== 'production';
      if (apiKey && !isDev && reqKey !== apiKey && reqKey !== `Bearer ${apiKey}`) {
        return res.status(401).json({ ok: false, error: 'Unauthorized' });
      }
      if (!dbPool) {
        return res.status(503).json({ ok: false, error: 'DATABASE_URL not set — DB unavailable' });
      }

      const retainDays = Math.max(1, parseInt((req.body || {}).retainDays) || 30);
      const { rows } = await dbPool.query(
        'SELECT ecos_prune_bus_messages($1) AS deleted',
        [retainDays]
      );
      const deleted = rows[0]?.deleted ?? 0;
      logger.info({ component: 'v108', retainDays, deleted }, '[V108] agent/bus/prune complete');
      res.json({ ok: true, retainDays, deleted });
    } catch (err) {
      logger.error({ err: err.message }, '[V108] agent/bus/prune error');
      res.status(500).json({ ok: false, error: err.message });
    }
  });

