  // ── [V110-BUG-K-2] POST /api/v1/payments/stripe/create-intent ────────────────
  // Create a Stripe PaymentIntent and return the clientSecret to the frontend.
  //
  // Full checkout flow:
  //   1. Frontend calls this endpoint → receives { paymentIntentId, clientSecret }
  //   2. Frontend calls stripe.confirmCardPayment(clientSecret)
  //   3. Stripe fires payment_intent.succeeded webhook → V109 handler credits ledger
  //
  // Body: { clientAccountId, amountCents, currency? }
  // Response: { ok, paymentIntentId, clientSecret, amount, currency, mock }
  //
  // No STRIPE_API_KEY → mock mode (clientSecret = 'pi_mock_..._secret_mock').
  // STRIPE_API_KEY set → calls POST https://api.stripe.com/v1/payment_intents.
  //
  // Logs each intent to stripe_payment_intents table (when DB available).
  app.post('/api/v1/payments/stripe/create-intent', async (req, res) => {
    try {
      const { clientAccountId, amountCents, currency } = req.body || {};

      if (!clientAccountId || amountCents == null) {
        return res.status(400).json({
          ok:    false,
          error: 'clientAccountId and amountCents are required',
        });
      }

      const cents = Math.round(Number(amountCents));
      if (!Number.isFinite(cents) || cents <= 0) {
        return res.status(400).json({ ok: false, error: 'amountCents must be a positive number' });
      }

      const { defaultStripeProvider: sp } = require('./lib/stripeProvider');
      const result = await sp.createPaymentIntent(clientAccountId, cents, currency || 'usd');

      logger.info(
        { component: 'v110', clientAccountId, amountCents: cents, mock: result.mock,
          paymentIntentId: result.paymentIntentId },
        '[V110] create-intent: PaymentIntent created'
      );

      // ── Log to stripe_payment_intents audit table (non-fatal) ────────────────
      if (dbPool && result.paymentIntentId) {
        const crypto = require('node:crypto');
        const secretHash = result.clientSecret
          ? crypto.createHash('sha256').update(result.clientSecret).digest('hex')
          : null;
        try {
          await dbPool.query(
            `INSERT INTO stripe_payment_intents
               (payment_intent_id, client_account_id, amount_cents, currency, mock, client_secret_hash)
             VALUES ($1, $2, $3, $4, $5, $6)
             ON CONFLICT (payment_intent_id) DO NOTHING`,
            [result.paymentIntentId, clientAccountId, cents,
             result.currency, result.mock, secretHash]
          );
        } catch (dbErr) {
          logger.warn({ component: 'v110', err: dbErr.message },
            '[V110] stripe_payment_intents insert failed (non-fatal)');
        }
      }

      return res.status(201).json({
        ok:              true,
        paymentIntentId: result.paymentIntentId,
        clientSecret:    result.clientSecret,
        amount:          result.amount,
        currency:        result.currency,
        mock:            result.mock,
      });
    } catch (err) {
      logger.error({ err: err.message }, '[V110] create-intent error');
      // Stripe API errors → 502 Bad Gateway; local errors → 500
      const status = err.message && err.message.startsWith('StripeProvider:') ? 502 : 500;
      return res.status(status).json({ ok: false, error: err.message });
    }
  });

  // ── [V110-P8-03] GET /api/v1/audit/replay/chain-verify ───────────────────────
  // Verify the entire audit log replay chain by paginating through all entries.
