  // ── [V115-P11-02] GET /api/v1/users/:id/graduation ──────────────────────────
  // Returns the graduation ladder status for a user.
  // Body/Query: validationsCompleted, patchesAuthored, referralsConverted, menteeActivated
  //
  // Response: { ok, userId, currentStage, nextStage, nextRequirements, allStages, stats }
  app.get('/api/v1/users/:id/graduation', (req, res) => {
    try {
      const userId = req.params.id;
      if (!userId) return res.status(400).json({ ok: false, error: 'userId required' });

      const stats = {
        validationsCompleted: parseInt(req.query.validationsCompleted || '0') || 0,
        patchesAuthored:      parseInt(req.query.patchesAuthored      || '0') || 0,
        referralsConverted:   parseInt(req.query.referralsConverted   || '0') || 0,
        menteeActivated:      parseInt(req.query.menteeActivated      || '0') || 0,
      };

      // Evaluate progression
      const evalResult = _v115.graduationEngine.evaluate(userId, stats);
      const report     = _v115.graduationEngine.progressionReport(userId, stats);

      res.json({
        ok: true,
        ...report,
        advanced:     evalResult.advanced,
        bonusCredits: evalResult.bonusCredits,
      });
    } catch (err) {
      logger.error({ err: err.message }, '[V115] users/:id/graduation error');
      res.status(500).json({ ok: false, error: err.message });
    }
  });

