  // ── [V115-P11-09] Sybil Resistance in Validator Onboarding ──────────────────

  // POST /api/v1/validator/onboard
  // Register a new validator with Sybil resistance screening.
  // Body: { userId, email, ip?, deviceFingerprint?, referredBy?, skillTestScore? }
  // Response: { ok, verdict, score, signals } or 403 if BLOCK
  app.post('/api/v1/validator/onboard', (req, res) => {
    try {
      const { userId, email, ip, deviceFingerprint, referredBy, skillTestScore } = req.body || {};
      if (!userId || !email) {
        return res.status(400).json({ ok: false, error: 'userId and email are required' });
      }

      // Fallback: use request IP if not explicitly provided
      const resolvedIp = ip || (req.headers['x-forwarded-for'] || '').split(',')[0].trim() || req.socket?.remoteAddress || null;

      const { verdict, score, signals } = _v115.sybilResistance.evaluate({
        userId, email, ip: resolvedIp, deviceFingerprint: deviceFingerprint || null,
        referredBy: referredBy || null,
        skillTestScore: skillTestScore !== undefined ? Number(skillTestScore) : null,
      });

      logger.info({ component: 'v115', userId, verdict, score }, '[V115-P11-09] Validator onboard evaluation');

      if (verdict === 'BLOCK') {
        return res.status(403).json({
          ok:      false,
          verdict,
          score,
          signals,
          error:   'Validator registration denied — Sybil resistance check failed',
        });
      }

      res.status(verdict === 'REVIEW' ? 202 : 201).json({
        ok: true,
        verdict,
        score,
        signals,
        message: verdict === 'REVIEW'
          ? 'Registration submitted for manual review. You will be notified within 24 hours.'
          : 'Validator registration accepted. Complete orientation tasks to begin earning.',
      });
    } catch (err) {
      logger.error({ err: err.message }, '[V115] validator/onboard error');
      res.status(500).json({ ok: false, error: err.message });
    }
  });

