// ── [V158-T02] Wire up WorkspaceTaskService singleton ──────────────────────
const {
  WorkspaceTaskService: _WTS,
  defaultWorkspaceTaskService: _wts,
  VALID_STATUSES: WS_TASK_STATUSES,
  VALID_PRIORITIES: WS_TASK_PRIORITIES,
} = require('./lib/workspaceTaskService');
if (typeof dbPool !== 'undefined' && dbPool) _wts.setDb(dbPool);

// ── [V158-T02b] Wire up CalibrationHistoryService ──────────────────────────
const {
  CalibrationHistoryService: _CHS,
  defaultCalibrationHistory: _calibHistory,
} = require('./lib/calibrationHistoryService');
if (typeof dbPool !== 'undefined' && dbPool) _calibHistory.setDb(dbPool);
_calibHistory._log = logger.child({ component: 'calib-history' });

// ── [V158-T02c] Wire up WorkspaceRealTimeFeed (SSE) ────────────────────────
const {
  WorkspaceSSEFeed: _WSSF,
  defaultWorkspaceSSEFeed: _wsFeed,
} = require('./lib/workspaceRealTimeFeed');

// ── Patch calibrator.fit to auto-record in history ─────────────────────────
try {
  const _origFit158 = calibrator.fit.bind(calibrator);
  calibrator.fit = function(samples, triggerType) {
    const result = _origFit158(samples);
    const p = calibrator.serializeParams ? calibrator.serializeParams() : {};
    _calibHistory.recordFit({
      A: p.A, B: p.B,
      sampleCount: samples.length,
      trigger: triggerType || 'auto',
    }).catch(() => {});
    return result;
  };
} catch (_) {}

// ── Workspace task activity logger ─────────────────────────────────────────
function _logWsActivity(wsId, actorId, evType, entityType, entityId, payload) {
  if (typeof dbPool !== 'undefined' && dbPool) {
    dbPool.query(
      `INSERT INTO workspace_activity_log
        (workspace_id,actor_id,event_type,entity_type,entity_id,payload)
       VALUES ($1,$2,$3,$4,$5,$6)`,
      [wsId, actorId, evType, entityType, entityId, JSON.stringify(payload || {})]
    ).catch(() => {});
  }
}

// ── [V158-T03] POST /api/v1/workspaces/:workspaceId/tasks ──────────────────
app.post('/api/v1/workspaces/:workspaceId/tasks', async (req, res) => {
  try {
    const { workspaceId } = req.params;
    const { title, description, status, priority, assigneeId, dueAt, tags, metadata } = req.body || {};
    if (!title || !String(title).trim())
      return res.status(400).json({ ok: false, error: 'title is required', code: 'MISSING_TITLE', ecosVersion: 'V158' });
    const actorId = req.headers['x-user-id'] || req.body?.createdBy || null;
    const task = await _wts.createTask(workspaceId, { title, description, status, priority, assigneeId, dueAt, tags, metadata, createdBy: actorId });
    _logWsActivity(workspaceId, actorId, 'task.created', 'task', task.id, { title: task.title });
    _wsFeed.emitTaskCreated(workspaceId, task);
    res.status(201).json({ ok: true, task, ecosVersion: 'V158' });
  } catch (err) { res.status(400).json({ ok: false, error: err.message, ecosVersion: 'V158' }); }
});

