// ── [V158-T17] POST /api/v1/workspaces/:workspaceId/members ────────────────
app.post('/api/v1/workspaces/:workspaceId/members', async (req, res) => {
  try {
    const { workspaceId } = req.params;
    const { userId, role = 'member' } = req.body || {};
    if (!userId) return res.status(400).json({ ok: false, error: 'userId required', ecosVersion: 'V158' });
    const VALID_ROLES = ['owner','admin','manager','member','viewer'];
    if (!VALID_ROLES.includes(role))
      return res.status(400).json({ ok: false, error: `Invalid role. Valid: ${VALID_ROLES.join(', ')}`, ecosVersion: 'V158' });
    const invitedBy = req.headers['x-user-id'] || null;
    if (typeof dbPool !== 'undefined' && dbPool) {
      await dbPool.query(
        `INSERT INTO workspace_members (workspace_id,user_id,role,invited_by)
         VALUES ($1,$2,$3,$4) ON CONFLICT (workspace_id,user_id) DO UPDATE SET role=EXCLUDED.role`,
        [workspaceId, userId, role, invitedBy]
      );
    }
    _logWsActivity(workspaceId, invitedBy, 'member.added', 'member', userId, { role });
    res.status(201).json({ ok: true, workspaceId, userId, role, ecosVersion: 'V158' });
  } catch (err) { res.status(400).json({ ok: false, error: err.message, ecosVersion: 'V158' }); }
});

