// ── [V158-T24] GET /api/v1/admin/ai-metrics/chart-data ────────────────────
app.get('/api/v1/admin/ai-metrics/chart-data', async (req, res) => {
  try {
    const pts = Math.min(Math.max(parseInt(req.query.points, 10) || 24, 6), 200);
    let series = [];
    if (typeof dbPool !== 'undefined' && dbPool) {
      const r = await dbPool.query(
        `SELECT snapshot_at,avg_confidence,pressure_rate,calib_accuracy,auto_calib_count
         FROM ai_metrics_snapshots ORDER BY snapshot_at DESC LIMIT $1`, [pts]
      );
      series = r.rows.reverse().map(row => ({
        ts: row.snapshot_at,
        avgConf: parseFloat(row.avg_confidence) || null,
        pressureRate: parseFloat(row.pressure_rate) || null,
        calibAccuracy: parseFloat(row.calib_accuracy) || null,
        autoCalibCount: parseInt(row.auto_calib_count, 10) || 0,
      }));
    }
    res.json({
      ok: true, points: series.length, series,
      bounds: { maxConf: Math.max(...series.map(p => p.avgConf || 0), 1), maxPressure: Math.max(...series.map(p => p.pressureRate || 0), 1) },
      chartMeta: { xLabel: 'Time', yLabels: ['Avg Confidence','Pressure Rate','Calib Accuracy'], colors: ['#22c55e','#f59e0b','#3b82f6'] },
      ecosVersion: 'V158',
    });
  } catch (err) { res.status(500).json({ ok: false, error: err.message, ecosVersion: 'V158' }); }
});

// ── [V158-T25] GET /api/v1/admin/ai-metrics/trends ────────────────────────
app.get('/api/v1/admin/ai-metrics/trends', async (req, res) => {
  try {
    const days = Math.min(parseInt(req.query.days, 10) || 7, 30);
    if (typeof dbPool !== 'undefined' && dbPool) {
      const r = await dbPool.query(
        `SELECT DATE_TRUNC('day',snapshot_at) AS day,
           AVG(avg_confidence)::numeric(5,4) AS avg_conf,
           AVG(pressure_rate)::numeric(5,4) AS avg_pressure,
           AVG(calib_accuracy)::numeric(5,4) AS avg_accuracy,
           SUM(auto_calib_count) AS total_calib, COUNT(*) AS snapshots
         FROM ai_metrics_snapshots
         WHERE snapshot_at >= NOW() - INTERVAL '1 day' * $1
         GROUP BY day ORDER BY day ASC`, [days]
      );
      return res.json({ ok: true, days, trend: r.rows, ecosVersion: 'V158' });
    }
    const current = _aiMetrics.getMetrics();
    res.json({ ok: true, days, trend: [{ day: new Date().toISOString().slice(0,10), ...current }], note: 'DB not connected', ecosVersion: 'V158' });
  } catch (err) { res.status(500).json({ ok: false, error: err.message, ecosVersion: 'V158' }); }
});

