      return res.status(400).json({ ok: false, error: 'max 200 per bulk update', ecosVersion: 'V158' });
    const updated = await Promise.all(taskIds.map(id => _wts.updateTask(workspaceId, id, { status }).catch(() => null)));
    res.json({ ok: true, updated: updated.filter(Boolean).length, total: taskIds.length, ecosVersion: 'V158' });
