// ── [V158-T35] GET /api/v1/workspaces/:workspaceId/tasks/assignee-breakdown ─
app.get('/api/v1/workspaces/:workspaceId/tasks/assignee-breakdown', async (req, res) => {
  try {
    const { workspaceId } = req.params;
    const result = await _wts.listTasks(workspaceId, { limit: 2000 });
    const byAssignee = {};
    for (const task of result.tasks) {
      const key = task.assigneeId || '_unassigned';
      if (!byAssignee[key]) byAssignee[key] = { count: 0, statuses: {}, tasks: [] };
      byAssignee[key].count++;
      byAssignee[key].statuses[task.status] = (byAssignee[key].statuses[task.status] || 0) + 1;
      if (byAssignee[key].tasks.length < 3) byAssignee[key].tasks.push({ id: task.id, title: task.title, status: task.status });
    }
    res.json({ ok: true, workspaceId, byAssignee, totalTasks: result.count, ecosVersion: 'V158' });
  } catch (err) { res.status(500).json({ ok: false, error: err.message, ecosVersion: 'V158' }); }
});

