// ── [V158-T42] GET /api/v1/workspaces/:workspaceId/tasks/timeline ──────────
app.get('/api/v1/workspaces/:workspaceId/tasks/timeline', async (req, res) => {
  try {
    const { workspaceId } = req.params;
    const result = await _wts.listTasks(workspaceId, { limit: 500 });
    const now = new Date();
    const withDue    = result.tasks.filter(t => t.dueAt).sort((a,b) => new Date(a.dueAt) - new Date(b.dueAt));
    const withoutDue = result.tasks.filter(t => !t.dueAt);
    const overdue    = withDue.filter(t => new Date(t.dueAt) < now && !['done','cancelled'].includes(t.status));
    const upcoming   = withDue.filter(t => new Date(t.dueAt) >= now);
    res.json({
      ok: true, workspaceId,
      timeline: { overdue, upcoming, noDueDate: withoutDue },
      counts: { overdue: overdue.length, upcoming: upcoming.length, noDueDate: withoutDue.length, total: result.count },
      ecosVersion: 'V158',
    });
  } catch (err) { res.status(500).json({ ok: false, error: err.message, ecosVersion: 'V158' }); }
});

// ── [V158-T43] GET /api/v1/admin/workspace-tasks/global-stats ─────────────
app.get('/api/v1/admin/workspace-tasks/global-stats', async (req, res) => {
  try {
    if (typeof dbPool !== 'undefined' && dbPool) {
      const r = await dbPool.query(
        `SELECT COUNT(*) AS total_tasks,
           COUNT(*) FILTER (WHERE status='done')         AS completed,
           COUNT(*) FILTER (WHERE status='in_progress')  AS in_progress,
           COUNT(*) FILTER (WHERE status='pending')      AS pending,
           COUNT(*) FILTER (WHERE status='blocked')      AS blocked,
           COUNT(*) FILTER (WHERE due_at<NOW() AND status NOT IN ('done','cancelled')) AS overdue,
           COUNT(DISTINCT workspace_id) AS workspace_count,
           COUNT(DISTINCT assignee_id) FILTER (WHERE assignee_id IS NOT NULL) AS assignee_count
         FROM workspace_tasks`
      );
      return res.json({ ok: true, global: r.rows[0], ecosVersion: 'V158' });
    }
    const dump = _wts.dump();
    let total=0, done=0, inProg=0, pending=0, blocked=0, overdue=0;
    const now = Date.now();
    for (const tasks of Object.values(dump)) {
      for (const t of tasks) {
        total++;
        if (t.status==='done') done++;
        if (t.status==='in_progress') inProg++;
        if (t.status==='pending') pending++;
        if (t.status==='blocked') blocked++;
        if (t.dueAt && new Date(t.dueAt).getTime()<now && !['done','cancelled'].includes(t.status)) overdue++;
      }
    }
    res.json({ ok: true, global: { total_tasks: total, completed: done, in_progress: inProg, pending, blocked, overdue, workspace_count: Object.keys(dump).length }, ecosVersion: 'V158' });
  } catch (err) { res.status(500).json({ ok: false, error: err.message, ecosVersion: 'V158' }); }
});

