// ── Task activity logger helper ─────────────────────────────────────────────
function _logTaskActivity(wsId, taskId, actorId, action, oldVal, newVal, meta) {
  if (typeof dbPool !== 'undefined' && dbPool) {
    dbPool.query(
      'INSERT INTO workspace_task_activity (workspace_id,task_id,actor_id,action,old_value,new_value,metadata) VALUES ($1,$2,$3,$4,$5,$6,$7)',
      [wsId, taskId, actorId, action,
       oldVal ? JSON.stringify(oldVal) : null,
       newVal ? JSON.stringify(newVal) : null,
       JSON.stringify(meta || {})]
    ).catch(() => {});
  }
}

// ── Due-soon checker ────────────────────────────────────────────────────────
function _checkDueSoon(workspaceId, leadHours) {
  const h      = parseInt(leadHours, 10) || 24;
  const now    = new Date();
  const cutoff = new Date(now.getTime() + h * 3600000);
  try {
    return [...(_wts._store && _wts._store.has(workspaceId) ? _wts._store.get(workspaceId).values() : [])]
      .filter(t => t.dueAt && !['done','cancelled'].includes(t.status) && new Date(t.dueAt) >= now && new Date(t.dueAt) <= cutoff)
      .map(t => t.toJSON());
  } catch (_) { return []; }
}

// ── CSV row splitter helper ─────────────────────────────────────────────────
function _splitCsvRow(row) {
  const result = []; let cur = ''; let inQ = false;
  for (let i = 0; i < row.length; i++) {
    const c = row[i];
    if (c === '"') { inQ = !inQ; continue; }
    if (c === ',' && !inQ) { result.push(cur); cur = ''; continue; }
    cur += c;
  }
  result.push(cur);
  return result;
}

