app.post('/api/v1/workspaces/:workspaceId/tasks/:taskId/auto-assign', async (req, res) => {
  try {
    const { workspaceId, taskId } = req.params;
    const { dryRun = false } = req.body || {};
    const task = await _wts.getTask(workspaceId, taskId);
    if (!task) return res.status(404).json({ ok: false, error: 'Task not found', ecosVersion: 'V159' });
    const routeResult = _vtRouter.autoAssign(task, { dryRun });
    if (!routeResult.ok) return res.status(422).json({ ok: false, ...routeResult, ecosVersion: 'V159' });
    if (!dryRun && routeResult.validator) {
      const updated = await _wts.assignTask(workspaceId, taskId, routeResult.validator.validatorId);
      _logTaskActivity(workspaceId, taskId, 'system', 'assigned', { assigneeId: task.assigneeId }, { assigneeId: routeResult.validator.validatorId }, { autoAssigned: true });
      _wsFeed.emitTaskAssigned(workspaceId, updated);
      _webhooks.dispatch(workspaceId, 'task.assigned', { task: updated, autoAssigned: true }).catch(() => {});
      if (typeof dbPool !== 'undefined' && dbPool) {
        dbPool.query('INSERT INTO validator_routing_log (id,task_id,workspace_id,validator_id,routing_score,task_tags,task_priority,dry_run) VALUES ($1,$2,$3,$4,$5,$6,$7,$8)',
          [routeResult.decision.id, taskId, workspaceId, routeResult.validator.validatorId, routeResult.decision.score, JSON.stringify(task.tags||[]), task.priority, false]).catch(() => {});
      }
    }
    res.json({ ok: true, ...routeResult, ecosVersion: 'V159' });
  } catch (err) { res.status(500).json({ ok: false, error: err.message, ecosVersion: 'V159' }); }
});

