// ── [V159-T27] PATCH /api/v1/workspaces/:workspaceId/tasks/tags/bulk ────────
app.patch('/api/v1/workspaces/:workspaceId/tasks/tags/bulk', async (req, res) => {
  try {
    const { workspaceId } = req.params;
    const { taskIds, addTags, removeTags } = req.body || {};
    if (!Array.isArray(taskIds)||taskIds.length===0) return res.status(400).json({ ok:false, error:'taskIds[] required', ecosVersion:'V159' });
    if (taskIds.length>200) return res.status(400).json({ ok:false, error:'max 200 tasks per bulk tag update', ecosVersion:'V159' });
    let updated=0;
    for (const taskId of taskIds) {
      const task = await _wts.getTask(workspaceId, taskId);
      if (!task) continue;
      let tags = [...(task.tags||[])];
      if (Array.isArray(addTags))    tags = [...new Set([...tags,...addTags])];
      if (Array.isArray(removeTags)) tags = tags.filter(t=>!removeTags.includes(t));
      await _wts.updateTask(workspaceId, taskId, { tags });
      updated++;
    }
    res.json({ ok:true, workspaceId, updated, total:taskIds.length, ecosVersion:'V159' });
  } catch (err) { res.status(400).json({ ok:false, error:err.message, ecosVersion:'V159' }); }
});

// ── [V159-T28] POST /api/v1/workspaces/:workspaceId/tasks/import ────────────
app.post('/api/v1/workspaces/:workspaceId/tasks/import', async (req, res) => {
  try {
    const { workspaceId } = req.params;
    const { csv, createdBy } = req.body || {};
    if (!csv) return res.status(400).json({ ok:false, error:'csv body required', ecosVersion:'V159' });
    const lines = csv.split('\n').map(l=>l.trim()).filter(Boolean);
    if (lines.length < 2) return res.status(400).json({ ok:false, error:'CSV must have header + at least 1 row', ecosVersion:'V159' });
    const headers = lines[0].split(',').map(h=>h.trim().toLowerCase());
    if (!headers.includes('title')) return res.status(400).json({ ok:false, error:'CSV header missing: title', ecosVersion:'V159' });
    const tasks = [];
    for (let i=1; i<Math.min(lines.length,501); i++) {
      const cols = _splitCsvRow(lines[i]);
      const row  = {};
      headers.forEach((h,idx)=>{ row[h]=(cols[idx]||'').trim(); });
      if (!row.title) continue;
      tasks.push({ title:row.title, description:row.description||'', status:row.status||'pending', priority:row.priority||'medium',
        assigneeId:row.assigneeid||null, dueAt:row.dueAt||row.due_at||null,
        tags:row.tags?row.tags.split('|').map(t=>t.trim()).filter(Boolean):[], createdBy:createdBy||null });
    }
    if (tasks.length===0) return res.status(400).json({ ok:false, error:'No valid tasks found in CSV', ecosVersion:'V159' });
    const result = await _wts.bulkCreate(workspaceId, tasks);
    result.tasks.forEach(t=>_wsFeed.emitTaskCreated(workspaceId,t));
    res.status(201).json({ ok:true, imported:result.created, tasks:result.tasks, ecosVersion:'V159' });
  } catch (err) { res.status(400).json({ ok:false, error:err.message, ecosVersion:'V159' }); }
});

