// ── [V159-T34] GET /api/v1/workspaces/:workspaceId/health-score ─────────────
app.get('/api/v1/workspaces/:workspaceId/health-score', async (req, res) => {
  try {
    const { workspaceId } = req.params;
    const stats  = await _wts.stats(workspaceId);
    const total  = stats.total || 0;
    if (total===0) return res.json({ ok:true, workspaceId, healthScore:100, grade:'A', breakdown:stats, ecosVersion:'V159' });
    const done    = stats.byStatus.done    || 0;
    const blocked = stats.byStatus.blocked || 0;
    const overdue = stats.overdue          || 0;
    const criticalPending = (stats.byPriority.critical||0) / total;
    let score = 100;
    score -= (overdue / total)        * 30;
    score -= (blocked / total)        * 20;
    score -= criticalPending          * 15;
    score += (done / total)           * 10;
    score = Math.max(0, Math.min(100, score));
    const rounded = Math.round(score);
    const grade   = rounded>=90?'A':rounded>=75?'B':rounded>=60?'C':rounded>=45?'D':'F';
    res.json({ ok:true, workspaceId, healthScore:rounded, grade, breakdown:{ total,done,blocked,overdue,completionRate:parseFloat((done/total).toFixed(3)) }, ecosVersion:'V159' });
  } catch (err) { res.status(500).json({ ok:false, error:err.message, ecosVersion:'V159' }); }
});

