app.get('/api/v1/deploy/check/v159', async (req, res) => {
  try {
    const checks = [
      { name:'WorkspaceTaskService',       ok:!!_wts,                  critical:true  },
      { name:'CalibrationHistoryService',  ok:!!_calibHistory,          critical:true  },
      { name:'WorkspaceSSEFeed',           ok:!!_wsFeed,                critical:true  },
      { name:'WebhookService',             ok:!!_webhooks,              critical:true  },
      { name:'ValidatorRouter',            ok:!!_vtRouter,              critical:true  },
      { name:'InvitationService',          ok:!!_invitations,           critical:true  },
      { name:'WEBHOOK_EVENTS_defined',     ok:Array.isArray(WEBHOOK_EVENTS)&&WEBHOOK_EVENTS.length>=10, critical:true },
      { name:'JWT_SECRET_set',             ok:!!process.env.JWT_SECRET, critical:false },
      { name:'DB_available',               ok:!!(typeof dbPool!=='undefined'&&dbPool), critical:false },
      { name:'Logger_configured',          ok:!!logger,                 critical:false },
      { name:'WS_TASK_STATUSES_v158',      ok:WS_TASK_STATUSES.length===6, critical:true },
      { name:'ValidatorRouter_config',     ok:typeof _vtRouter.minConfidence==='number', critical:true },
    ];
    const failed   = checks.filter(c=>!c.ok);
    const critical = failed.filter(c=>c.critical);
    const verdict  = critical.length===0 ? 'DEPLOY_READY' : 'DEPLOY_BLOCKED';
    res.status(critical.length===0?200:503).json({ ok:critical.length===0, verdict, version:'V159', phase:'P48',
      checks, failedChecks:failed, criticalFails:critical.length, checkedAt:new Date().toISOString(), ecosVersion:'V159' });
  } catch (err) { res.status(500).json({ ok:false, error:err.message, ecosVersion:'V159' }); }
});

