// ── [V160-T30] POST /api/v1/workspaces/:workspaceId/task-templates/bulk-instantiate ──
app.post('/api/v1/workspaces/:workspaceId/task-templates/bulk-instantiate', async (req, res) => {
  try {
    const { workspaceId } = req.params;
    const { templateIds, overrides } = req.body || {};
    if (!Array.isArray(templateIds) || templateIds.length === 0) {
      return res.status(400).json({ ok:false, error:'templateIds array required', ecosVersion:'V160' });
    }
    if (templateIds.length > 20) {
      return res.status(400).json({ ok:false, error:'Max 20 templates per bulk instantiate', ecosVersion:'V160' });
    }
    const results = [];
    for (const tplId of templateIds) {
      try {
        const r = await _templates.instantiate(workspaceId, tplId, (overrides && overrides[tplId]) || {});
        results.push({ templateId:tplId, ok:true, ...r });
      } catch (e) {
        results.push({ templateId:tplId, ok:false, error:e.message });
      }
    }
    const succeeded = results.filter(r=>r.ok).length;
    res.json({ ok:true, results, succeeded, failed:results.length-succeeded, ecosVersion:'V160' });
  } catch (err) { res.status(500).json({ ok:false, error:err.message, ecosVersion:'V160' }); }
});


// ═════════════════════════════════════════════════════════════════════════════
// BLOCK E — Calibration Chart API (T31–T34) — extends CalibrationHistoryService
// ═════════════════════════════════════════════════════════════════════════════

// ── [V160-T31] GET /api/v1/calibration/:calibratorId/history/chart ───────────
app.get('/api/v1/calibration/:calibratorId/history/chart', async (req, res) => {
  try {
    const { calibratorId } = req.params;
    const range = req.query.range || '7d';
    const rangeDays = range === '90d' ? 90 : range === '30d' ? 30 : 7;
    const cutoff    = new Date(Date.now() - rangeDays * 86400000);

    const { records } = await _calibHistory.list({ limit: 1000 });
    const filtered = records.filter(r => new Date(r.fittedAt) >= cutoff);

    // Bucket by day
    const buckets = {};
    for (const r of filtered) {
      const day = r.fittedAt.slice(0, 10);
      if (!buckets[day]) buckets[day] = { date:day, brier:[], auc:[], accuracy:[], sampleCount:0 };
      buckets[day].brier.push(r.brier);
      buckets[day].auc.push(r.auc);
      buckets[day].accuracy.push(r.accuracy);
      buckets[day].sampleCount += r.sampleCount || 0;
    }

    const avg = arr => arr.length ? parseFloat((arr.reduce((s,v)=>s+v,0)/arr.length).toFixed(4)) : null;
    const series = Object.values(buckets)
      .sort((a,b)=>a.date.localeCompare(b.date))
      .map(b => ({
        date:        b.date,
        avgBrier:    avg(b.brier),
        avgAuc:      avg(b.auc),
        avgAccuracy: avg(b.accuracy),
        sampleCount: b.sampleCount,
        dataPoints:  b.brier.length,
      }));

    res.json({ ok:true, calibratorId, range, rangeDays, series, totalPoints:filtered.length, ecosVersion:'V160' });
  } catch (err) { res.status(500).json({ ok:false, error:err.message, ecosVersion:'V160' }); }
});

// ── [V160-T32] GET /api/v1/calibration/:calibratorId/history/rolling ─────────
app.get('/api/v1/calibration/:calibratorId/history/rolling', async (req, res) => {
  try {
    const { calibratorId } = req.params;
    const window = parseInt(req.query.window, 10) || 7;
    const { records } = await _calibHistory.list({ limit: window * 2 + 10 });
    const latest = records.slice(0, window);
    const avg = key => latest.length ? parseFloat((latest.reduce((s,r)=>s+(r[key]||0),0)/latest.length).toFixed(4)) : null;
    res.json({ ok:true, calibratorId, window, avgBrier:avg('brier'), avgAuc:avg('auc'), avgAccuracy:avg('accuracy'),
      sampleCount: latest.reduce((s,r)=>s+(r.sampleCount||0),0), points:latest.length, ecosVersion:'V160' });
  } catch (err) { res.status(500).json({ ok:false, error:err.message, ecosVersion:'V160' }); }
});

// ── [V160-T33] GET /api/v1/admin/calibration/comparison ──────────────────────
app.get('/api/v1/admin/calibration/comparison', async (req, res) => {
  try {
    const { period1 = '7d', period2 = '30d' } = req.query;
    const toDays  = p => p === '90d' ? 90 : p === '30d' ? 30 : 7;
    const { records } = await _calibHistory.list({ limit: 2000 });
    const now = Date.now();
    const slice = (days) => records.filter(r => new Date(r.fittedAt).getTime() >= now - days*86400000);
    const stats = (recs) => {
      if (!recs.length) return null;
      const avg = k => parseFloat((recs.reduce((s,r)=>s+(r[k]||0),0)/recs.length).toFixed(4));
      return { count:recs.length, avgBrier:avg('brier'), avgAuc:avg('auc'), avgAccuracy:avg('accuracy') };
    };
    res.json({ ok:true, period1:{ range:period1, stats:stats(slice(toDays(period1))) }, period2:{ range:period2, stats:stats(slice(toDays(period2))) }, ecosVersion:'V160' });
  } catch (err) { res.status(500).json({ ok:false, error:err.message, ecosVersion:'V160' }); }
});

// ── [V160-T34] GET /api/v1/admin/calibration/outliers ────────────────────────
app.get('/api/v1/admin/calibration/outliers', async (req, res) => {
  try {
    const threshold = parseFloat(req.query.brierThreshold) || 0.3;
    const { records } = await _calibHistory.list({ limit: 1000 });
    const outliers   = records.filter(r => (r.brier||0) > threshold);
    res.json({ ok:true, threshold, outliers, count:outliers.length, total:records.length, ecosVersion:'V160' });
  } catch (err) { res.status(500).json({ ok:false, error:err.message, ecosVersion:'V160' }); }
});


