// ── [V160-T40] GET /api/v1/workspaces/:workspaceId/tasks/:taskId/full-context ──
// Returns task + its dependencies + watchers + SLA status (integration endpoint)
app.get('/api/v1/workspaces/:workspaceId/tasks/:taskId/full-context', async (req, res) => {
  try {
    const { workspaceId, taskId } = req.params;
    const task = await _wts.getTask(workspaceId, taskId);
    if (!task) return res.status(404).json({ ok:false, error:'Task not found', ecosVersion:'V160' });

    const [depResult, blockResult] = await Promise.all([
      _deps.getDependencies(workspaceId, taskId),
      _deps.isTaskBlocked(workspaceId, taskId, async (id) => {
        const t = await _wts.getTask(workspaceId, id);
        return t ? t.status : 'unknown';
      }),
    ]);

    const ageMs    = Date.now() - new Date(task.createdAt).getTime();
    const ageHours = parseFloat((ageMs/3600000).toFixed(2));
    const slaMap   = { critical:4, high:24, medium:72, low:168 };
    const slaHours = slaMap[task.priority]||72;
    const slaStatus = {
      ageHours, slaHours,
      breached: !['done','cancelled'].includes(task.status) && ageHours > slaHours,
      remaining: parseFloat(Math.max(0, slaHours - ageHours).toFixed(2)),
    };

    res.json({ ok:true, task, dependencies:depResult, blockStatus:blockResult, sla:slaStatus, ecosVersion:'V160' });
  } catch (err) { res.status(500).json({ ok:false, error:err.message, ecosVersion:'V160' }); }
});

// ── [V160-T41] GET /api/v1/workspaces/:workspaceId/health-score/v160 ─────────
// Enhanced health score factoring in quota usage + dependency health
app.get('/api/v1/workspaces/:workspaceId/health-score/v160', async (req, res) => {
  try {
    const { workspaceId } = req.params;
    const stats    = await _wts.stats(workspaceId);
    const total    = stats.total || 0;
    if (total === 0) return res.json({ ok:true, workspaceId, healthScore:100, grade:'A', ecosVersion:'V160' });

    const done      = stats.byStatus.done    || 0;
    const blocked   = stats.byStatus.blocked || 0;
    const overdue   = stats.overdue          || 0;
    const critPend  = (stats.byPriority.critical||0) / total;
    const depStats  = _deps.stats(workspaceId);
    const depRatio  = total > 0 ? depStats.totalDependencies / total : 0;

    let score = 100;
    score -= (overdue / total) * 30;
    score -= (blocked / total) * 20;
    score -= critPend          * 15;
    score += (done / total)    * 10;
    score -= Math.max(0, depRatio - 1) * 5; // penalty if too many deps per task
    score  = Math.max(0, Math.min(100, score));

    const rounded = Math.round(score);
    const grade   = rounded>=90?'A':rounded>=75?'B':rounded>=60?'C':rounded>=45?'D':'F';
    res.json({ ok:true, workspaceId, healthScore:rounded, grade,
      breakdown:{ total, done, blocked, overdue, completionRate:parseFloat((done/total).toFixed(3)), depCount:depStats.totalDependencies },
      ecosVersion:'V160' });
  } catch (err) { res.status(500).json({ ok:false, error:err.message, ecosVersion:'V160' }); }
});

