// ── [V160-T44] POST /api/v1/workspaces/:workspaceId/tasks/bulk-assign ────────
app.post('/api/v1/workspaces/:workspaceId/tasks/bulk-assign', async (req, res) => {
  try {
    const { workspaceId } = req.params;
    const { taskIds, assigneeId } = req.body || {};
    if (!Array.isArray(taskIds) || !assigneeId) {
      return res.status(400).json({ ok:false, error:'taskIds array and assigneeId required', ecosVersion:'V160' });
    }
    if (taskIds.length > 500) return res.status(400).json({ ok:false, error:'Max 500 tasks per bulk-assign', ecosVersion:'V160' });
    let updated = 0, failed = 0;
    for (const id of taskIds) {
      try {
        await _wts.assignTask(workspaceId, id, assigneeId);
        updated++;
      } catch (_) { failed++; }
    }
    res.json({ ok:true, workspaceId, assigneeId, requested:taskIds.length, updated, failed, ecosVersion:'V160' });
  } catch (err) { res.status(500).json({ ok:false, error:err.message, ecosVersion:'V160' }); }
});

