// ── [V161-T01] POST /api/v1/workspaces/:workspaceId/labels ────────────────
app.post('/api/v1/workspaces/:workspaceId/labels', async (req, res) => {
  try {
    const { workspaceId } = req.params;
    const { name, color, description, createdBy } = req.body || {};
    if (!name) return res.status(400).json({ ok:false, error:'name is required', ecosVersion:'V161' });
    const label = await _labels.createLabel(workspaceId, { name, color, description, createdBy });
    await _auditTrail.record(workspaceId, 'label.created', { actorId: createdBy, targetId: label.id, targetType: 'label', payload: label.toJSON() });
    res.status(201).json({ ok:true, label: label.toJSON(), ecosVersion:'V161' });
  } catch (err) { res.status(500).json({ ok:false, error:err.message, ecosVersion:'V161' }); }
});

