// ═════════════════════════════════════════════════════════════════════════════
// BLOCK B — V164 Enhanced Label Filtering (V164-T06 … V164-T07)
// ═════════════════════════════════════════════════════════════════════════════

// ── [V164-T06] GET /api/v1/workspaces/:workspaceId/tasks/by-labels
// AND-logic multi-label filter: ?labelId[]=lbl_1&labelId[]=lbl_2
// Returns only tasks that have ALL specified labels applied
app.get('/api/v1/workspaces/:workspaceId/tasks/by-labels', async (req, res) => {
  try {
    const { workspaceId } = req.params;
    // labelId may come as array or single string
    let labelIds = req.query['labelId[]'] || req.query.labelId || [];
    if (typeof labelIds === 'string') labelIds = [labelIds];
    labelIds = labelIds.filter(Boolean);

    if (labelIds.length === 0) {
      return res.status(400).json({ ok: false, error: 'At least one labelId[] required', ecosVersion: 'V164' });
    }
    const limit = Math.min(parseInt(req.query.limit || '50', 10), 200);

    // DB path — AND join across workspace_task_labels
    if (typeof dbPool !== 'undefined' && dbPool) {
      try {
        // Find taskIds that have ALL requested labels (AND logic via GROUP BY + HAVING COUNT)
        const placeholders = labelIds.map((_, i) => `$${i + 2}`).join(', ');
        const sql = `
          SELECT task_id
            FROM workspace_task_labels
           WHERE workspace_id = $1
             AND label_id IN (${placeholders})
           GROUP BY task_id
          HAVING COUNT(DISTINCT label_id) = ${labelIds.length}
           LIMIT $${labelIds.length + 2}
        `;
        const params = [workspaceId, ...labelIds, limit];
        const r = await dbPool.query(sql, params);
        const taskIds = r.rows.map(row => row.task_id);

        // Fetch task records
        const tasks = [];
        for (const taskId of taskIds) {
          try {
            const task = await _wts.getTask(workspaceId, taskId);
            if (task) tasks.push(task);
          } catch (_) { /* task may not exist in memory */ }
        }
        return res.json({ ok: true, tasks, count: tasks.length, labelIds, logic: 'AND', ecosVersion: 'V164' });
      } catch (dbErr) {
        logger.warn({ err: dbErr.message }, '[V164-T06] DB label filter failed, falling back');
      }
    }

    // In-memory fallback via _labels service
    try {
      // Get task→label assignments per label, then intersect
      const labelTaskSets = await Promise.all(
        labelIds.map(async (labelId) => {
          const assignments = await _labels.getTasksForLabel(workspaceId, labelId).catch(() => []);
          return new Set(assignments.map(a => a.taskId || a.task_id || a));
        })
      );

      // Intersection of all sets
      let intersection = labelTaskSets[0] || new Set();
      for (let i = 1; i < labelTaskSets.length; i++) {
        intersection = new Set([...intersection].filter(id => labelTaskSets[i].has(id)));
      }

      const taskIds = [...intersection].slice(0, limit);
      const tasks = [];
      for (const taskId of taskIds) {
        try {
          const task = await _wts.getTask(workspaceId, taskId);
          if (task) tasks.push(task);
        } catch (_) {}
      }
      return res.json({ ok: true, tasks, count: tasks.length, labelIds, logic: 'AND', ecosVersion: 'V164' });
    } catch (memErr) {
      return res.status(500).json({ ok: false, error: memErr.message, ecosVersion: 'V164' });
    }
  } catch (err) {
    res.status(500).json({ ok: false, error: err.message, ecosVersion: 'V164' });
  }
});

// ── [V164-T07] GET /api/v1/workspaces/:workspaceId/labels/:labelId/tasks
// List all tasks that have a specific label applied (single-label convenience)
app.get('/api/v1/workspaces/:workspaceId/labels/:labelId/tasks', async (req, res) => {
  try {
    const { workspaceId, labelId } = req.params;
    const limit = Math.min(parseInt(req.query.limit || '50', 10), 200);

    if (typeof dbPool !== 'undefined' && dbPool) {
      try {
        const r = await dbPool.query(
          `SELECT task_id FROM workspace_task_labels
            WHERE workspace_id = $1 AND label_id = $2
            ORDER BY applied_at DESC LIMIT $3`,
          [workspaceId, labelId, limit],
        );
        const taskIds = r.rows.map(row => row.task_id);
        const tasks = [];
        for (const taskId of taskIds) {
          try {
            const task = await _wts.getTask(workspaceId, taskId);
            if (task) tasks.push(task);
          } catch (_) {}
        }
        return res.json({ ok: true, tasks, count: tasks.length, labelId, ecosVersion: 'V164' });
      } catch (dbErr) {
        logger.warn({ err: dbErr.message }, '[V164-T07] DB failed, falling back');
      }
    }

    // In-memory fallback
    const assignments = await _labels.getTasksForLabel(workspaceId, labelId).catch(() => []);
    const taskIds = assignments.map(a => a.taskId || a.task_id || a).slice(0, limit);
    const tasks = [];
    for (const taskId of taskIds) {
      try {
        const task = await _wts.getTask(workspaceId, taskId);
        if (task) tasks.push(task);
      } catch (_) {}
    }
    res.json({ ok: true, tasks, count: tasks.length, labelId, ecosVersion: 'V164' });
  } catch (err) {
    res.status(500).json({ ok: false, error: err.message, ecosVersion: 'V164' });
  }
});


