// ── [V167-T01] GET /api/v1/workspaces/:workspaceId/activity
// Paginated activity feed for a workspace
app.get('/api/v1/workspaces/:workspaceId/activity', async (req, res) => {
  try {
    const { workspaceId } = req.params;
    const { limit, after, before, actorId, since, until } = req.query;
    const types = req.query['types[]']
      ? (Array.isArray(req.query['types[]']) ? req.query['types[]'] : [req.query['types[]']])
      : (req.query.types ? (Array.isArray(req.query.types) ? req.query.types : [req.query.types]) : undefined);
    const result = await _activityFeed.getActivityFeed(workspaceId, {
      limit: limit ? parseInt(limit, 10) : undefined,
      after, before, types, actorId, since, until,
    });
    res.json({ ok: true, ...result, workspaceId, ecosVersion: 'V167' });
  } catch (err) {
    const sc = err.statusCode || 500;
    res.status(sc).json({ ok: false, error: err.message, ecosVersion: 'V167' });
  }
});

