// ── V168: require services ────────────────────────────────────────────────
const {
  CustomFieldBulkUpdateService,
  BulkUpdateValidationError,
  BulkUpdateFieldNotFoundError,
} = require('./lib/customFieldBulkUpdateService');

const {
  ValidatorPerformanceDashboardService,
  ValidatorPerfValidationError,
  ValidatorNotFoundError,
} = require('./lib/validatorPerformanceDashboardService');

const _cfBulk    = new CustomFieldBulkUpdateService({ pool: null, dbEnabled: false });
const _validPerf = new ValidatorPerformanceDashboardService({ pool: null, dbEnabled: false });


// ═════════════════════════════════════════════════════════════════════════════
// BLOCK A — V168 Custom Field Bulk Update (V168-T01 … V168-T02)
// ═════════════════════════════════════════════════════════════════════════════

// ── [V168-T01] POST /api/v1/workspaces/:workspaceId/custom-fields/:fieldId/bulk-set
// Bulk-set a custom field value on multiple tasks in one request
app.post('/api/v1/workspaces/:workspaceId/custom-fields/:fieldId/bulk-set', async (req, res) => {
  try {
    const { workspaceId, fieldId } = req.params;
    const { taskIds, value, fieldSchema } = req.body || {};

    if (!taskIds) return res.status(400).json({ ok: false, error: 'taskIds required', ecosVersion: 'V168' });

    // Allow caller to supply fieldSchema for in-memory / test environments
    if (fieldSchema) {
      _cfBulk.registerFieldSchema(workspaceId, { id: fieldId, ...fieldSchema });
    }

    const result = await _cfBulk.bulkSetField(workspaceId, fieldId, taskIds, value);
    const statusCode = result.totalFailed === 0 ? 200 : 207; // 207 Multi-Status on partial failure
    res.status(statusCode).json({ ok: true, ...result, ecosVersion: 'V168' });
  } catch (err) {
    const sc = err.statusCode || 500;
    res.status(sc).json({ ok: false, error: err.message, ecosVersion: 'V168' });
  }
});

// ── [V168-T02] GET /api/v1/workspaces/:workspaceId/tasks/:taskId/custom-fields/:fieldId
// Get current value of a custom field on a task
app.get('/api/v1/workspaces/:workspaceId/tasks/:taskId/custom-fields/:fieldId', (req, res) => {
  try {
    const { workspaceId, taskId, fieldId } = req.params;
    const entry = _cfBulk.getFieldValue(workspaceId, taskId, fieldId);
    if (!entry) return res.status(404).json({ ok: false, error: 'No value set for this field/task', ecosVersion: 'V168' });
    res.json({ ok: true, entry, ecosVersion: 'V168' });
  } catch (err) {
    res.status(500).json({ ok: false, error: err.message, ecosVersion: 'V168' });
  }
});


