// ── [V173-T01] GET /api/v1/workspaces/:workspaceId/tasks/:taskId/recurrence
// Get the recurrence rule for a specific task (canonical, via V162 service)
app.get('/api/v1/workspaces/:workspaceId/tasks/:taskId/recurrence', async (req, res) => {
  try {
    const { workspaceId, taskId } = req.params;
    const rule = await _recurrence.getRecurrence(workspaceId, taskId);
    const ruleJSON = typeof rule.toJSON === 'function' ? rule.toJSON() : rule;
    res.json({ ok: true, rule: ruleJSON, ecosVersion: 'V173' });
  } catch (err) {
    const sc = err.statusCode || 500;
    res.status(sc).json({ ok: false, error: err.message, ecosVersion: 'V173' });
  }
});


