// ── V171: require workspaceNotificationService ───────────────────────────────
const {
  WorkspaceNotificationService,
  NotificationValidationError,
  NotificationNotFoundError,
  NotificationLimitError,
} = require('./lib/workspaceNotificationService');

const _wsNotif = new WorkspaceNotificationService({ pool: null, dbEnabled: false });

// ── V171: re-use existing TaskDependencyService (already required above) ──────
// _deps is the singleton already in scope from V160 require block.

// ─────────────────────────────────────────────────────────────────────────────
// BLOCK A — V171 Task Dependencies per-task REST (T01–T04)
// ─────────────────────────────────────────────────────────────────────────────

// ── [V171-T01] POST /api/v1/workspaces/:workspaceId/tasks/:taskId/dependencies
// Add a dependency (taskId depends on dependsOnId)
app.post('/api/v1/workspaces/:workspaceId/tasks/:taskId/dependencies', async (req, res) => {
  try {
    const { workspaceId, taskId } = req.params;
    const { dependsOnId, type, createdBy } = req.body || {};
    if (!dependsOnId) return res.status(400).json({ ok: false, error: 'dependsOnId required', ecosVersion: 'V171' });

    const result = await _deps.addDependency(workspaceId, taskId, dependsOnId, { type, createdBy });
    const status = result.alreadyExists ? 200 : 201;
    res.status(status).json({ ok: true, ...result, ecosVersion: 'V171' });
  } catch (err) {
    const s = err.statusCode || (err.code === 'CYCLIC_DEPENDENCY' ? 409 : 500);
    res.status(s).json({ ok: false, error: err.message, code: err.code, ecosVersion: 'V171' });
  }
});

// ── [V171-T02] GET /api/v1/workspaces/:workspaceId/tasks/:taskId/dependencies
// List dependencies for a task (what it depends on + what depends on it)
app.get('/api/v1/workspaces/:workspaceId/tasks/:taskId/dependencies', async (req, res) => {
  try {
    const { workspaceId, taskId } = req.params;
    const { includeTree } = req.query;

    const deps = await _deps.getDependencies(workspaceId, taskId);
    const blocked = await _deps.isTaskBlocked(workspaceId, taskId, null);

    let tree = null;
    if (includeTree === 'true') {
      tree = await _deps.getDependencyTree(workspaceId, taskId);
    }

    res.json({ ok: true, ...deps, isBlocked: blocked.blocked, blockers: blocked.blockers, tree, ecosVersion: 'V171' });
  } catch (err) {
    res.status(err.statusCode || 500).json({ ok: false, error: err.message, ecosVersion: 'V171' });
  }
});

// ── [V171-T03] DELETE /api/v1/workspaces/:workspaceId/tasks/:taskId/dependencies/:depId
// Remove a specific dependency (depId = the dependsOnId task)
app.delete('/api/v1/workspaces/:workspaceId/tasks/:taskId/dependencies/:depId', async (req, res) => {
  try {
    const { workspaceId, taskId, depId } = req.params;
    const removed = await _deps.removeDependency(workspaceId, taskId, depId);
    if (!removed) return res.status(404).json({ ok: false, error: 'Dependency not found', ecosVersion: 'V171' });
    res.json({ ok: true, deleted: true, dependency: removed, ecosVersion: 'V171' });
  } catch (err) {
    res.status(err.statusCode || 500).json({ ok: false, error: err.message, ecosVersion: 'V171' });
  }
});

// ── [V171-T04] GET /api/v1/workspaces/:workspaceId/tasks/:taskId/dependencies/blocked
// Quick boolean: is this task currently blocked?
app.get('/api/v1/workspaces/:workspaceId/tasks/:taskId/dependencies/blocked', async (req, res) => {
  try {
    const { workspaceId, taskId } = req.params;
    const result = await _deps.isTaskBlocked(workspaceId, taskId, null);
    res.json({ ok: true, taskId, ...result, ecosVersion: 'V171' });
  } catch (err) {
    res.status(err.statusCode || 500).json({ ok: false, error: err.message, ecosVersion: 'V171' });
  }
});

