// BLOCK B — V171 Workspace Notifications Center (T05–T09)
// ─────────────────────────────────────────────────────────────────────────────

// ── [V171-T05] POST /api/v1/workspaces/:workspaceId/notifications
// Create a notification for a user
app.post('/api/v1/workspaces/:workspaceId/notifications', async (req, res) => {
  try {
    const { workspaceId } = req.params;
    const { userId, title, body, type, meta, createdBy } = req.body || {};
    const notif = await _wsNotif.createNotification(workspaceId, { userId, title, body, type, meta, createdBy });
    res.status(201).json({ ok: true, notification: notif.toJSON(), ecosVersion: 'V171' });
  } catch (err) {
    const s = err.statusCode || 500;
    res.status(s).json({ ok: false, error: err.message, code: err.code, ecosVersion: 'V171' });
  }
});

// ── [V171-T06] GET /api/v1/workspaces/:workspaceId/notifications
// List notifications for calling user (userId required via query)
app.get('/api/v1/workspaces/:workspaceId/notifications', async (req, res) => {
  try {
    const { workspaceId } = req.params;
    const { userId, unreadOnly, limit, offset } = req.query;
    if (!userId) return res.status(400).json({ ok: false, error: 'userId query param required', ecosVersion: 'V171' });

    const result = await _wsNotif.listNotifications(workspaceId, userId, {
      unreadOnly: unreadOnly === 'true',
      limit:      limit  ? parseInt(limit,  10) : 50,
      offset:     offset ? parseInt(offset, 10) : 0,
    });
    res.json({ ok: true, ...result, ecosVersion: 'V171' });
  } catch (err) {
    res.status(err.statusCode || 500).json({ ok: false, error: err.message, ecosVersion: 'V171' });
  }
});

// ── [V171-T07] PATCH /api/v1/workspaces/:workspaceId/notifications/:notifId/read
// Mark a single notification as read
app.patch('/api/v1/workspaces/:workspaceId/notifications/:notifId/read', async (req, res) => {
  try {
    const { workspaceId, notifId } = req.params;
    const { userId } = req.body || {};
    if (!userId) return res.status(400).json({ ok: false, error: 'userId required', ecosVersion: 'V171' });
    const notif = await _wsNotif.markRead(workspaceId, userId, notifId);
    res.json({ ok: true, notification: notif.toJSON(), ecosVersion: 'V171' });
  } catch (err) {
    res.status(err.statusCode || 500).json({ ok: false, error: err.message, code: err.code, ecosVersion: 'V171' });
  }
});

