// ── [V176-T01] POST /api/v1/workspaces/:workspaceId/tasks/:taskId/watchers ──
// Add a watcher to a task. Idempotent. Body: { userId }
app.post('/api/v1/workspaces/:workspaceId/tasks/:taskId/watchers', async (req, res) => {
  try {
    const { workspaceId, taskId } = req.params;
    const { userId } = req.body || {};
    if (!userId) return res.status(400).json({ ok: false, error: 'userId required', ecosVersion: 'V176' });
    const { watcher, created } = await _taskWatcher.watch(taskId, workspaceId, userId);
    const status = created ? 201 : 200;
    res.status(status).json({ ok: true, taskId, workspaceId, watcher: watcher.toJSON(), created, ecosVersion: 'V176' });
  } catch (err) {
    const sc = err.statusCode || 500;
    res.status(sc).json({ ok: false, error: err.message, code: err.code || 'ERROR', ecosVersion: 'V176' });
  }
});

// ── [V176-T02] DELETE /api/v1/workspaces/:workspaceId/tasks/:taskId/watchers ─
// Remove a watcher from a task. Query param: ?userId= or body: { userId }
app.delete('/api/v1/workspaces/:workspaceId/tasks/:taskId/watchers', async (req, res) => {
  try {
    const { workspaceId, taskId } = req.params;
    const userId = req.query.userId || (req.body || {}).userId;
    if (!userId) return res.status(400).json({ ok: false, error: 'userId required', ecosVersion: 'V176' });
    const { removed } = await _taskWatcher.unwatch(taskId, userId);
    res.json({ ok: true, taskId, workspaceId, userId, removed, ecosVersion: 'V176' });
  } catch (err) {
    const sc = err.statusCode || 500;
    res.status(sc).json({ ok: false, error: err.message, code: err.code || 'ERROR', ecosVersion: 'V176' });
  }
});

