// This is the service-backed version of V158-T17.
app.post('/api/v1/workspaces/:workspaceId/members/v2', async (req, res) => {
  try {
    const { workspaceId } = req.params;
    const { userId, role, addedBy } = req.body || {};
    if (!userId) return res.status(400).json({ ok: false, error: 'userId required', ecosVersion: 'V176' });
    const { member, created } = await _memberSvc.addMember(workspaceId, userId, { role, addedBy: addedBy || req.headers['x-user-id'] || null });
    const status = created ? 201 : 200;
    res.status(status).json({ ok: true, member: member.toJSON(), created, ecosVersion: 'V176' });
  } catch (err) {
    const sc = err.statusCode || 500;
    res.status(sc).json({ ok: false, error: err.message, code: err.code || 'ERROR', ecosVersion: 'V176' });
  }
});

