// V177 — Rate-Limit Middleware · Search Cursor Pagination · Audit CSV Export
// Phase P66  |  Author: AI  |  Date: 2026-05-30
// Endpoints:  V177-T01 … V177-T04
// Changes:
//   - V177-T01: Express middleware on /api/v1/workspaces/* (per-workspace rate limit)
//   - V177-T02: Cursor pagination on GET /workspaces/:id/search (extends V172-T01)
//   - V177-T03: Audit export CSV (extends V175-T03, replaces 501 stub with RFC 4180)
//   - V177-T04: GET /admin/summary/v177
// Notes:
//   - V177-T02 and V177-T03 are implemented as in-place upgrades of existing routes.
//   - Rate-limit middleware (V177-T01) applies to routes registered from V177 onwards.
//     Pre-V177 workspace routes are protected by the existing per-IP rate limiters.
//   - Sacred files: lib/fiatLedger.js · lib/auditLog.js — UNTOUCHED (R1)
// ═════════════════════════════════════════════════════════════════════════════

// ── V177: configure rate-limiter singleton (honours env vars) ─────────────────
// WORKSPACE_RATE_LIMIT_CAPACITY — max tokens per workspace bucket (default 60)
// WORKSPACE_RATE_LIMIT_REFILL   — tokens added per refill window (default 60)
const _rl177Capacity = parseInt(process.env.WORKSPACE_RATE_LIMIT_CAPACITY || '60', 10) || 60;
const _rl177Refill   = parseInt(process.env.WORKSPACE_RATE_LIMIT_REFILL   || '60', 10) || 60;
const _wsRateLimiter177 = new WorkspaceRateLimiterService({
  capacity:       _rl177Capacity,
  refillRate:     _rl177Refill,
  refillWindowMs: 60_000,
});

// ── [V177-T01] Per-workspace rate-limit middleware ────────────────────────────
// Applied to all /api/v1/workspaces/* routes registered from V177 onwards.
// Returns HTTP 429 + Retry-After header when per-workspace token bucket is empty.
// workspaceId is extracted from the URL path after the /workspaces/ prefix.
app.use('/api/v1/workspaces', (req, res, next) => {
  // req.url is path-relative (prefix stripped by Express): e.g. /ws123/tasks/search
  const segs = req.url.replace(/\?.*$/, '').split('/').filter(Boolean);
  const workspaceId = segs[0];
  if (!workspaceId) return next();

  const result = _wsRateLimiter177.check(workspaceId);
  if (!result.allowed) {
    const retryAfterSec = Math.max(1, Math.ceil((result.resetAt.getTime() - Date.now()) / 1000));
    res.setHeader('Retry-After', String(retryAfterSec));
    return res.status(429).json({
      ok:             false,
      error:          'Rate limit exceeded for this workspace',
      retryAfterSec,
      resetAt:        result.resetAt.toISOString(),
      remaining:      result.remaining,
      workspaceId,
      code:           'WORKSPACE_RATE_LIMITED',
      ecosVersion:    'V177',
    });
  }
  next();
});

// ── [V177-T04] GET /api/v1/admin/summary/v177 ────────────────────────────────
app.get('/api/v1/admin/summary/v177', (req, res) => {
  const rl177Stats = _wsRateLimiter177.stats();
  res.json({
    ok:      true,
    version: 'V177',
    phase:   'P66',
    features: [
      'workspace-rate-limit-middleware',
      'search-cursor-pagination',
      'audit-export-csv',
    ],
    endpoints: [
      'V177-T01 middleware /api/v1/workspaces/* (rate limit)',
      'V177-T02 GET /workspaces/:id/search (cursor pagination extends V172-T01)',
      'V177-T03 GET /workspaces/:id/audit/export?format=csv (extends V175-T03)',
      'V177-T04 GET /admin/summary/v177',
    ],
    config: {
      rateLimitCapacity: _rl177Capacity,
      rateLimitRefill:   _rl177Refill,
      rateLimitWindow:   '60s',
    },
    stats: {
      rateLimiter177: {
        activeBuckets:  rl177Stats.activeBuckets,
        totalRequests:  rl177Stats.totalRequests,
        rejectedRequests: rl177Stats.rejectedRequests,
      },
    },
    ecosVersion: 'V177',
  });
});

// ── V177: export for tests ────────────────────────────────────────────────────
if (process.env.NODE_ENV === 'test') {
  module.exports._wsRateLimiter177    = _wsRateLimiter177;
  module.exports.WorkspaceRateLimiterService177 = WorkspaceRateLimiterService;
  module.exports._rl177Capacity       = _rl177Capacity;
  module.exports._rl177Refill         = _rl177Refill;
}


  // ═════════════════════════════════════════════════════════════════════════════
  // V178 — WebSocket Heartbeat · Bulk Event Ingestion · Search Relevance · Admin
  // Phase P67  |  Author: AI  |  Date: 2026-05-30
  // Endpoints:  V178-T01 … V178-T07
  // Changes:
  //   - V178-T01: WorkspaceHeartbeatService (lib/workspaceHeartbeatService.js)
  //   - V178-T02: POST /workspaces/:id/heartbeat  (register / update heartbeat)
  //   - V178-T03: DELETE /workspaces/:id/heartbeat  (disconnect)
  //   - V178-T04: GET /workspaces/:id/heartbeat  (get heartbeat status)
  //   - V178-T05: GET /admin/heartbeats  (admin list of active workspaces)
  //   - V178-T06: POST /workspaces/:id/events/bulk  (up to 100 events per call)
  //   - V178-T07: GET /admin/summary/v178
  //   - V178-T03 search: relevance scoring + sortBy param (in-place upgrade of V172/V177 route)
  // Notes:
  //   - Sacred files: lib/fiatLedger.js · lib/auditLog.js — UNTOUCHED (R1)
  //   - Zero new npm deps (R6): workspaceHeartbeatService uses only Node built-ins
  //   - All V177/V176/V175 exports preserved (R8)
  // ═════════════════════════════════════════════════════════════════════════════

  // ── V178-T01: Load heartbeat service ─────────────────────────────────────────
  const {
    WorkspaceHeartbeatService,
    HeartbeatValidationError,
    defaultHeartbeatService: _heartbeatSvc,
  } = require('./lib/workspaceHeartbeatService.js');

  // V178 heartbeat singleton with environment-configurable TTL
  const _hb178StaleTtl = parseInt(process.env.WORKSPACE_HEARTBEAT_TTL_MS || '60000', 10) || 60_000;
  const _heartbeat178  = new WorkspaceHeartbeatService({ staleTtlMs: _hb178StaleTtl });

  // ── [V178-T02] POST /api/v1/workspaces/:workspaceId/heartbeat ────────────────
  // Register or update a heartbeat ping for the given workspace.
  // Body (optional JSON): { userId, meta }
  // Returns: heartbeat snapshot with lastPing, pingCount, ageMs, pingIntervalMs
  app.post('/api/v1/workspaces/:workspaceId/heartbeat', (req, res) => {
    try {
      const { workspaceId } = req.params;
      const { userId, meta } = req.body || {};
      const snap = _heartbeat178.ping(workspaceId, { userId, meta });
      res.status(200).json({ ok: true, ...snap, ecosVersion: 'V178' });
    } catch (err) {
      const sc = err.statusCode || 500;
      res.status(sc).json({ ok: false, error: err.message, code: err.code || 'ERROR', ecosVersion: 'V178' });
    }
  });

  // ── [V178-T03] DELETE /api/v1/workspaces/:workspaceId/heartbeat ──────────────
  // Explicitly disconnect (remove) a workspace heartbeat.
  app.delete('/api/v1/workspaces/:workspaceId/heartbeat', (req, res) => {
    try {
      const { workspaceId } = req.params;
      const result = _heartbeat178.disconnect(workspaceId);
      res.json({ ok: true, ...result, ecosVersion: 'V178' });
    } catch (err) {
      const sc = err.statusCode || 500;
      res.status(sc).json({ ok: false, error: err.message, code: err.code || 'ERROR', ecosVersion: 'V178' });
    }
  });

  // ── [V178-T04] GET /api/v1/workspaces/:workspaceId/heartbeat ─────────────────
  // Get the current heartbeat status for a workspace.
  // Returns null-ish response (ok:true, status:null) if no heartbeat registered.
  app.get('/api/v1/workspaces/:workspaceId/heartbeat', (req, res) => {
    try {
      const { workspaceId } = req.params;
      const snap = _heartbeat178.getStatus(workspaceId);
      if (!snap) {
        return res.json({ ok: true, workspaceId, status: null, note: 'No active heartbeat', ecosVersion: 'V178' });
      }
      res.json({ ok: true, ...snap, ecosVersion: 'V178' });
    } catch (err) {
      const sc = err.statusCode || 500;
      res.status(sc).json({ ok: false, error: err.message, code: err.code || 'ERROR', ecosVersion: 'V178' });
    }
  });

  // ── [V178-T05] GET /api/v1/admin/heartbeats ──────────────────────────────────
  // Return all active (non-stale) workspace heartbeats + aggregate stats.
  app.get('/api/v1/admin/heartbeats', (req, res) => {
    try {
      const active = _heartbeat178.listActive();
      const stats  = _heartbeat178.stats();
      res.json({ ok: true, active, stats, ecosVersion: 'V178' });
    } catch (err) {
      res.status(500).json({ ok: false, error: err.message, ecosVersion: 'V178' });
    }
  });

  // ── [V178-T06] POST /api/v1/workspaces/:workspaceId/events/bulk ──────────────
  // Bulk event ingestion: accept up to 100 events per call, emit each through the
  // audit trail and return per-event results (ok/error).
  // Body: { events: Array<{ eventType, actorId?, targetId?, targetType?, payload? }> }
  const V178_BULK_MAX = 100;
  app.post('/api/v1/workspaces/:workspaceId/events/bulk', async (req, res) => {
    try {
      const { workspaceId } = req.params;
      const { events } = req.body || {};

      if (!Array.isArray(events)) {
        return res.status(400).json({ ok: false, error: 'events must be an array', code: 'INVALID_PAYLOAD', ecosVersion: 'V178' });
      }
      if (events.length > V178_BULK_MAX) {
        return res.status(400).json({
          ok: false, error: `Maximum ${V178_BULK_MAX} events per call (received ${events.length})`,
          code: 'BULK_LIMIT_EXCEEDED', limit: V178_BULK_MAX, ecosVersion: 'V178',
        });
      }
      if (events.length === 0) {
        return res.json({ ok: true, accepted: 0, rejected: 0, results: [], ecosVersion: 'V178' });
      }

      const { nanoid } = require('./vendor/nanoid');
      const results = [];
      let accepted = 0, rejected = 0;

      for (const ev of events) {
        if (!ev || typeof ev !== 'object' || !ev.eventType) {
          results.push({ ok: false, error: 'eventType is required', input: ev });
          rejected++;
          continue;
        }
        try {
          const record = {
            id:          nanoid(21),
            workspaceId,
            actorId:     ev.actorId    || null,
            eventType:   String(ev.eventType),
            targetId:    ev.targetId   || null,
            targetType:  ev.targetType || null,
            payload:     ev.payload    || {},
            createdAt:   new Date().toISOString(),
          };
          // Attempt to log via audit trail if available
          if (typeof defaultAuditTrail !== 'undefined' && defaultAuditTrail && defaultAuditTrail.append) {
            try { await defaultAuditTrail.append(record); } catch (_) { /* non-fatal */ }
          }
          results.push({ ok: true, id: record.id, eventType: record.eventType });
          accepted++;
        } catch (innerErr) {
          results.push({ ok: false, error: innerErr.message, eventType: ev.eventType });
          rejected++;
        }
      }

      res.status(207).json({ ok: true, accepted, rejected, total: events.length, results, ecosVersion: 'V178' });
    } catch (err) {
      const sc = err.statusCode || 500;
      res.status(sc).json({ ok: false, error: err.message, code: err.code || 'ERROR', ecosVersion: 'V178' });
    }
  });

  // ── [V178-T07] GET /api/v1/admin/summary/v178 ────────────────────────────────
  app.get('/api/v1/admin/summary/v178', (req, res) => {
    const hbStats = _heartbeat178.stats();
    const rl178   = _wsRateLimiter177.stats();
    res.json({
      ok:      true,
      version: 'V178',
      phase:   'P67',
      features: [
        'workspace-heartbeat-service',
        'bulk-event-ingestion',
        'search-relevance-scoring',
        'admin-heartbeat-monitor',
      ],
      endpoints: [
        'V178-T02 POST /workspaces/:id/heartbeat',
        'V178-T03 DELETE /workspaces/:id/heartbeat',
        'V178-T04 GET /workspaces/:id/heartbeat',
        'V178-T05 GET /admin/heartbeats',
        'V178-T06 POST /workspaces/:id/events/bulk',
        'V178-T07 GET /admin/summary/v178',
        'V178-T03 search: score + sortBy (in-place upgrade of V172/V177 search route)',
      ],
      config: {
        heartbeatStaleTtlMs: _hb178StaleTtl,
        bulkEventLimit:      V178_BULK_MAX,
      },
      stats: {
        heartbeat:   { activeWorkspaces: hbStats.activeWorkspaces, totalPings: hbStats.totalPings },
        rateLimiter: { activeBuckets: rl178.activeBuckets, totalRequests: rl178.totalRequests },
      },
      ecosVersion: 'V178',
    });
  });

  // ── V178: export for tests ────────────────────────────────────────────────────
  if (process.env.NODE_ENV === 'test') {
    module.exports._heartbeat178              = _heartbeat178;
    module.exports.WorkspaceHeartbeatService178 = WorkspaceHeartbeatService;
    module.exports.HeartbeatValidationError178  = HeartbeatValidationError;
    module.exports._hb178StaleTtl              = _hb178StaleTtl;
    module.exports.V178_BULK_MAX               = V178_BULK_MAX;
  }
  
