// V187 — Snapshot Clear, Bookmark Rename, Batch Token Set
// Phase P76 | Date: 2026-05-30
// Endpoints: V187-T01 … V187-T04
// ═══════════════════════════════════════════════════════════════════════════════

// ── V187 constants ────────────────────────────────────────────────────────────
const V187_BULK_SET_MAX = 50;  // max tokens per bulk-set call

// ── [V187-T01] DELETE /api/v1/workspaces/:workspaceId/events/stats/snapshots ──
// Clears the rolling snapshot window for a workspace.
// Returns { ok, workspaceId, cleared, ecosVersion }.
app.delete('/api/v1/workspaces/:workspaceId/events/stats/snapshots', (req, res) => {
  try {
    const { workspaceId } = req.params;
    if (!workspaceId) {
      return res.status(400).json({ ok: false, error: 'workspaceId is required', ecosVersion: 'V187' });
    }

    const snaps187 = _statsSnapshots185.get(workspaceId) || [];
    const cleared187 = snaps187.length;
    _statsSnapshots185.delete(workspaceId);

    res.json({
      ok:          true,
      workspaceId,
      cleared:     cleared187,
      ecosVersion: 'V187',
    });
  } catch (err187) {
    res.status(500).json({ ok: false, error: err187.message, ecosVersion: 'V187' });
  }
});

// ── [V187-T02] PATCH /api/v1/workspaces/:workspaceId/events/bookmarks/:name ──
// Renames an existing bookmark in _bookmarks184.
// Body: { newName: string }
// 404 if :name not found; 400 if newName already taken.
app.patch('/api/v1/workspaces/:workspaceId/events/bookmarks/:name', (req, res) => {
  try {
    const { workspaceId, name: oldName187 } = req.params;
    if (!workspaceId) {
      return res.status(400).json({ ok: false, error: 'workspaceId is required', ecosVersion: 'V187' });
    }

    const newName187 = req.body && typeof req.body.newName === 'string' ? req.body.newName.trim() : null;
    if (!newName187) {
      return res.status(400).json({
        ok:          false,
        error:       'newName is required and must be a non-empty string',
        ecosVersion: 'V187',
      });
    }
    if (newName187.length > 128) {
      return res.status(400).json({
        ok:          false,
        error:       'newName must be ≤128 characters',
        ecosVersion: 'V187',
      });
    }

    const bkMap187 = _bookmarks184.get(workspaceId);
    if (!bkMap187 || !bkMap187.has(oldName187)) {
      return res.status(404).json({
        ok:          false,
        error:       `Bookmark '${oldName187}' not found`,
        code:        'BOOKMARK_NOT_FOUND_187',
        ecosVersion: 'V187',
      });
    }
    if (bkMap187.has(newName187)) {
      return res.status(400).json({
        ok:          false,
        error:       `Bookmark '${newName187}' already exists`,
        code:        'BOOKMARK_NAME_TAKEN_187',
        ecosVersion: 'V187',
      });
    }

    const existing187 = bkMap187.get(oldName187);
    const renamed187  = { ...existing187, name: newName187, renamedAt: new Date().toISOString() };
    bkMap187.delete(oldName187);
    bkMap187.set(newName187, renamed187);

    res.json({
      ok:          true,
      workspaceId,
      oldName:     oldName187,
      newName:     newName187,
      bookmark:    renamed187,
      ecosVersion: 'V187',
    });
  } catch (err187) {
    res.status(500).json({ ok: false, error: err187.message, ecosVersion: 'V187' });
  }
});

// ── [V187-T03] POST /api/v1/admin/tokens/bulk-set ────────────────────────────
// Accepts { tokens: Array<{ workspaceId, token }> } (≤V187_BULK_SET_MAX).
// Sets tokens in bulk via _tokenSvc181.setToken. HTTP 207.
// Each result: { workspaceId, ok, error? }
app.post('/api/v1/admin/tokens/bulk-set', (req, res) => {
  try {
    const items187 = req.body && Array.isArray(req.body.tokens) ? req.body.tokens : null;
    if (!items187) {
      return res.status(400).json({
        ok:          false,
        error:       'tokens must be a non-empty array',
        ecosVersion: 'V187',
      });
    }
    if (items187.length === 0) {
      return res.status(400).json({
        ok:          false,
        error:       'tokens array must not be empty',
        ecosVersion: 'V187',
      });
    }
    if (items187.length > V187_BULK_SET_MAX) {
      return res.status(400).json({
        ok:          false,
        error:       `tokens array exceeds max of ${V187_BULK_SET_MAX}`,
        code:        'BULK_SET_LIMIT_187',
        max:         V187_BULK_SET_MAX,
        received:    items187.length,
        ecosVersion: 'V187',
      });
    }

    const results187 = items187.map(item187 => {
      const wsId187  = item187 && item187.workspaceId;
      const tok187   = item187 && item187.token;
      if (!wsId187 || typeof wsId187 !== 'string') {
        return { workspaceId: wsId187 || null, ok: false, error: 'workspaceId is required' };
      }
      if (!tok187 || typeof tok187 !== 'string') {
        return { workspaceId: wsId187, ok: false, error: 'token is required' };
      }
      try {
        _tokenSvc181.setToken(wsId187, tok187);
        return { workspaceId: wsId187, ok: true };
      } catch (e187) {
        return { workspaceId: wsId187, ok: false, error: e187.message };
      }
    });

    const succeeded187 = results187.filter(r187 => r187.ok).length;
    const failed187    = results187.length - succeeded187;

    res.status(207).json({
      ok:          true,
      results:     results187,
      total:       results187.length,
      succeeded:   succeeded187,
      failed:      failed187,
      ecosVersion: 'V187',
    });
  } catch (err187) {
    res.status(500).json({ ok: false, error: err187.message, ecosVersion: 'V187' });
  }
});

