// ── [V188-T02] DELETE /api/v1/workspaces/:workspaceId/events/bookmarks ────────
// Bulk-delete named bookmarks from _bookmarks184.
// Body: { names: string[] } (≤V188_BOOKMARK_BULK_DELETE_MAX = 20).
// HTTP 207; per-name result { name, deleted, code|null }.
app.delete('/api/v1/workspaces/:workspaceId/events/bookmarks', (req, res) => {
  try {
    const { workspaceId } = req.params;
    if (!workspaceId) {
      return res.status(400).json({ ok: false, error: 'workspaceId is required', ecosVersion: 'V188' });
    }

    const names188 = req.body && Array.isArray(req.body.names) ? req.body.names : null;
    if (!names188 || names188.length === 0) {
      return res.status(400).json({
        ok:          false,
        error:       'names must be a non-empty array',
        ecosVersion: 'V188',
      });
    }
    if (names188.length > V188_BOOKMARK_BULK_DELETE_MAX) {
      return res.status(400).json({
        ok:          false,
        error:       `names array exceeds max of ${V188_BOOKMARK_BULK_DELETE_MAX}`,
        code:        'BOOKMARK_BULK_DELETE_LIMIT_188',
        max:         V188_BOOKMARK_BULK_DELETE_MAX,
        received:    names188.length,
        ecosVersion: 'V188',
      });
    }

    const bkMap188 = _bookmarks184.has(workspaceId) ? _bookmarks184.get(workspaceId) : new Map();
    const results188 = names188.map(n188 => {
      if (!n188 || typeof n188 !== 'string') {
        return { name: n188 || null, deleted: false, code: 'INVALID_NAME_188' };
      }
      if (!bkMap188.has(n188)) {
        return { name: n188, deleted: false, code: 'BOOKMARK_NOT_FOUND_188' };
      }
      bkMap188.delete(n188);
      return { name: n188, deleted: true, code: null };
    });

    const deletedCount188 = results188.filter(r188 => r188.deleted).length;

    res.status(207).json({
      ok:          true,
      workspaceId,
      results:     results188,
      total:       results188.length,
      deleted:     deletedCount188,
      ecosVersion: 'V188',
    });
  } catch (err188) {
    res.status(500).json({ ok: false, error: err188.message, ecosVersion: 'V188' });
  }
});

// ── [V188-T03] POST /api/v1/admin/tokens/bulk-clear-v2 ────────────────────────
// Extends V183 bulk-clear: also removes entries from _tokenExpiry184.
// Body: { workspaceIds: string[] } (≤V188_BULK_CLEAR_V2_MAX = 50). HTTP 207.
app.post('/api/v1/admin/tokens/bulk-clear-v2', (req, res) => {
  try {
    const body188        = req.body || {};
    const workspaceIds188 = body188.workspaceIds;

    if (!Array.isArray(workspaceIds188) || workspaceIds188.length === 0) {
      return res.status(400).json({
        ok:          false,
        error:       'workspaceIds must be a non-empty array',
        ecosVersion: 'V188',
      });
    }
    if (workspaceIds188.length > V188_BULK_CLEAR_V2_MAX) {
      return res.status(400).json({
        ok:          false,
        error:       `workspaceIds must contain at most ${V188_BULK_CLEAR_V2_MAX} entries`,
        code:        'BULK_CLEAR_V2_LIMIT_188',
        max:         V188_BULK_CLEAR_V2_MAX,
        received:    workspaceIds188.length,
        ecosVersion: 'V188',
      });
    }

    const results188v2  = [];
    let   cleared188v2  = 0;
    let   skipped188v2  = 0;

    for (const wsId188 of workspaceIds188) {
      if (!wsId188 || typeof wsId188 !== 'string') {
        results188v2.push({ workspaceId: wsId188 || null, cleared: false, hadToken: false, hadExpiry: false, error: 'invalid workspaceId' });
        skipped188v2++;
        continue;
      }
      const hadToken188   = _tokenSvc181.hasToken(wsId188);
      const hadExpiry188  = _tokenExpiry184.has(wsId188);
      _tokenSvc181.clearToken(wsId188);
      _tokenExpiry184.delete(wsId188);
      results188v2.push({ workspaceId: wsId188, cleared: true, hadToken: hadToken188, hadExpiry: hadExpiry188 });
      if (hadToken188) cleared188v2++;
    }

    res.status(207).json({
      ok:          true,
      results:     results188v2,
      cleared:     cleared188v2,
      skipped:     skipped188v2,
      ecosVersion: 'V188',
    });
  } catch (err188) {
    res.status(500).json({ ok: false, error: err188.message, ecosVersion: 'V188' });
  }
});

