// ── [V189-T02] GET /api/v1/workspaces/:workspaceId/events/bookmarks ───────────
// Lists all bookmark names for a workspace (read-only, uses _bookmarks184).
// Optional query params: ?limit=N&offset=N (max V189_BOOKMARK_LIST_MAX per page).
// Response: { ok, workspaceId, bookmarks, total, limit, offset, ecosVersion }
app.get('/api/v1/workspaces/:workspaceId/events/bookmarks', (req, res) => {
  try {
    const wsId189b = (req.params.workspaceId || '').trim();
    if (!wsId189b) {
      return res.status(400).json({ ok: false, error: 'workspaceId is required', ecosVersion: 'V189' });
    }
    const bkMap189 = _bookmarks184.has(wsId189b) ? _bookmarks184.get(wsId189b) : new Map();
    const allBookmarks189 = Array.from(bkMap189.values());

    let limit189  = parseInt(req.query.limit,  10);
    let offset189 = parseInt(req.query.offset, 10);
    if (!Number.isFinite(limit189)  || limit189  <= 0) limit189  = V189_BOOKMARK_LIST_MAX;
    if (!Number.isFinite(offset189) || offset189 <  0) offset189 = 0;
    if (limit189 > V189_BOOKMARK_LIST_MAX) limit189 = V189_BOOKMARK_LIST_MAX;

    const page189 = allBookmarks189.slice(offset189, offset189 + limit189);

    res.status(200).json({
      ok:          true,
      workspaceId: wsId189b,
      bookmarks:   page189,
      total:       allBookmarks189.length,
      limit:       limit189,
      offset:      offset189,
      ecosVersion: 'V189',
    });
  } catch (err189t02) {
    res.status(500).json({ ok: false, error: err189t02.message, ecosVersion: 'V189' });
  }
});

