app.post('/api/v1/admin/tokens/bulk-status', (req, res) => {
  try {
    const { workspaceIds: workspaceIds189 } = req.body || {};
    if (!Array.isArray(workspaceIds189) || workspaceIds189.length === 0) {
      return res.status(400).json({
        ok:          false,
        error:       'workspaceIds must be a non-empty array',
        ecosVersion: 'V189',
      });
    }
    if (workspaceIds189.length > V189_BULK_STATUS_MAX) {
      return res.status(400).json({
        ok:          false,
        error:       `workspaceIds array exceeds max of ${V189_BULK_STATUS_MAX}`,
        code:        'BULK_STATUS_LIMIT_189',
        max:         V189_BULK_STATUS_MAX,
        ecosVersion: 'V189',
      });
    }

    const now189ms  = Date.now();
    const results189s = [];

    for (const wsId189s of workspaceIds189) {
      if (!wsId189s || typeof wsId189s !== 'string') {
        results189s.push({ workspaceId: wsId189s || null, hasToken: false, expiresAt: null, expired: null, error: 'invalid workspaceId' });
        continue;
      }
      const hasToken189s  = _tokenSvc181.hasToken(wsId189s);
      const expiryEntry189 = _tokenExpiry184.has(wsId189s) ? _tokenExpiry184.get(wsId189s) : null;
      let expiresAt189 = null;
      let expired189   = null;
      if (expiryEntry189 !== null) {
        expiresAt189 = expiryEntry189;
        expired189   = now189ms > expiryEntry189;
      }
      results189s.push({
        workspaceId: wsId189s,
        hasToken:    hasToken189s,
        expiresAt:   expiresAt189,
        expired:     expired189,
      });
    }

    res.status(207).json({
      ok:          true,
      results:     results189s,
      total:       results189s.length,
      ecosVersion: 'V189',
    });
  } catch (err189t03) {
    res.status(500).json({ ok: false, error: err189t03.message, ecosVersion: 'V189' });
  }
});

