// ═════════════════════════════════════════════════════════════════════════════
// V191 — Workspace Event Digest (read-only aggregation) + Admin summary
// Phase P80  |  Author: AI  |  Date: 2026-05-30
// Endpoints:  V191-T01 (GET /workspaces/:id/events/digest), V191-T02 (GET /admin/summary/v191)
// Notes: Sacred files UNTOUCHED (R1); zero new deps (R6 — service loaded at top of file, so this
//        block introduces no module loads); reads the existing _eventLog181 store
//        (no parallel store, per V190 chain notes); version-suffixed identifiers
//        (…191) to avoid duplicate-const (BUG-L). Exports live in the shared final
//        NODE_ENV==='test' block (so lastIndexOf still finds all cumulative exports).
// ═════════════════════════════════════════════════════════════════════════════

// ── [V191-T01] GET /api/v1/workspaces/:workspaceId/events/digest ─────────────
app.get('/api/v1/workspaces/:workspaceId/events/digest', (req, res) => {
  try {
    const { workspaceId } = req.params;
    if (!workspaceId) {
      return res.status(400).json({ ok: false, error: 'workspaceId is required', ecosVersion: 'V191' });
    }
    const ring191 = (typeof _eventLog181 !== 'undefined' && _eventLog181.get(workspaceId)) || [];
    const result191 = _eventDigest191.digest(ring191, {
      topSenders: req.query.topSenders,
      type:       req.query.type || null,
    });
    res.json({ ok: true, workspaceId, ...result191, ecosVersion: 'V191' });
  } catch (err191) {
    const code191 = (err191 && err191.statusCode) || 500;
    res.status(code191).json({ ok: false, error: err191.message, code: err191.code || 'ERROR', ecosVersion: 'V191' });
  }
});

