// ═════════════════════════════════════════════════════════════════════════════
// V192 — Workspace Event Digest Extensions (time-window + per-sender)
// Phase P81  |  Author: AI  |  Date: 2026-05-30
// Endpoints:  V192-T01 (GET /workspaces/:id/events/digest?since=&until=)
//             V192-T02 (GET /workspaces/:id/events/digest/by-sender/:senderId)
//             V192-T03 (GET /admin/summary/v192)
// Notes: Reuses _eventDigest191 + _eventLog181 (no new store, per chain notes).
//        All identifiers version-suffixed …192 (BUG-L guard).
//        Zero new npm deps (R6). Sacred files UNTOUCHED (R1).
// ═════════════════════════════════════════════════════════════════════════════

// ── [V192-T01] GET /api/v1/workspaces/:workspaceId/events/digest (time-window)
// Accepts optional ?since= and ?until= ISO timestamps to filter events before
// digesting. Reuses the existing V191 service digest() method.
app.get('/api/v1/workspaces/:workspaceId/events/digest/window', (req192, res192) => {
  try {
    const { workspaceId } = req192.params;
    if (!workspaceId) {
      return res192.status(400).json({ ok: false, error: 'workspaceId is required', ecosVersion: 'V192' });
    }

    const sinceRaw192 = req192.query.since || null;
    const untilRaw192 = req192.query.until || null;

    // Parse + validate timestamps
    let sinceMs192 = null, untilMs192 = null;
    if (sinceRaw192) {
      sinceMs192 = new Date(sinceRaw192).getTime();
      if (isNaN(sinceMs192)) return res192.status(400).json({ ok: false, error: 'since must be a valid ISO timestamp', ecosVersion: 'V192' });
    }
    if (untilRaw192) {
      untilMs192 = new Date(untilRaw192).getTime();
      if (isNaN(untilMs192)) return res192.status(400).json({ ok: false, error: 'until must be a valid ISO timestamp', ecosVersion: 'V192' });
    }
    if (sinceMs192 !== null && untilMs192 !== null && sinceMs192 > untilMs192) {
      return res192.status(400).json({ ok: false, error: 'since must not be after until', ecosVersion: 'V192' });
    }

    const ring192 = (typeof _eventLog181 !== 'undefined' && _eventLog181.get(workspaceId)) || [];

    // Filter by time window
    const filtered192 = ring192.filter(e192 => {
      if (!e192 || !e192.sentAt) return (sinceMs192 === null && untilMs192 === null);
      const t192 = new Date(e192.sentAt).getTime();
      if (isNaN(t192)) return false;
      if (sinceMs192 !== null && t192 < sinceMs192) return false;
      if (untilMs192 !== null && t192 > untilMs192) return false;
      return true;
    });

    const result192 = _eventDigest191.digest(filtered192, {
      topSenders: req192.query.topSenders,
      type:       req192.query.type || null,
    });

    res192.json({
      ok: true,
      workspaceId,
      window: { since: sinceRaw192 || null, until: untilRaw192 || null },
      filteredCount: filtered192.length,
      ...result192,
      ecosVersion: 'V192',
    });
  } catch (err192) {
    const code192 = (err192 && err192.statusCode) || 500;
    res192.status(code192).json({ ok: false, error: err192.message, code: err192.code || 'ERROR', ecosVersion: 'V192' });
  }
});

// ── [V192-T02] GET /api/v1/workspaces/:workspaceId/events/digest/by-sender/:senderId
// Returns a digest restricted to a single sender — type breakdown, time range,
// hourly histogram, event count.
app.get('/api/v1/workspaces/:workspaceId/events/digest/by-sender/:senderId', (req192b, res192b) => {
  try {
    const { workspaceId, senderId } = req192b.params;
    if (!workspaceId) return res192b.status(400).json({ ok: false, error: 'workspaceId is required', ecosVersion: 'V192' });
    if (!senderId)    return res192b.status(400).json({ ok: false, error: 'senderId is required', ecosVersion: 'V192' });

    const ring192b = (typeof _eventLog181 !== 'undefined' && _eventLog181.get(workspaceId)) || [];

    // Filter to sender only — use the existing digest() with a pre-filtered array
    const senderEvents192b = ring192b.filter(e192b => e192b && e192b.senderId === senderId);

    const result192b = _eventDigest191.digest(senderEvents192b, {
      topSenders: 1, // only one sender by definition
      type: req192b.query.type || null,
    });

    res192b.json({
      ok: true,
      workspaceId,
      senderId,
      ...result192b,
      // override topSenders to the single-sender summary (cleaner API)
      topSenders: [{ senderId, count: result192b.total }],
      ecosVersion: 'V192',
    });
  } catch (err192b) {
    const code192b = (err192b && err192b.statusCode) || 500;
    res192b.status(code192b).json({ ok: false, error: err192b.message, code: err192b.code || 'ERROR', ecosVersion: 'V192' });
  }
});

// ── [V192-T03] GET /api/v1/admin/summary/v192 ───────────────────────────────
app.get('/api/v1/admin/summary/v192', (req192c, res192c) => {
  const totalLogged192c = typeof _eventLog181 !== 'undefined'
    ? [..._eventLog181.values()].reduce((s, r) => s + (Array.isArray(r) ? r.length : 0), 0)
    : 0;
  res192c.json({
    ok: true,
    version: 'V192',
    phase: 'P81',
    features: ['event-digest-window', 'event-digest-by-sender'],
    reuseOf: ['_eventDigest191', '_eventLog181'],
    digest: _eventDigest191.stats(),
    eventLog: { totalLoggedEvents: totalLogged192c, trackedWorkspaces: typeof _eventLog181 !== 'undefined' ? _eventLog181.size : 0 },
    ecosVersion: 'V192',
  });
});

// ═════════════════════════════════════════════════════════════════════════════
// V193 — Workspace Event Digest: Daily + Diff views + Admin summary
// Phase P82  |  Author: AI  |  Date: 2026-05-31
// Endpoints:  V193-T01 (GET /workspaces/:id/events/digest/daily)
//             V193-T02 (GET /workspaces/:id/events/digest/diff)
//             V193-T03 (GET /admin/summary/v193)
// Notes: Reuses _eventDigest191 + _eventLog181 (no new store, per chain notes).
//        All identifiers version-suffixed …193 (BUG-L guard).
//        Zero new npm deps (R6). Sacred files UNTOUCHED (R1).
// ═════════════════════════════════════════════════════════════════════════════

// ── [V193-T01] GET /api/v1/workspaces/:workspaceId/events/digest/daily ───────
// Filter events for a single calendar day (UTC) then run digest.
// Required: ?date=YYYY-MM-DD  (UTC).
// Optional: ?type=  ?topSenders=
app.get('/api/v1/workspaces/:workspaceId/events/digest/daily', (req193, res193) => {
  try {
    const { workspaceId } = req193.params;
    if (!workspaceId) {
      return res193.status(400).json({ ok: false, error: 'workspaceId is required', ecosVersion: 'V193' });
    }

    const dateRaw193 = req193.query.date || null;
    if (!dateRaw193) {
      return res193.status(400).json({ ok: false, error: 'date is required (YYYY-MM-DD)', ecosVersion: 'V193' });
    }
    // Validate format YYYY-MM-DD
    if (!/^\d{4}-\d{2}-\d{2}$/.test(dateRaw193)) {
      return res193.status(400).json({ ok: false, error: 'date must be YYYY-MM-DD format', ecosVersion: 'V193' });
    }
    const dayStart193 = new Date(dateRaw193 + 'T00:00:00.000Z').getTime();
    if (isNaN(dayStart193)) {
      return res193.status(400).json({ ok: false, error: 'date is not a valid calendar date', ecosVersion: 'V193' });
    }
    const dayEnd193 = dayStart193 + 86400000; // +24 h (exclusive)

    const ring193 = (typeof _eventLog181 !== 'undefined' && _eventLog181.get(workspaceId)) || [];

    // Keep only events whose sentAt falls within the calendar day (UTC)
    const daily193 = ring193.filter(ev193 => {
      if (!ev193 || !ev193.sentAt) return false;
      const t193 = new Date(ev193.sentAt).getTime();
      if (isNaN(t193)) return false;
      return t193 >= dayStart193 && t193 < dayEnd193;
    });

    const result193 = _eventDigest191.digest(daily193, {
      topSenders: req193.query.topSenders,
      type:       req193.query.type || null,
    });

    res193.json({
      ok: true,
      workspaceId,
      date: dateRaw193,
      dayStart: new Date(dayStart193).toISOString(),
      dayEnd:   new Date(dayEnd193).toISOString(),
      filteredCount: daily193.length,
      ...result193,
      ecosVersion: 'V193',
    });
  } catch (err193) {
    const code193 = (err193 && err193.statusCode) || 500;
    res193.status(code193).json({ ok: false, error: err193.message, code: err193.code || 'ERROR', ecosVersion: 'V193' });
  }
});

// ── [V193-T02] GET /api/v1/workspaces/:workspaceId/events/digest/diff ────────
// Compare two time windows and return deltas: added/removed event types and
// sender count changes.
// Window A (compare/baseline): ?compareSince= & ?compareUntil=
// Window B (current):          ?since= & ?until=
// Both default to null (whole log) if omitted.
app.get('/api/v1/workspaces/:workspaceId/events/digest/diff', (req193b, res193b) => {
  try {
    const { workspaceId } = req193b.params;
    if (!workspaceId) {
      return res193b.status(400).json({ ok: false, error: 'workspaceId is required', ecosVersion: 'V193' });
    }

    // Helper: parse an optional ISO timestamp param
    function parseTs193b(raw, label) {
      if (!raw) return null;
      const ms = new Date(raw).getTime();
      if (isNaN(ms)) throw Object.assign(new Error(`${label} must be a valid ISO timestamp`), { statusCode: 400 });
      return ms;
    }

    const sinceMs193b      = parseTs193b(req193b.query.since,         'since');
    const untilMs193b      = parseTs193b(req193b.query.until,         'until');
    const cmpSinceMs193b   = parseTs193b(req193b.query.compareSince,  'compareSince');
    const cmpUntilMs193b   = parseTs193b(req193b.query.compareUntil,  'compareUntil');

    if (sinceMs193b !== null && untilMs193b !== null && sinceMs193b > untilMs193b) {
      return res193b.status(400).json({ ok: false, error: 'since must not be after until', ecosVersion: 'V193' });
    }
    if (cmpSinceMs193b !== null && cmpUntilMs193b !== null && cmpSinceMs193b > cmpUntilMs193b) {
      return res193b.status(400).json({ ok: false, error: 'compareSince must not be after compareUntil', ecosVersion: 'V193' });
    }

    const ring193b = (typeof _eventLog181 !== 'undefined' && _eventLog181.get(workspaceId)) || [];

    // Filter helper (inclusive on both ends; null = unbounded)
    function filterWindow193b(events, sinceMs, untilMs) {
      return events.filter(ev => {
        if (!ev || !ev.sentAt) return (sinceMs === null && untilMs === null);
        const t = new Date(ev.sentAt).getTime();
        if (isNaN(t)) return false;
        if (sinceMs !== null && t < sinceMs) return false;
        if (untilMs !== null && t > untilMs) return false;
        return true;
      });
    }

    const windowB193b = filterWindow193b(ring193b, sinceMs193b, untilMs193b);
    const windowA193b = filterWindow193b(ring193b, cmpSinceMs193b, cmpUntilMs193b);

    const digestB193b = _eventDigest191.digest(windowB193b);
    const digestA193b = _eventDigest191.digest(windowA193b);

    // Type diff — which event types were added, removed, or changed in count
    const allTypes193b = new Set([...Object.keys(digestA193b.byType), ...Object.keys(digestB193b.byType)]);
    const typeDiff193b = [];
    for (const t of allTypes193b) {
      const countA = digestA193b.byType[t] || 0;
      const countB = digestB193b.byType[t] || 0;
      const delta  = countB - countA;
      if (delta !== 0) {
        typeDiff193b.push({ type: t, baseline: countA, current: countB, delta, status: delta > 0 ? 'added' : 'removed' });
      }
    }
    typeDiff193b.sort((a, b) => Math.abs(b.delta) - Math.abs(a.delta));

    // Sender diff — top senders in each window and their count delta
    const senderMapA193b = {};
    for (const s of digestA193b.topSenders) senderMapA193b[s.senderId] = s.count;
    const senderMapB193b = {};
    for (const s of digestB193b.topSenders) senderMapB193b[s.senderId] = s.count;
    const allSenders193b = new Set([...Object.keys(senderMapA193b), ...Object.keys(senderMapB193b)]);
    const senderDiff193b = [];
    for (const sid of allSenders193b) {
      const cntA = senderMapA193b[sid] || 0;
      const cntB = senderMapB193b[sid] || 0;
      if (cntA !== cntB) senderDiff193b.push({ senderId: sid, baseline: cntA, current: cntB, delta: cntB - cntA });
    }
    senderDiff193b.sort((a, b) => Math.abs(b.delta) - Math.abs(a.delta));

    res193b.json({
      ok: true,
      workspaceId,
      windows: {
        baseline: { since: req193b.query.compareSince || null, until: req193b.query.compareUntil || null, count: windowA193b.length },
        current:  { since: req193b.query.since || null,        until: req193b.query.until || null,        count: windowB193b.length },
      },
      totalDelta: windowB193b.length - windowA193b.length,
      typeDiff:   typeDiff193b,
      senderDiff: senderDiff193b,
      ecosVersion: 'V193',
    });
  } catch (err193b) {
    const code193b = (err193b && err193b.statusCode) || 500;
    res193b.status(code193b).json({ ok: false, error: err193b.message, code: err193b.code || 'ERROR', ecosVersion: 'V193' });
  }
});

// ── [V193-T03] GET /api/v1/admin/summary/v193 ────────────────────────────────
app.get('/api/v1/admin/summary/v193', (req193c, res193c) => {
  const totalLogged193c = typeof _eventLog181 !== 'undefined'
    ? [..._eventLog181.values()].reduce((s, r) => s + (Array.isArray(r) ? r.length : 0), 0)
    : 0;
  res193c.json({
    ok: true,
    version: 'V193',
    phase: 'P82',
    features: ['event-digest-daily', 'event-digest-diff'],
    reuseOf: ['_eventDigest191', '_eventLog181'],
    digest: _eventDigest191.stats(),
    eventLog: {
      totalLoggedEvents: totalLogged193c,
      trackedWorkspaces: typeof _eventLog181 !== 'undefined' ? _eventLog181.size : 0,
    },
    ecosVersion: 'V193',
  });
});

