// ── [V194-T01] GET /api/v1/workspaces/:workspaceId/events/digest/top-types ──
// Returns the N most-frequent event types across the entire workspace log,
// with count and percentage share of total events.
// Query params: ?limit=N (1–50, default 10)
app.get('/api/v1/workspaces/:workspaceId/events/digest/top-types', (req194, res194) => {
  try {
    const workspaceId194 = req194.params.workspaceId;
    if (!workspaceId194) {
      return res194.status(400).json({ ok: false, error: 'workspaceId required', ecosVersion: 'V194' });
    }

    const limitRaw194 = parseInt(req194.query.limit, 10);
    const limit194    = isNaN(limitRaw194) ? 10 : Math.max(1, Math.min(50, limitRaw194));

    const ring194 = (typeof _eventLog181 !== 'undefined' && _eventLog181.get(workspaceId194)) || [];

    // Build type counts via digest (reuse — no parallel store)
    const digest194 = _eventDigest191.digest(ring194);
    const total194  = digest194.total;

    const topTypes194 = Object.entries(digest194.byType)
      .map(([type, count]) => ({
        type,
        count,
        pct: total194 > 0 ? Math.round((count / total194) * 10000) / 100 : 0,
      }))
      .sort((a, b) => b.count - a.count || a.type.localeCompare(b.type))
      .slice(0, limit194);

    res194.json({
      ok: true,
      workspaceId: workspaceId194,
      total: total194,
      limit: limit194,
      topTypes: topTypes194,
      ecosVersion: 'V194',
    });
  } catch (err194) {
    const code194 = (err194 && err194.statusCode) || 500;
    res194.status(code194).json({ ok: false, error: err194.message, ecosVersion: 'V194' });
  }
});

// ── [V194-T02] GET /api/v1/workspaces/:workspaceId/events/digest/sender-timeline/:senderId ──
// Returns hourly or daily event counts for a single sender within the workspace log.
// Query params: ?bucketSize=hour|day (default: hour)
app.get('/api/v1/workspaces/:workspaceId/events/digest/sender-timeline/:senderId', (req194b, res194b) => {
  try {
    const workspaceId194b = req194b.params.workspaceId;
    const senderId194b    = req194b.params.senderId;
    if (!workspaceId194b) {
      return res194b.status(400).json({ ok: false, error: 'workspaceId required', ecosVersion: 'V194' });
    }
    if (!senderId194b) {
      return res194b.status(400).json({ ok: false, error: 'senderId required', ecosVersion: 'V194' });
    }

    const bucketRaw194b  = (req194b.query.bucketSize || 'hour').toLowerCase();
    const bucketSize194b = (bucketRaw194b === 'day') ? 'day' : 'hour';

    const ring194b = (typeof _eventLog181 !== 'undefined' && _eventLog181.get(workspaceId194b)) || [];

    // Filter to only this sender's events
    const senderEvents194b = ring194b.filter(ev => ev && ev.senderId === senderId194b);

    // Build timeline buckets
    const buckets194b = {};
    for (const ev of senderEvents194b) {
      if (!ev.sentAt) continue;
      const d194b = new Date(ev.sentAt);
      if (isNaN(d194b.getTime())) continue;
      const iso194b = d194b.toISOString();
      // Hour bucket: YYYY-MM-DDTHH:00   Day bucket: YYYY-MM-DD
      const key194b = bucketSize194b === 'day'
        ? iso194b.slice(0, 10)
        : iso194b.slice(0, 13) + ':00';
      buckets194b[key194b] = (buckets194b[key194b] || 0) + 1;
    }

    // Convert to sorted array
    const timeline194b = Object.entries(buckets194b)
      .map(([bucket, count]) => ({ bucket, count }))
      .sort((a, b) => a.bucket.localeCompare(b.bucket));

    res194b.json({
      ok: true,
      workspaceId: workspaceId194b,
      senderId:    senderId194b,
      bucketSize:  bucketSize194b,
      total:       senderEvents194b.length,
      timeline:    timeline194b,
      ecosVersion: 'V194',
    });
  } catch (err194b) {
    const code194b = (err194b && err194b.statusCode) || 500;
    res194b.status(code194b).json({ ok: false, error: err194b.message, ecosVersion: 'V194' });
  }
});

