// V196 — Phase P85 | Date: 2026-05-31
// Endpoints: V196-T01 … V196-T03
// Reuses: _eventDigest191, _eventLog181 — no new stores (per chain notes)
// Sacred: lib/fiatLedger.js MD5:563e9b1f… · lib/auditLog.js MD5:e5a5c2c2… UNTOUCHED
// ═══════════════════════════════════════════════════════════════════════════════

// ── [V196-T01] GET /api/v1/workspaces/:workspaceId/events/digest/cross ────────
// Pivot table: counts events by two dimensions simultaneously.
// Query params:
//   ?rowBy=type|sender  (default: type)
//   ?colBy=day|hour     (default: day)
// Response: { rows: [ { key, cols: { "2026-06-10": 3, … }, total } ], cols: [...sorted keys] }
app.get('/api/v1/workspaces/:workspaceId/events/digest/cross', (req196, res196) => {
  try {
    const workspaceId196 = req196.params.workspaceId;
    if (!workspaceId196) {
      return res196.status(400).json({ ok: false, error: 'workspaceId required', ecosVersion: 'V196' });
    }

    const rowByRaw196 = (req196.query.rowBy || 'type').toLowerCase();
    const colByRaw196 = (req196.query.colBy || 'day').toLowerCase();
    const rowBy196 = (rowByRaw196 === 'sender') ? 'sender' : 'type';
    const colBy196 = (colByRaw196 === 'hour')   ? 'hour'   : 'day';

    const ring196 = (typeof _eventLog181 !== 'undefined' && _eventLog181.get(workspaceId196)) || [];

    // Build pivot: Map<rowKey, Map<colKey, count>>
    const pivot196 = new Map();
    const colSet196 = new Set();

    for (const ev196 of ring196) {
      if (!ev196 || !ev196.sentAt) continue;
      const d196 = new Date(ev196.sentAt);
      if (isNaN(d196.getTime())) continue;

      const rowKey196 = rowBy196 === 'sender' ? (ev196.senderId || '') : (ev196.type || '');
      const iso196    = d196.toISOString();
      const colKey196 = colBy196 === 'hour'
        ? iso196.slice(0, 13) + ':00'
        : iso196.slice(0, 10);

      colSet196.add(colKey196);
      if (!pivot196.has(rowKey196)) pivot196.set(rowKey196, new Map());
      const rowMap196 = pivot196.get(rowKey196);
      rowMap196.set(colKey196, (rowMap196.get(colKey196) || 0) + 1);
    }

    const sortedCols196 = [...colSet196].sort();

    const rows196 = [...pivot196.entries()]
      .map(([key196, colMap196]) => {
        const cols196 = {};
        let rowTotal196 = 0;
        for (const col196 of sortedCols196) {
          const cnt196 = colMap196.get(col196) || 0;
          cols196[col196] = cnt196;
          rowTotal196 += cnt196;
        }
        return { key: key196, cols: cols196, total: rowTotal196 };
      })
      .sort((a196, b196) => b196.total - a196.total || a196.key.localeCompare(b196.key));

    res196.json({
      ok: true,
      workspaceId: workspaceId196,
      rowBy:       rowBy196,
      colBy:       colBy196,
      totalEvents: ring196.length,
      cols:        sortedCols196,
      rows:        rows196,
      ecosVersion: 'V196',
    });
  } catch (err196) {
    const code196 = (err196 && err196.statusCode) || 500;
    res196.status(code196).json({ ok: false, error: err196.message, ecosVersion: 'V196' });
  }
});

// ── [V196-T02] GET /api/v1/workspaces/:workspaceId/events/digest/peak ─────────
// Returns the single time bucket with the highest event count,
// plus the top-3 event types within that bucket.
// Query params: ?granularity=hour|day (default: hour)
app.get('/api/v1/workspaces/:workspaceId/events/digest/peak', (req196b, res196b) => {
  try {
    const workspaceId196b = req196b.params.workspaceId;
    if (!workspaceId196b) {
      return res196b.status(400).json({ ok: false, error: 'workspaceId required', ecosVersion: 'V196' });
    }

    const granRaw196b  = (req196b.query.granularity || 'hour').toLowerCase();
    const gran196b     = (granRaw196b === 'day') ? 'day' : 'hour';

    const ring196b = (typeof _eventLog181 !== 'undefined' && _eventLog181.get(workspaceId196b)) || [];

    // Build bucket → { count, typeCounts }
    const buckets196b = new Map();

    for (const ev196b of ring196b) {
      if (!ev196b || !ev196b.sentAt) continue;
      const d196b = new Date(ev196b.sentAt);
      if (isNaN(d196b.getTime())) continue;
      const iso196b  = d196b.toISOString();
      const key196b  = gran196b === 'day' ? iso196b.slice(0, 10) : iso196b.slice(0, 13) + ':00';
      const evType196b = ev196b.type || '';

      if (!buckets196b.has(key196b)) buckets196b.set(key196b, { count: 0, typeCounts: new Map() });
      const bkt196b = buckets196b.get(key196b);
      bkt196b.count++;
      bkt196b.typeCounts.set(evType196b, (bkt196b.typeCounts.get(evType196b) || 0) + 1);
    }

    if (buckets196b.size === 0) {
      return res196b.json({
        ok: true,
        workspaceId: workspaceId196b,
        granularity: gran196b,
        totalEvents: 0,
        peak: null,
        ecosVersion: 'V196',
      });
    }

    // Find peak bucket
    let peakKey196b = null, peakCount196b = -1;
    for (const [k196b, v196b] of buckets196b) {
      if (v196b.count > peakCount196b ||
         (v196b.count === peakCount196b && k196b < peakKey196b)) {
        peakCount196b = v196b.count;
        peakKey196b   = k196b;
      }
    }

    const peakBkt196b = buckets196b.get(peakKey196b);

    // Top-3 types in peak bucket
    const top3196b = [...peakBkt196b.typeCounts.entries()]
      .map(([type196b, cnt196b]) => ({ type: type196b, count: cnt196b }))
      .sort((a196b, b196b) => b196b.count - a196b.count || a196b.type.localeCompare(b196b.type))
      .slice(0, 3);

    res196b.json({
      ok: true,
      workspaceId: workspaceId196b,
      granularity: gran196b,
      totalEvents: ring196b.length,
      peak: {
        bucket:   peakKey196b,
        count:    peakCount196b,
        top3Types: top3196b,
      },
      ecosVersion: 'V196',
    });
  } catch (err196b) {
    const code196b = (err196b && err196b.statusCode) || 500;
    res196b.status(code196b).json({ ok: false, error: err196b.message, ecosVersion: 'V196' });
  }
});

