// ═════════════════════════════════════════════════════════════════════════════
// V197 — Digest Sender-Rank + Type-Cooccurrence
// Phase P86 | Date: 2026-05-31
// Endpoints: V197-T01 … V197-T03
// Reuses: _eventDigest191, _eventLog181 — no new stores
// ═════════════════════════════════════════════════════════════════════════════

const V197_SENDER_RANK_MAX197 = 100; // max senders returned
const V197_COOCCUR_MAX197     = 200; // max pairs returned
const V197_COOCCUR_WINDOW_DEFAULT197 = 60; // default windowSec

// ── [V197-T01] GET /api/v1/workspaces/:workspaceId/events/digest/sender-rank ─
// Ranks all unique senders by event count (desc).
// Each entry: { senderId, count, topType, firstSentAt, lastSentAt }
// Query: ?limit=N (default 20, max 100)
app.get('/api/v1/workspaces/:workspaceId/events/digest/sender-rank', (req197, res197) => {
  try {
    const wsId197 = req197.params.workspaceId;
    if (!wsId197) {
      return res197.status(400).json({ ok: false, error: 'workspaceId required', ecosVersion: 'V197' });
    }

    const limitRaw197 = parseInt(req197.query.limit || '20', 10);
    const limit197    = Math.min(isNaN(limitRaw197) || limitRaw197 < 1 ? 20 : limitRaw197, V197_SENDER_RANK_MAX197);

    const ring197 = (typeof _eventLog181 !== 'undefined' && _eventLog181.get(wsId197)) || [];

    // Aggregate per senderId
    const senderMap197 = new Map(); // senderId → { count, typeCounts, firstSentAt, lastSentAt }

    for (const ev197 of ring197) {
      if (!ev197) continue;
      const sid197  = ev197.senderId || '';
      const type197 = ev197.type     || '';
      const sat197  = ev197.sentAt   || null;

      if (!senderMap197.has(sid197)) {
        senderMap197.set(sid197, { count: 0, typeCounts: new Map(), firstSentAt: sat197, lastSentAt: sat197 });
      }
      const entry197 = senderMap197.get(sid197);
      entry197.count++;
      entry197.typeCounts.set(type197, (entry197.typeCounts.get(type197) || 0) + 1);

      if (sat197) {
        if (!entry197.firstSentAt || sat197 < entry197.firstSentAt) entry197.firstSentAt = sat197;
        if (!entry197.lastSentAt  || sat197 > entry197.lastSentAt)  entry197.lastSentAt  = sat197;
      }
    }

    // Build ranked list
    const ranked197 = [...senderMap197.entries()]
      .map(([sid197b, data197]) => {
        // topType: type with highest count (tie → lex)
        let topType197 = '', topCount197 = -1;
        for (const [t197, c197] of data197.typeCounts) {
          if (c197 > topCount197 || (c197 === topCount197 && t197 < topType197)) {
            topCount197 = c197; topType197 = t197;
          }
        }
        return {
          senderId:    sid197b,
          count:       data197.count,
          topType:     topType197,
          firstSentAt: data197.firstSentAt,
          lastSentAt:  data197.lastSentAt,
        };
      })
      .sort((a197, b197) => b197.count - a197.count || a197.senderId.localeCompare(b197.senderId))
      .slice(0, limit197);

    res197.json({
      ok: true,
      workspaceId: wsId197,
      limit:       limit197,
      totalEvents: ring197.length,
      senderCount: senderMap197.size,
      senders:     ranked197,
      ecosVersion: 'V197',
    });
  } catch (err197) {
    const code197 = (err197 && err197.statusCode) || 500;
    res197.status(code197).json({ ok: false, error: err197.message, ecosVersion: 'V197' });
  }
});

// ── [V197-T02] GET /api/v1/workspaces/:workspaceId/events/digest/type-cooccurrence ─
// For each pair of event types (A,B) where A < B (lex), counts how many times
// an event of type A and an event of type B occur within windowSec seconds of each other.
// Query: ?windowSec=N (default 60, min 1, max 3600)
// Response: sorted by cooccurrence count desc, limited to top V197_COOCCUR_MAX197 pairs.
app.get('/api/v1/workspaces/:workspaceId/events/digest/type-cooccurrence', (req197b, res197b) => {
  try {
    const wsId197b = req197b.params.workspaceId;
    if (!wsId197b) {
      return res197b.status(400).json({ ok: false, error: 'workspaceId required', ecosVersion: 'V197' });
    }

    const winRaw197b = parseInt(req197b.query.windowSec || String(V197_COOCCUR_WINDOW_DEFAULT197), 10);
    const windowSec197b = Math.min(Math.max(isNaN(winRaw197b) || winRaw197b < 1 ? V197_COOCCUR_WINDOW_DEFAULT197 : winRaw197b, 1), 3600);
    const windowMs197b  = windowSec197b * 1000;

    const ring197b = (typeof _eventLog181 !== 'undefined' && _eventLog181.get(wsId197b)) || [];

    // Filter to events with valid sentAt + type, sort chronologically
    const valid197b = ring197b
      .filter(ev197b => ev197b && ev197b.sentAt && ev197b.type)
      .map(ev197b => ({ type: ev197b.type, ts: new Date(ev197b.sentAt).getTime() }))
      .filter(ev197b => !isNaN(ev197b.ts))
      .sort((a197b, b197b) => a197b.ts - b197b.ts);

    // Sliding-window cooccurrence: for each event i, scan forward while ts[j] - ts[i] <= windowMs
    const pairCounts197b = new Map(); // "typeA|typeB" → count (typeA < typeB lex)

    for (let i197b = 0; i197b < valid197b.length; i197b++) {
      const evI197b = valid197b[i197b];
      for (let j197b = i197b + 1; j197b < valid197b.length; j197b++) {
        const evJ197b = valid197b[j197b];
        if (evJ197b.ts - evI197b.ts > windowMs197b) break;
        if (evI197b.type === evJ197b.type) continue; // skip same-type pairs
        const a197b = evI197b.type < evJ197b.type ? evI197b.type : evJ197b.type;
        const b197b = evI197b.type < evJ197b.type ? evJ197b.type : evI197b.type;
        const key197b = a197b + '|' + b197b;
        pairCounts197b.set(key197b, (pairCounts197b.get(key197b) || 0) + 1);
      }
    }

    const pairs197b = [...pairCounts197b.entries()]
      .map(([key197b, cnt197b]) => {
        const [typeA197b, typeB197b] = key197b.split('|');
        return { typeA: typeA197b, typeB: typeB197b, count: cnt197b };
      })
      .sort((a197b, b197b) => b197b.count - a197b.count || a197b.typeA.localeCompare(b197b.typeA) || a197b.typeB.localeCompare(b197b.typeB))
      .slice(0, V197_COOCCUR_MAX197);

    res197b.json({
      ok: true,
      workspaceId:  wsId197b,
      windowSec:    windowSec197b,
      totalEvents:  ring197b.length,
      validEvents:  valid197b.length,
      pairCount:    pairCounts197b.size,
      pairs:        pairs197b,
      ecosVersion: 'V197',
    });
  } catch (err197b) {
    const code197b = (err197b && err197b.statusCode) || 500;
    res197b.status(code197b).json({ ok: false, error: err197b.message, ecosVersion: 'V197' });
  }
});

