// ═════════════════════════════════════════════════════════════════════════════
// V198 — Digest Sender-Timeline + Burst Detection
// Phase P87 | Date: 2026-05-31
// Endpoints: V198-T01 … V198-T03
// Reuses: _eventLog181 — no new stores
// ═════════════════════════════════════════════════════════════════════════════

const V198_TIMELINE_MAX198    = 500;  // max buckets in timeline response
const V198_BURST_WINDOW_MIN198 = 1;   // min windowSec
const V198_BURST_WINDOW_MAX198 = 3600; // max windowSec
const V198_BURST_RESULTS_MAX198 = 100; // max burst windows returned
const V198_BURST_THRESHOLD_DEFAULT198 = 2; // default K

// ── [V198-T01] GET /api/v1/workspaces/:workspaceId/events/digest/sender-timeline/:senderId
// Returns event counts bucketed by hour or day for a specific sender.
// Query: ?granularity=hour|day (default hour)
// Response: { senderId, granularity, totalEvents, buckets: [{bucket, count}] }
app.get('/api/v1/workspaces/:workspaceId/events/digest/sender-timeline/:senderId', (req198, res198) => {
  try {
    const wsId198    = req198.params.workspaceId;
    const sender198  = req198.params.senderId;
    if (!wsId198)   return res198.status(400).json({ ok: false, error: 'workspaceId required', ecosVersion: 'V198' });
    if (!sender198) return res198.status(400).json({ ok: false, error: 'senderId required', ecosVersion: 'V198' });

    const gran198 = (req198.query.granularity || 'hour').toLowerCase();
    if (gran198 !== 'hour' && gran198 !== 'day') {
      return res198.status(400).json({ ok: false, error: 'granularity must be "hour" or "day"', ecosVersion: 'V198' });
    }

    const ring198 = (typeof _eventLog181 !== 'undefined' && _eventLog181.get(wsId198)) || [];

    // Filter to this sender, with valid sentAt
    const senderEvents198 = ring198.filter(ev198 =>
      ev198 && ev198.senderId === sender198 && ev198.sentAt
    );

    // Bucket by hour or day
    const bucketMap198 = new Map(); // bucket-key → count
    for (const ev198 of senderEvents198) {
      const d198 = new Date(ev198.sentAt);
      if (isNaN(d198.getTime())) continue;
      let key198;
      if (gran198 === 'hour') {
        // Format: "2026-06-10T08"
        key198 = d198.toISOString().slice(0, 13); // "YYYY-MM-DDTHH"
      } else {
        // Format: "2026-06-10"
        key198 = d198.toISOString().slice(0, 10);
      }
      bucketMap198.set(key198, (bucketMap198.get(key198) || 0) + 1);
    }

    // Sort buckets chronologically, cap at max
    const buckets198 = [...bucketMap198.entries()]
      .sort((a198, b198) => a198[0].localeCompare(b198[0]))
      .slice(0, V198_TIMELINE_MAX198)
      .map(([bucket198, count198]) => ({ bucket: bucket198, count: count198 }));

    res198.json({
      ok:          true,
      workspaceId: wsId198,
      senderId:    sender198,
      granularity: gran198,
      totalEvents: senderEvents198.length,
      buckets:     buckets198,
      ecosVersion: 'V198',
    });
  } catch (err198) {
    const code198 = (err198 && err198.statusCode) || 500;
    res198.status(code198).json({ ok: false, error: err198.message, ecosVersion: 'V198' });
  }
});

// ── [V198-T02] GET /api/v1/workspaces/:workspaceId/events/digest/bursts
// Find all time windows of windowSec seconds with >= threshold events.
// Query: ?windowSec=N (default 60, 1–3600), ?threshold=K (default 2, min 1)
// Response: { windowSec, threshold, bursts: [{windowStart, count, topType}] } sorted by count desc
app.get('/api/v1/workspaces/:workspaceId/events/digest/bursts', (req198b, res198b) => {
  try {
    const wsId198b = req198b.params.workspaceId;
    if (!wsId198b) return res198b.status(400).json({ ok: false, error: 'workspaceId required', ecosVersion: 'V198' });

    const winRaw198b = parseInt(req198b.query.windowSec || '60', 10);
    const windowSec198b = Math.min(
      Math.max(isNaN(winRaw198b) || winRaw198b < 1 ? 60 : winRaw198b, V198_BURST_WINDOW_MIN198),
      V198_BURST_WINDOW_MAX198
    );
    const windowMs198b = windowSec198b * 1000;

    const thrRaw198b = parseInt(req198b.query.threshold || String(V198_BURST_THRESHOLD_DEFAULT198), 10);
    const threshold198b = Math.max(isNaN(thrRaw198b) || thrRaw198b < 1 ? V198_BURST_THRESHOLD_DEFAULT198 : thrRaw198b, 1);

    const ring198b = (typeof _eventLog181 !== 'undefined' && _eventLog181.get(wsId198b)) || [];

    // Filter to events with valid sentAt, sort chronologically
    const valid198b = ring198b
      .filter(ev198b => ev198b && ev198b.sentAt)
      .map(ev198b => ({ ts: new Date(ev198b.sentAt).getTime(), type: ev198b.type || '', sentAt: ev198b.sentAt }))
      .filter(ev198b => !isNaN(ev198b.ts))
      .sort((a198b, b198b) => a198b.ts - b198b.ts);

    // Sliding-window burst detection: for each event i, count events within [ts_i, ts_i + windowMs)
    const bursts198b = [];
    for (let i198b = 0; i198b < valid198b.length; i198b++) {
      const startTs198b = valid198b[i198b].ts;
      const typeCounts198b = new Map();
      let count198b = 0;

      for (let j198b = i198b; j198b < valid198b.length; j198b++) {
        if (valid198b[j198b].ts - startTs198b >= windowMs198b) break;
        count198b++;
        const t198b = valid198b[j198b].type;
        typeCounts198b.set(t198b, (typeCounts198b.get(t198b) || 0) + 1);
      }

      if (count198b >= threshold198b) {
        // Compute topType (highest count, lex tie-break)
        let topType198b = '', topCnt198b = -1;
        for (const [t198b, c198b] of typeCounts198b) {
          if (c198b > topCnt198b || (c198b === topCnt198b && t198b < topType198b)) {
            topCnt198b = c198b; topType198b = t198b;
          }
        }
        bursts198b.push({ windowStart: valid198b[i198b].sentAt, count: count198b, topType: topType198b });
      }
    }

    // Sort by count desc, deduplicate by windowStart, cap results
    const seen198b = new Set();
    const deduped198b = [];
    for (const b198b of bursts198b.sort((a198b, b198bb) => b198bb.count - a198b.count || a198b.windowStart.localeCompare(b198bb.windowStart))) {
      if (!seen198b.has(b198b.windowStart)) {
        seen198b.add(b198b.windowStart);
        deduped198b.push(b198b);
        if (deduped198b.length >= V198_BURST_RESULTS_MAX198) break;
      }
    }

    res198b.json({
      ok:          true,
      workspaceId: wsId198b,
      windowSec:   windowSec198b,
      threshold:   threshold198b,
      totalEvents: ring198b.length,
      burstCount:  deduped198b.length,
      bursts:      deduped198b,
      ecosVersion: 'V198',
    });
  } catch (err198b) {
    const code198b = (err198b && err198b.statusCode) || 500;
    res198b.status(code198b).json({ ok: false, error: err198b.message, ecosVersion: 'V198' });
  }
});

