// ═════════════════════════════════════════════════════════════════════════════
// V199 — Digest Gap Detection + Event Velocity
// Phase P88 | Date: 2026-05-31
// Endpoints: V199-T01 … V199-T03
// Reuses: _eventLog181 — no new stores
// ═════════════════════════════════════════════════════════════════════════════

const V199_GAP_RESULTS_MAX199    = 200;  // max gaps returned
const V199_GAP_MIN_SEC199        = 1;    // min valid minGapSec
const V199_VELOCITY_MAX199       = 500;  // max buckets in velocity response
const V199_GAP_DEFAULT_SEC199    = 60;   // default minGapSec if missing/invalid

// ── [V199-T01] GET /api/v1/workspaces/:workspaceId/events/digest/gaps
// Find intervals between consecutive events where gap >= minGapSec.
// Query: ?minGapSec=N (default 60, min 1)
// Response: { minGapSec, totalEvents, gapCount, gaps: [{gapStart, gapEnd, gapSec}] } sorted by gapSec desc
app.get('/api/v1/workspaces/:workspaceId/events/digest/gaps', (req199, res199) => {
  try {
    const wsId199 = req199.params.workspaceId;
    if (!wsId199) return res199.status(400).json({ ok: false, error: 'workspaceId required', ecosVersion: 'V199' });

    const minGapRaw199 = parseInt(req199.query.minGapSec || String(V199_GAP_DEFAULT_SEC199), 10);
    const minGapSec199 = isNaN(minGapRaw199) || minGapRaw199 < V199_GAP_MIN_SEC199
      ? V199_GAP_DEFAULT_SEC199
      : minGapRaw199;
    const minGapMs199 = minGapSec199 * 1000;

    const ring199 = (typeof _eventLog181 !== 'undefined' && _eventLog181.get(wsId199)) || [];

    // Filter to events with valid sentAt, sort chronologically
    const sorted199 = ring199
      .filter(ev199 => ev199 && ev199.sentAt)
      .map(ev199 => ({ ts: new Date(ev199.sentAt).getTime(), sentAt: ev199.sentAt }))
      .filter(ev199 => !isNaN(ev199.ts))
      .sort((a199, b199) => a199.ts - b199.ts);

    // Find consecutive pairs where gap >= minGapMs
    const gaps199 = [];
    for (let i199 = 0; i199 < sorted199.length - 1; i199++) {
      const gapMs199 = sorted199[i199 + 1].ts - sorted199[i199].ts;
      if (gapMs199 >= minGapMs199) {
        gaps199.push({
          gapStart: sorted199[i199].sentAt,
          gapEnd:   sorted199[i199 + 1].sentAt,
          gapSec:   Math.floor(gapMs199 / 1000),
        });
      }
    }

    // Sort by gapSec desc, cap at max
    const result199 = gaps199
      .sort((a199, b199) => b199.gapSec - a199.gapSec)
      .slice(0, V199_GAP_RESULTS_MAX199);

    res199.json({
      ok:          true,
      workspaceId: wsId199,
      minGapSec:   minGapSec199,
      totalEvents: sorted199.length,
      gapCount:    result199.length,
      gaps:        result199,
      ecosVersion: 'V199',
    });
  } catch (err199) {
    const code199 = (err199 && err199.statusCode) || 500;
    res199.status(code199).json({ ok: false, error: err199.message, ecosVersion: 'V199' });
  }
});

