// ── [V208-T02] GET /api/v1/system/guided-actions ────────────────────────────
// Returns the full guided actions catalog. Supports filtering by:
//   ?category=economy|governance|onboarding|retention|quality|admin
//   ?minRank=0..9  — only actions available at or above this rank
//   ?humanInLoop=true|false
app.get('/api/v1/system/guided-actions', (req, res) => {
  try {
    let actions208 = [...GUIDED_ACTIONS_208];
    const { category, minRank, humanInLoop } = req.query;
    if (category) actions208 = actions208.filter(a => a.category === category);
    if (minRank !== undefined) {
      const rank208 = parseInt(minRank, 10);
      if (!isNaN(rank208)) actions208 = actions208.filter(a => a.minRank <= rank208);
    }
    if (humanInLoop !== undefined) {
      const hitl208 = humanInLoop === 'true';
      actions208 = actions208.filter(a => !!a.humanInLoop === hitl208);
    }
    res.json({
      ok: true,
      total: actions208.length,
      filters: { category: category || null, minRank: minRank || null, humanInLoop: humanInLoop || null },
      actions: actions208,
      ecosVersion: 'V208',
    });
  } catch (err208) {
    res.status(500).json({ ok: false, error: err208.message, ecosVersion: 'V208' });
  }
});

