// ── [V210-T05] GET /api/v1/workspaces/:id/health-score ───────────────────────
// Workspace Health Score: composite metric (reputation + streak + task volume + escrow ratio).
// Inline computation — no new lib required.
app.get('/api/v1/workspaces/:id/health-score', (req210m, res210m) => {
  try {
    const wsId210m = req210m.params.id;
    // Collect what we know about this workspace from existing stores
    const repDecay210m    = typeof computeDecay208 === 'function'
      ? computeDecay208(wsId210m, Date.now()) : null;
    const streak210m      = typeof getStreak208 === 'function'
      ? (() => { try { return getStreak208(wsId210m); } catch(_) { return null; } })()
      : null;
    const stakeData210m   = getStakeStatus210({ validatorId: wsId210m });
    const referralData210m = (() => { try { return getReferralEarnings210(wsId210m); } catch(_) { return null; } })();

    // Score components (0–100 each)
    const repScore210m    = repDecay210m ? Math.min(100, Math.round((repDecay210m.adjustedScore || 0) / 10)) : 50;
    const streakScore210m = streak210m ? Math.min(100, (streak210m.currentStreak || 0) * 5) : 0;
    const stakeScore210m  = stakeData210m.correctCount > 0
      ? Math.min(100, Math.round(stakeData210m.correctCount / (stakeData210m.correctCount + stakeData210m.wrongCount + 0.001) * 100))
      : 50;
    const royaltyScore210m = referralData210m ? Math.min(100, Math.round(referralData210m.royaltiesFromNetwork)) : 0;

    const overall210m = Math.round(
      repScore210m * 0.40 +
      streakScore210m * 0.30 +
      stakeScore210m  * 0.20 +
      royaltyScore210m * 0.10
    );

    res210m.json({
      ok: true,
      workspaceId: wsId210m,
      healthScore: overall210m,
      grade: overall210m >= 80 ? 'A' : overall210m >= 60 ? 'B' : overall210m >= 40 ? 'C' : 'D',
      components: {
        reputation: repScore210m,
        streak:     streakScore210m,
        stakeAccuracy: stakeScore210m,
        networkRoyalties: royaltyScore210m,
      },
      weights: { reputation: 0.40, streak: 0.30, stakeAccuracy: 0.20, networkRoyalties: 0.10 },
      ecosVersion: 'V210',
    });
  } catch (err210m) {
    res210m.status(500).json({ ok: false, error: err210m.message, ecosVersion: 'V210' });
  }
});

