// ═════════════════════════════════════════════════════════════════════════════
// V213 — Economic Safety Monitor (research-grounded red-flag indices)
// Phase P102 | Author: AI (lead) | Date: 2026-05-31
// Endpoints: V213-T01 GET /api/v1/admin/economic-safety
//            V213-T02 GET /api/v1/admin/economic-safety/:indexId
//            V213-T03 GET /api/v1/admin/summary/v213
// Notes: Sacred files UNTOUCHED (R1); zero new npm deps (R6 — relative lib only);
//        pure stateless monitor; version-suffixed identifiers (…213, BUG-L safe).
//        Operationalizes the "red flags to monitor immediately" research layer:
//        Faucet/Sink, Reputation Inflation, Reputation Gini, Hollow Task Rate,
//        Treasury Liquidity Ratio.
// ═════════════════════════════════════════════════════════════════════════════
(function _wireEconomicSafety213() {
  const {
    assess213, faucetSinkRatio213, reputationInflationIndex213, reputationGini213,
    hollowTaskRate213, treasuryLiquidityRatio213, SafetyInputError213,
  } = require('./lib/economicSafetyMonitor213.js');

  function _parseSafetyInput213(q) {
    const inp = {};
    const numKeys = ['emission','burn','repMinted','repDecayed','hollowTasks','totalTasks','externalStableValue','nativeTokenValue'];
    for (const k of numKeys) if (q[k] !== undefined) inp[k] = Number(q[k]);
    if (q.reputations !== undefined) {
      inp.reputations = String(q.reputations).split(',').map(s => Number(s.trim())).filter(n => isFinite(n));
    }
    return inp;
  }

  // ── [V213-T01] GET /api/v1/admin/economic-safety ───────────────────────────
  // Full assessment across all five indices (inputs via query; missing indices skipped).
  app.get('/api/v1/admin/economic-safety', (req213, res213) => {
    try {
      const result213 = assess213(_parseSafetyInput213(req213.query || {}));
      res213.json({ ok: true, ...result213, ecosVersion: 'V213' });
    } catch (e213) {
      res213.status((e213 && e213.statusCode) || 500).json({ ok: false, error: e213.message, code: e213.code || 'ERROR', ecosVersion: 'V213' });
    }
  });

  // ── [V213-T02] GET /api/v1/admin/economic-safety/:indexId ──────────────────
  // Single index by id: faucet_sink_ratio | reputation_inflation_index |
  // reputation_gini | hollow_task_rate | treasury_liquidity_ratio
  app.get('/api/v1/admin/economic-safety/:indexId', (req213b, res213b) => {
    try {
      const q = _parseSafetyInput213(req213b.query || {});
      const id = req213b.params.indexId;
      let out;
      switch (id) {
        case 'faucet_sink_ratio':           out = faucetSinkRatio213(q.emission, q.burn); break;
        case 'reputation_inflation_index':  out = reputationInflationIndex213(q.repMinted, q.repDecayed); break;
        case 'reputation_gini':             out = reputationGini213(q.reputations || []); break;
        case 'hollow_task_rate':            out = hollowTaskRate213(q.hollowTasks, q.totalTasks); break;
        case 'treasury_liquidity_ratio':    out = treasuryLiquidityRatio213(q.externalStableValue, q.nativeTokenValue); break;
        default: return res213b.status(404).json({ ok: false, error: 'unknown indexId', code: 'UNKNOWN_INDEX', ecosVersion: 'V213' });
      }
      res213b.json({ ok: true, index: out, ecosVersion: 'V213' });
    } catch (e213b) {
      res213b.status((e213b && e213b.statusCode) || 500).json({ ok: false, error: e213b.message, code: e213b.code || 'ERROR', ecosVersion: 'V213' });
    }
  });

  // ── [V213-T03] GET /api/v1/admin/summary/v213 ──────────────────────────────
  app.get('/api/v1/admin/summary/v213', (req213c, res213c) => {
    res213c.json({
      ok: true,
      version: 'V213',
      phase: 'P102',
      features: ['economic-safety-monitor'],
      newLibFiles: ['lib/economicSafetyMonitor213.js'],
      indices: ['faucet_sink_ratio','reputation_inflation_index','reputation_gini','hollow_task_rate','treasury_liquidity_ratio'],
      basis: 'ECOS strategic economic research — red-flags-to-monitor layer',
      ecosVersion: 'V213',
    });
  });
})();

