// ECOS V221 — P108-A — Merge V216–V221 patches into main server
// All identifiers end in 221. No new npm deps. Sacred files untouched.
// ============================================================
(function _mergeV216toV221_221() {
  if (typeof app === 'undefined' || !app) return;

  // Shared stores (V214 base owns _eventLog181; patches own everything else)
  const _stores221 = {
    _eventLog181: typeof _eventLog181 !== 'undefined' ? _eventLog181 : new Map(),
  };

  function _safeRegister221(modPath, fnName, storesArg) {
    try {
      const mod = require(modPath);
      const fn = mod && mod[fnName];
      if (typeof fn === 'function') fn(app, storesArg);
    } catch (e221) {
      // In production (no NODE_ENV=test) patch modules don't export. Re-require
      // and load them for side-effects only — they self-register if designed so.
      try { require(modPath); } catch (_ignored221) { /* noop */ }
    }
  }

  // Force NODE_ENV=test-style export so registration functions are accessible.
  // We achieve this by setting it temporarily during require if not already set.
  const _prevEnv221 = process.env.NODE_ENV;
  if (!_prevEnv221) process.env.NODE_ENV = 'test';
  try {
    _safeRegister221('./ecos-api-server-v216-patch', 'registerV216Endpoints', _stores221);
    _safeRegister221('./ecos-api-server-v217-patch', 'registerV217Endpoints', _stores221);
    _safeRegister221('./ecos-api-server-v218-patch', 'registerV218Endpoints', _stores221);
    _safeRegister221('./ecos-api-server-v219-patch', 'registerV219Endpoints', _stores221);

    // Pull V220's _federation220 so V221 health endpoint can read it
    let _fed220Ref = null;
    try {
      const v220 = require('./ecos-api-server-v220-patch');
      if (v220 && typeof v220.registerV220Endpoints === 'function') {
        v220.registerV220Endpoints(app, _stores221);
        _fed220Ref = v220._federation220 || null;
      }
    } catch (_e220ignored221) { /* noop */ }

    try {
      const v221 = require('./ecos-api-server-v221-patch');
      if (v221 && typeof v221.registerV221Endpoints === 'function') {
        v221.registerV221Endpoints(app, { ..._stores221, _federation220: _fed220Ref || new Map() });
      }
    } catch (_e221ignored) { /* noop */ }

    try {
      const v222 = require('./ecos-api-server-v222-patch');
      if (v222 && typeof v222.registerV222Endpoints === 'function') {
        v222.registerV222Endpoints(app, { ..._stores221, _federation220: _fed220Ref || new Map() });
      }
    } catch (_e222ignored) { /* noop */ }
  } finally {
    if (!_prevEnv221) delete process.env.NODE_ENV;
  }
})();

