// V254 — Automation Catalog (home for reusable automation recipes)
// Phase P150 | Author: AI (lead) | Date: 2026-05-31
// A registry where external builders (e.g. Gumloop) publish reusable automations.
// Each recipe is validated and risk-annotated via the V240 safety interlock, so a
// destructive step (payout/delete/etc.) is surfaced as requiresHitl before anyone
// runs it. Sacred files UNTOUCHED (R1); zero new npm deps (R6); suffixed (…254).
// Endpoints: V254-T01 POST/GET /api/v1/automations(/:id), DELETE, validate
//            V254-T02 GET /api/v1/admin/summary/v254
// ═════════════════════════════════════════════════════════════════════════════
(function _wireAutomationCatalog254() {
  try {
    const { createAutomationCatalog254, validateAutomation254 } = require('./lib/automationCatalog254.js');
    let classify254 = null;
    try { classify254 = require('./lib/dangerousToolInterlock240.js').classifyToolCall240; } catch (_) {}
    const _automations254 = createAutomationCatalog254({
      classify: classify254,
      audit: (ev) => { try { logger.info({ automation: ev }, '[V254] automation catalog'); } catch (_) {} },
    });

    // [V254-T01] register / list / get / delete / validate
    app.post('/api/v1/automations', (req, res) => {
      try { res.json({ ok: true, automation: _automations254.register(req.body || {}), ecosVersion: 'V254' }); }
      catch (e) { res.status((e && e.statusCode) || 500).json({ ok: false, error: e.message, code: e.code || 'ERROR', ecosVersion: 'V254' }); }
    });
    app.post('/api/v1/automations/validate', (req, res) => {
      res.json({ ok: true, ...validateAutomation254(req.body || {}), ecosVersion: 'V254' });
    });
    app.get('/api/v1/automations', (req, res) => {
      const q = req.query || {};
      res.json({ ok: true, automations: _automations254.list({ trigger: q.trigger, tag: q.tag, source: q.source }), ecosVersion: 'V254' });
    });
    app.get('/api/v1/automations/:id', (req, res) => {
      const a = _automations254.get(req.params.id);
      if (!a) return res.status(404).json({ ok: false, error: 'not found', code: 'NOT_FOUND', ecosVersion: 'V254' });
      res.json({ ok: true, automation: a, ecosVersion: 'V254' });
    });
    app.delete('/api/v1/automations/:id', (req, res) => {
      res.json({ ok: true, ..._automations254.remove(req.params.id), ecosVersion: 'V254' });
    });

    // [V254-T02] summary
    app.get('/api/v1/admin/summary/v254', (req, res) => {
      res.json({ ok: true, version: 'V254', phase: 'P150', feature: 'automation-catalog',
        safetyIntegrated: !!classify254, catalog: _automations254.stats(), ecosVersion: 'V254' });
    });
  } catch (e254) {
    try { logger.warn({ err: e254.message }, '[V254] automation catalog not wired (non-fatal)'); } catch (_) {}
  }
})();

