// ── Bloom Audit ↔ InjectionFirewall Cross-Reference Bridge ───────────────────
// POST /api/v271/audit/bloom-firewall-check  — check if an input is in bloom AND firewall
// GET  /api/v271/audit/bloom-firewall-stats  — cross-reference statistics
(function _wireBloomFirewallCrossRef271() {
  try {
    const _getBloomAndFirewall271 = () => {
      try {
        const { createV268State } = require('./ecos-api-server-v268-patch.js');
        const state = createV268State({ dbPool, logger });
        return { auditBloom: state.auditBloom, firewall: state.firewall };
      } catch (_) {
        return { auditBloom: null, firewall: null };
      }
    };

    // Persistent Bloom adapter integration (writes audit bloom state to postgres)
    const _tryMountBloomPersistence271 = () => {
      try {
        if (!dbPool || typeof dbPool.query !== 'function') return;
        const { createPostgresAuditBloomAdapter271 } =
          require('./src/lib/postgresAuditBloomAdapter271.js');
        const adapter = createPostgresAuditBloomAdapter271(dbPool);
        const { auditBloom } = _getBloomAndFirewall271();
        if (auditBloom && typeof auditBloom.setPersistenceAdapter === 'function') {
          auditBloom.setPersistenceAdapter(adapter);
          try { logger.info({ phase: 'P171' }, '[V271] AuditBloom268 persistence adapter mounted'); } catch (_) {}
        }
      } catch (_) {}
    };
    _tryMountBloomPersistence271();

    // Cross-reference: input is checked against both Bloom (known-bad log) and InjectionFirewall
    app.post('/api/v271/audit/bloom-firewall-check', (req, res) => {
      try {
        const { input } = req.body || {};
        if (!input || typeof input !== 'string') {
          return res.status(400).json({ ok: false, error: 'input string required', ecosVersion: 'V271' });
        }
        const { auditBloom, firewall } = _getBloomAndFirewall271();
        const bloomHit    = auditBloom && typeof auditBloom.check === 'function'
          ? auditBloom.check(input)
          : null;
        const firewallHit = firewall && typeof firewall.checkInput === 'function'
          ? firewall.checkInput(input)
          : null;
        const blocked = (bloomHit === true) || (firewallHit && firewallHit.blocked);
        res.json({
          ok:          true,
          ecosVersion: 'V271',
          input:       input.slice(0, 80),
          bloom:       { checked: bloomHit !== null, hit: bloomHit },
          firewall:    { checked: firewallHit !== null, result: firewallHit },
          blocked,
          crossRef:    'auditBloom268 × injectionFirewall268',
        });
      } catch (e) {
        res.status(500).json({ ok: false, error: e.message, ecosVersion: 'V271' });
      }
    });

    app.get('/api/v271/audit/bloom-firewall-stats', (req, res) => {
      try {
        const { auditBloom, firewall } = _getBloomAndFirewall271();
        const bloomStats    = auditBloom && typeof auditBloom.getStats === 'function'
          ? auditBloom.getStats()
          : null;
        const firewallStats = firewall && typeof firewall.getBlockList === 'function'
          ? { blockListSize: (firewall.getBlockList() || []).length }
          : null;
        res.json({
          ok:           true,
          ecosVersion:  'V271',
          auditBloom:   bloomStats,
          firewall:     firewallStats,
          crossRefBridge: 'V271',
        });
      } catch (e) {
        res.status(500).json({ ok: false, error: e.message, ecosVersion: 'V271' });
      }
    });

    try { logger.info({ phase: 'P171' }, '[V271] Bloom-Firewall cross-reference bridge wired'); } catch (_) {}
  } catch (e271b) {
    try { logger.warn({ err: e271b.message }, '[V271] Bloom-Firewall bridge not wired (non-fatal)'); } catch (_) {}
  }
})();

