// ═════════════════════════════════════════════════════════════════════════════
// V299 — Capital-Safe Pilots (paper-trading, fulfilment bridge, audit receipts, treasury MM)
// Phase P187 | Author: AI (lead) | Date: 2026-06-02
// Grows the V298 seeds into capital-safe pilots:
//   (a) paperBacktest299 — offline backtest loop over grid+AS quotes
//   (b) ServiceFulfilmentBridge299 — payment-rail / agent-rental stubs + credit HITL gate
//   (c) simulateAndReceipt299 — formula-contract simulation → AgentReceipts268-shaped audit record
//   (d) TreasuryMarketMaker299 — inventory quotes + V240-style HITL annotation
// Sacred UNTOUCHED (R1); zero new npm deps (R6); version-suffixed (…299).
// Endpoints: V299-T01 /market/backtest  ·  V299-T02 /services/:id/fulfil
//            V299-T03 /contracts/simulate/receipt  ·  V299-T04 /market/treasury/quote
//            V299-T05 GET /api/v1/admin/summary/v299
// ═════════════════════════════════════════════════════════════════════════════
(function _wireCapitalPilots299() {
  try {
    const V299 = require('./lib/marketMaker299.js');
    const SS298 = require('./lib/sovereignServices298.js');
    const bridge = V299.defaultFulfilBridge299();
    const treasury = V299.defaultTreasuryMarketMaker299();

    function _failV299(res, e) {
      res.status((e && e.statusCode) || 500).json({ ok: false, error: e.message, code: e.code || 'ERROR', ecosVersion: 'V299' });
    }

    // Named contract templates (same as V298 — no arbitrary code over HTTP)
    const CONTRACT_TEMPLATES_V299 = {
      vault: new SS298.FormulaContract298({
        id: 'vault',
        guards: [{ expr: s => s.balance >= 0, msg: 'no negative balance' }],
        step: (s, inp, ops) => ({ balance: ops.add(s.balance, Number(inp.delta) || 0) }),
      }),
      'linear-vesting': new SS298.FormulaContract298({
        id: 'linear-vesting',
        guards: [{ expr: s => s.released <= s.total, msg: 'over-release' }],
        step: (s, inp, ops) => ({ total: s.total, released: ops.min(s.total, ops.add(s.released, Number(s.perStep) || 0)), perStep: s.perStep }),
      }),
    };

    // [V299-T01] offline paper-trading backtest
    app.post('/api/v1/market/backtest', (req, res) => {
      try {
        const b = req.body || {};
        const result = V299.paperBacktest299(
          b.priceSeries || [],
          b.gridParams   || {},
          b.asParams     || {},
        );
        res.json({ ok: true, ...result, ecosVersion: 'V299' });
      } catch (e) { _failV299(res, e); }
    });

    // [V299-T02] service fulfilment (credit charge + adapter dispatch)
    app.post('/api/v1/services/:id/fulfil', (req, res) => {
      try {
        const b = req.body || {};
        const result = bridge.fulfil(req.params.id, b.qty || 1, {
          userId:    b.userId,
          userInput: b.userInput,
        });
        res.status(result.ok === false && result.code === 'HITL_REQUIRED' ? 202 : 200)
          .json(Object.assign({}, result, { ecosVersion: 'V299' }));
      } catch (e) { _failV299(res, e); }
    });

    // [V299-T03] formula-contract simulate + emit audit receipt (named templates only)
    app.post('/api/v1/contracts/simulate/receipt', (req, res) => {
      try {
        const b = req.body || {};
        const contract = CONTRACT_TEMPLATES_V299[b.template];
        if (!contract) {
          return res.status(400).json({
            ok: false, error: 'unknown template; allowed: ' + Object.keys(CONTRACT_TEMPLATES_V299).join(', '),
            code: 'BAD_TEMPLATE', ecosVersion: 'V299',
          });
        }
        const result = V299.simulateAndReceipt299(contract, b.initialState || {}, b.inputs || {});
        res.json(Object.assign({}, result, { ecosVersion: 'V299' }));
      } catch (e) { _failV299(res, e); }
    });

    // [V299-T04] treasury inventory quote (HITL annotation on large positions)
    app.post('/api/v1/market/treasury/quote', (req, res) => {
      try {
        const q = treasury.quote(req.body || {});
        res.json({ ok: true, ...q, ecosVersion: 'V299' });
      } catch (e) { _failV299(res, e); }
    });

    // [V299-T05] combined V299 summary
    app.get('/api/v1/admin/summary/v299', (req, res) => {
      res.json({
        ok: true, version: 'V299', phase: 'P187',
        feature: 'capital-safe-pilots: paper-backtest + fulfilment-bridge + contract-receipts + treasury-mm',
        contractTemplates: Object.keys(CONTRACT_TEMPLATES_V299),
        fulfilBridge: bridge.stats(),
        treasury:     treasury.stats(),
        note: 'all pilots offline-only; real capital/chain binding is the V300+ step',
        ecosVersion: 'V299',
      });
    });

  } catch (e299) {
    try { logger.warn({ err: e299.message }, '[V299] capital-safe pilots not wired (non-fatal)'); } catch (_) {}
  }
})();

