// V334 — Capability Lineage & Self-Healing (turn version-duplication into an asset)
// Phase P222 | Author: AI (lead) | Date: 2026-06-01
// Builds on the V287 mesh: groups the 169+ versioned capability families into
// lineages and exposes four advantages — interface-drift detection (surface silent
// breakage), self-healing version resolution (fall back past a bad latest), a SAFE
// consolidation plan (~21% surface reduction path), and a regression oracle.
// Sacred UNTOUCHED (R1); zero new npm deps (R6); version-suffixed (…334).
// Endpoints: V334-T01 lineage · T02 drift · T03 consolidation-plan · T04 resolve · T05 summary
// ═════════════════════════════════════════════════════════════════════════════
(function _wireCapabilityLineage334() {
  try {
    const Mesh = require('./lib/moduleMesh287.js');
    const L = require('./lib/capabilityLineage334.js');
    let _g334 = null;
    function graph334() { if (!_g334) _g334 = new Mesh.CapabilityGraph287().build([__dirname + '/lib']); return _g334; }

    // [V334-T01] lineage report
    app.get('/api/v1/lineage', (req, res) => {
      try { res.json({ ok: true, ...L.lineageReport334(graph334()), ecosVersion: 'V334' }); }
      catch (e) { res.status(500).json({ ok: false, error: e.message, ecosVersion: 'V334' }); }
    });
    // [V334-T02] interface-drift detection (surfaced silent breakage)
    app.get('/api/v1/lineage/drift', (req, res) => {
      try { res.json({ ok: true, ...L.detectInterfaceDrift334(graph334()), ecosVersion: 'V334' }); }
      catch (e) { res.status(500).json({ ok: false, error: e.message, ecosVersion: 'V334' }); }
    });
    // [V334-T03] safe consolidation plan (optimize the existing surface)
    app.get('/api/v1/lineage/consolidation-plan', (req, res) => {
      try { res.json({ ok: true, ...L.planConsolidation334(graph334()), ecosVersion: 'V334' }); }
      catch (e) { res.status(500).json({ ok: false, error: e.message, ecosVersion: 'V334' }); }
    });
    // [V334-T04] self-healing version resolution
    app.get('/api/v1/lineage/resolve/:base', (req, res) => {
      try {
        const knownBad = (req.query && req.query.knownBad ? String(req.query.knownBad).split(',') : []).map(Number).filter(n => !isNaN(n));
        const r = L.resolveBestVersion334(graph334(), req.params.base, { knownBad });
        if (!r) return res.status(404).json({ ok: false, error: 'unknown capability family', ecosVersion: 'V334' });
        res.json({ ok: true, ...r, ecosVersion: 'V334' });
      } catch (e) { res.status(500).json({ ok: false, error: e.message, ecosVersion: 'V334' }); }
    });
    // [V334-T05] summary
    app.get('/api/v1/admin/summary/v334', (req, res) => {
      try {
        const rep = L.lineageReport334(graph334()); const plan = L.planConsolidation334(graph334()); const drift = L.detectInterfaceDrift334(graph334());
        res.json({ ok: true, version: 'V334', phase: 'P222', feature: 'capability-lineage-and-self-healing',
          lineage: rep, driftFamilies: drift.drifted,
          consolidation: { safeRetireFamilies: plan.safeRetireFamilies, modulesRetirable: plan.modulesRetirable, surfaceReductionPct: plan.estimatedSurfaceReductionPct },
          insight: 'versioned duplication reframed as a self-healing, self-verifying capability fabric',
          ecosVersion: 'V334' });
      } catch (e) { res.status(500).json({ ok: false, error: e.message, ecosVersion: 'V334' }); }
    });
  } catch (e334) {
    try { logger.warn({ err: e334.message }, '[V334] capability lineage not wired (non-fatal)'); } catch (_) {}
  }
})();

