// V335 — Consolidation Execution (turn V334 analysis into concrete action)
// Phase P223 | Author: AI (lead) | Date: 2026-06-02
// Builds on V334 capabilityLineage334 and the V287 mesh:
//   T01 executeConsolidationSlice — ready-to-write thin re-export stubs for 5 deepest families
//   T02 wireSelfHealingDispatcher — mark known-bad versions; dispatch auto-falls-back
//   T03 buildDriftGuardrail — CI-runnable check; exitCode 1 when drift families exceed threshold
//   T04 runRegressionOracle — behavioral equivalence proof for a named lineage (dry-run safe)
//   T05 admin summary v335
// Sacred UNTOUCHED (R1); zero new npm deps (R3); all new ids end with `335` (R2).
// ═════════════════════════════════════════════════════════════════════════════
(function _wireConsolidationEngine335() {
  try {
    const Mesh = require('./lib/moduleMesh287.js');
    const L    = require('./lib/capabilityLineage334.js');
    const C    = require('./lib/consolidationEngine335.js');

    let _g335 = null;
    function graph335() {
      if (!_g335) _g335 = new Mesh.CapabilityGraph287().build([__dirname + '/lib']);
      return _g335;
    }

    // Stateful dispatcher (singleton per process)
    let _disp335 = null;
    function disp335() {
      if (!_disp335) _disp335 = C.wireSelfHealingDispatcher335(graph335(), L.resolveBestVersion334);
      return _disp335;
    }

    // [V335-T01] GET /api/v1/lineage/consolidation/slice/v335
    // Returns stub code + manifest for the N deepest safe-retire families.
    // Query: ?sliceSize=N (default 5)
    app.get('/api/v1/lineage/consolidation/slice/v335', (req, res) => {
      try {
        const sliceSize = req.query && req.query.sliceSize ? parseInt(req.query.sliceSize, 10) : 5;
        const result = C.executeConsolidationSlice335(graph335(), L.planConsolidation334, { sliceSize });
        res.json({ ok: true, ...result, ecosVersion: 'V335' });
      } catch (e) { res.status(500).json({ ok: false, error: e.message, ecosVersion: 'V335' }); }
    });

    // [V335-T02] POST /api/v1/lineage/dispatcher/heal/v335
    // Body: { familyBase, markBad?: [version,...] }
    // Marks versions bad and returns the currently-healthy dispatch result.
    app.post('/api/v1/lineage/dispatcher/heal/v335', (req, res) => {
      try {
        const { familyBase, markBad } = req.body || {};
        if (!familyBase) return res.status(400).json({ ok: false, error: 'familyBase required', ecosVersion: 'V335' });
        const d = disp335();
        if (Array.isArray(markBad) && markBad.length) d.markBad335(familyBase, markBad);
        const resolved = d.dispatch335(familyBase);
        if (!resolved) return res.status(404).json({ ok: false, error: 'unknown family', ecosVersion: 'V335' });
        res.json({ ok: true, ...resolved, registry: d.getKnownBadRegistry335(), stats: d.stats335(), ecosVersion: 'V335' });
      } catch (e) { res.status(500).json({ ok: false, error: e.message, ecosVersion: 'V335' }); }
    });

    // [V335-T03] GET /api/v1/lineage/guardrail/v335
    // CI drift guardrail. Query: ?warnThreshold=N (default 0)
    // Returns exitCode 0 (ok) or 1 (blocked) — pipeline can act on exitCode.
    app.get('/api/v1/lineage/guardrail/v335', (req, res) => {
      try {
        const warnThreshold = req.query && req.query.warnThreshold ? parseInt(req.query.warnThreshold, 10) : 0;
        const result = C.buildDriftGuardrail335(graph335(), L.detectInterfaceDrift334, { warnThreshold });
        const status = result.ok ? 200 : 422;
        res.status(status).json({ ok: result.ok, ...result, ecosVersion: 'V335' });
      } catch (e) { res.status(500).json({ ok: false, error: e.message, ecosVersion: 'V335' }); }
    });

    // [V335-T04] POST /api/v1/lineage/oracle/v335
    // Body: { familyBase, inputs?: [[arg,...], ...], dryRun?: true }
    // Runs regression oracle; dryRun:true is safe for automated CI (no require()).
    app.post('/api/v1/lineage/oracle/v335', (req, res) => {
      try {
        const { familyBase, inputs, dryRun } = req.body || {};
        if (!familyBase) return res.status(400).json({ ok: false, error: 'familyBase required', ecosVersion: 'V335' });
        const result = C.runRegressionOracle335(graph335(), L.compareVersions334, familyBase, {
          inputs: Array.isArray(inputs) ? inputs : [[1], [2], [3]],
          dryRun: dryRun !== false, // default true in API for safety
        });
        res.json({ ok: true, ...result, ecosVersion: 'V335' });
      } catch (e) { res.status(500).json({ ok: false, error: e.message, ecosVersion: 'V335' }); }
    });

    // [V335-T05] GET /api/v1/admin/summary/v335
    app.get('/api/v1/admin/summary/v335', (req, res) => {
      try {
        const slice    = C.executeConsolidationSlice335(graph335(), L.planConsolidation334, { sliceSize: 5 });
        const guardrail = C.buildDriftGuardrail335(graph335(), L.detectInterfaceDrift334);
        const dispStats = disp335().stats335();
        res.json({
          ok: true, version: 'V335', phase: 'P223',
          feature: 'consolidation-execution-self-healing-guardrail-oracle',
          consolidationSlice:  { totalStubs: slice.totalStubs, globalModulesRetirable: slice.globalModulesRetirable, families: slice.families.length },
          driftGuardrail:      { ok: guardrail.ok, drifted: guardrail.drifted, exitCode: guardrail.exitCode },
          selfHealingDispatcher: dispStats,
          insight: 'V334 analysis → V335 action: stubs ready, dispatcher live, guardrail armed, oracle on-demand',
          ecosVersion: 'V335',
        });
      } catch (e) { res.status(500).json({ ok: false, error: e.message, ecosVersion: 'V335' }); }
    });

  } catch (e335) {
    try { logger.warn({ err: e335.message }, '[V335] consolidation-engine not wired (non-fatal)'); } catch (_) {}
  }
})();

