// Four new tools: writeConsolidationStubs336, persistDispatcherRegistry336,
// loadDispatcherRegistry336, runOracleWithRealFns336
// Five new endpoints: V336-T01..T05
// Registry sidecar path (no new deps — plain fs.writeFileSync)
(function wireV336() {
  try {
    const Mesh = require('./lib/moduleMesh287.js');
    const L    = require('./lib/capabilityLineage334.js');
    const C    = require('./lib/consolidationEngine335.js');
    const W    = require('./lib/stubWriter336.js');
    const os   = require('os');
    const path = require('path');

    const REGISTRY_SIDECAR_PATH = process.env.DISPATCHER_REGISTRY_PATH ||
      path.join(os.tmpdir(), 'ecos_dispatcher_registry_v336.json');

    let _g336 = null;
    function graph336() {
      if (!_g336) _g336 = new Mesh.CapabilityGraph287().build([__dirname + '/lib']);
      return _g336;
    }

    // [V336-T01] POST /api/v1/lineage/stubs/write/v336
    // Body: { dryRun?: true, sliceSize?: N }
    // Generates (and optionally writes) thin re-export stubs for the N deepest families.
    // dryRun:true (default) — report only, no files touched.
    app.post('/api/v1/lineage/stubs/write/v336', (req, res) => {
      try {
        const { dryRun, sliceSize } = req.body || {};
        const dry = dryRun !== false; // default true — safe by default
        const sz  = typeof sliceSize === 'number' && sliceSize > 0 ? sliceSize : 5;
        const slice  = C.executeConsolidationSlice335(graph336(), L.planConsolidation334, { sliceSize: sz });
        const result = W.writeConsolidationStubs336(slice, {
          dryRun:  dry,
          baseDir: __dirname,
        });
        res.json({ ok: true, ...result, ecosVersion: 'V336' });
      } catch (e) { res.status(500).json({ ok: false, error: e.message, ecosVersion: 'V336' }); }
    });

    // [V336-T02] GET /api/v1/lineage/dispatcher/registry/persist/v336
    // Snapshot the in-memory known-bad dispatcher registry to the JSON sidecar.
    // The dispatcher is re-built from the graph + loaded sidecar on each server restart.
    app.get('/api/v1/lineage/dispatcher/registry/persist/v336', (req, res) => {
      try {
        const disp = C.wireSelfHealingDispatcher335(graph336(), L.resolveBestVersion334);
        const reg  = disp.getKnownBadRegistry335();
        const result = W.persistDispatcherRegistry336(reg, REGISTRY_SIDECAR_PATH);
        res.json({ ok: result.ok, ...result, sidecarPath: REGISTRY_SIDECAR_PATH, ecosVersion: 'V336' });
      } catch (e) { res.status(500).json({ ok: false, error: e.message, ecosVersion: 'V336' }); }
    });

    // [V336-T03] GET /api/v1/lineage/dispatcher/registry/load/v336
    // Read the JSON sidecar and return the loaded known-bad registry.
    // Useful for verifying restart-recovery state without restarting the server.
    app.get('/api/v1/lineage/dispatcher/registry/load/v336', (req, res) => {
      try {
        const result = W.loadDispatcherRegistry336(REGISTRY_SIDECAR_PATH);
        res.json({ ok: result.ok, ...result, sidecarPath: REGISTRY_SIDECAR_PATH, ecosVersion: 'V336' });
      } catch (e) { res.status(500).json({ ok: false, error: e.message, ecosVersion: 'V336' }); }
    });

    // [V336-T04] POST /api/v1/lineage/oracle/realfns/v336
    // Body: { familyBase?: string, inputs?: [[arg,...], ...] }
    // Real-fn regression oracle: require()s the boundary versions from lib/,
    // extracts a safe pure function, and proves behavioral equivalence.
    app.post('/api/v1/lineage/oracle/realfns/v336', (req, res) => {
      try {
        const { familyBase, inputs } = req.body || {};
        const base = familyBase || 'agentLoop';
        const result = W.runOracleWithRealFns336(graph336(), L.compareVersions334, base, {
          libDir: __dirname + '/lib',
          inputs: Array.isArray(inputs) ? inputs : undefined,
        });
        const status = result.ok ? 200 : (result.oldVersion == null ? 404 : 200);
        res.status(status).json({ ok: result.ok, ...result, ecosVersion: 'V336' });
      } catch (e) { res.status(500).json({ ok: false, error: e.message, ecosVersion: 'V336' }); }
    });

    // [V336-T05] GET /api/v1/admin/summary/v336
    // Aggregate summary across all four V336 tools.
    app.get('/api/v1/admin/summary/v336', (req, res) => {
      try {
        const slice   = C.executeConsolidationSlice335(graph336(), L.planConsolidation334, { sliceSize: 5 });
        const stubDry = W.writeConsolidationStubs336(slice, { dryRun: true });
        const guard   = C.buildDriftGuardrail335(graph336(), L.detectInterfaceDrift334);
        const sidecar = W.loadDispatcherRegistry336(REGISTRY_SIDECAR_PATH);
        const oracle  = W.runOracleWithRealFns336(graph336(), L.compareVersions334, 'agentLoop', {
          libDir: __dirname + '/lib',
        });
        res.json({
          ok: true, version: 'V336', phase: 'P224',
          feature: 'stub-writer-dispatcher-persistence-guardrail-real-fn-oracle',
          stubWriter:   { dryRun: true, wouldWrite: stubDry.written, skipped: stubDry.skipped, totalStubs: stubDry.totalStubs },
          driftGuardrail: { ok: guard.ok, drifted: guard.drifted, exitCode: guard.exitCode },
          registrySidecar: { ok: sidecar.ok, families: sidecar.families, savedAt: sidecar.savedAt || null },
          realFnOracle: { ok: oracle.ok, familyBase: oracle.familyBase, equivalencePct: oracle.equivalencePct },
          insight: 'V335 dry-manifests → V336 durable: stubs written, registry persisted, guardrail scripted, oracle real',
          ecosVersion: 'V336',
        });
      } catch (e) { res.status(500).json({ ok: false, error: e.message, ecosVersion: 'V336' }); }
    });

  } catch (e336) {
    try { logger.warn({ err: e336.message }, '[V336] stub-writer not wired (non-fatal)'); } catch (_) {}
  }
})();

