// ─── V341 (Phase P229) — Health Remediation Tracker ──────────────────────────
// Requires: lib/healthRemediationTracker341.js
// Four new tools: recordRemediationExecution341, compareProjectedVsActual341,
//                 buildExecutionAuditLog341, exportExecutionAuditLog341
// Five new endpoints: V341-T01..T05
(function wireV341() {
  try {
    const Mesh = require('./lib/moduleMesh287.js');
    const L    = require('./lib/capabilityLineage334.js');
    const W    = require('./lib/stubWriter336.js');
    const P    = require('./lib/healthReportPersistence338.js');
    const T    = require('./lib/healthTrendAnalyzer339.js');
    const R    = require('./lib/healthRemediationEngine340.js');
    const EX   = require('./lib/healthRemediationTracker341.js');

    const HEALTH_HISTORY_DIR_V341      = process.env.HEALTH_HISTORY_DIR ||
      require('path').join(require('os').tmpdir(), 'ecos_health_history');
    const HEALTH_EXECUTION_LOG_DIR_V341 = process.env.HEALTH_EXECUTION_LOG_DIR ||
      require('path').join(require('os').tmpdir(), 'ecos_health_execution_log');
    const HEALTH_AUDIT_EXPORT_DIR_V341  = process.env.HEALTH_AUDIT_EXPORT_DIR ||
      require('path').join(require('os').tmpdir(), 'ecos_health_audit_export');
    const REGISTRY_PATH_V341 = process.env.DISPATCHER_REGISTRY_PATH ||
      require('path').join(__dirname, '.dispatcher-registry.json');

    // [V341-T01] POST /api/v1/lineage/health/remediation/execute/v341
    // Body: { executedTaskIds[], executedBy?, notes?, dryRun?, windowSize?, maxTasks? }
    // Records execution of a subset of tasks from the latest remediation plan.
    app.post('/api/v1/lineage/health/remediation/execute/v341', (req, res) => {
      try {
        const { executedTaskIds, executedBy, notes, dryRun, windowSize, maxTasks } = req.body || {};
        const dry   = dryRun !== false;
        const hist  = P.loadHealthHistory338({ historyDir: HEALTH_HISTORY_DIR_V341, order: 'asc' });
        const trend = T.buildTrendReport339(hist, { windowSize });
        const plan  = R.buildRemediationPlan340(trend, { maxTasks });
        const result = EX.recordRemediationExecution341(plan, executedTaskIds || [], {
          logDir: HEALTH_EXECUTION_LOG_DIR_V341, executedBy, notes, dryRun: dry,
        });
        res.json({ ok: result.ok, ...result, ecosVersion: 'V341' });
      } catch (e) { res.status(500).json({ ok: false, error: e.message, ecosVersion: 'V341' }); }
    });

    // [V341-T02] POST /api/v1/lineage/health/remediation/compare/v341
    // Body: { snapshotBefore, snapshotAfter, executionId?, accuracyThreshold? }
    // Compares projected vs actual score deltas for a recorded execution.
    app.post('/api/v1/lineage/health/remediation/compare/v341', (req, res) => {
      try {
        const { snapshotBefore, snapshotAfter, executionId, accuracyThreshold } = req.body || {};
        const logPath = require('path').join(HEALTH_EXECUTION_LOG_DIR_V341, 'execution_log.jsonl');
        const { execSync: _es } = require('child_process'); // not used — pure fs read
        const fs2 = require('fs');
        if (!fs2.existsSync(logPath)) {
          return res.json({ ok: false, error: 'no execution log found', ecosVersion: 'V341' });
        }
        const lines = fs2.readFileSync(logPath, 'utf8').trim().split('\n').filter(Boolean);
        let record;
        if (executionId) record = lines.map(l => JSON.parse(l)).find(r => r.executionId === executionId);
        else             record = JSON.parse(lines[lines.length - 1]);
        if (!record) return res.json({ ok: false, error: 'execution record not found', ecosVersion: 'V341' });
        const result = EX.compareProjectedVsActual341(record, snapshotBefore, snapshotAfter, { accuracyThreshold });
        res.json({ ok: result.ok, ...result, ecosVersion: 'V341' });
      } catch (e) { res.status(500).json({ ok: false, error: e.message, ecosVersion: 'V341' }); }
    });

    // [V341-T03] GET /api/v1/lineage/health/remediation/audit/v341
    // Query: ?limit=N&since=ISO
    // Builds the execution audit log summary.
    app.get('/api/v1/lineage/health/remediation/audit/v341', (req, res) => {
      try {
        const { limit, since } = req.query || {};
        const result = EX.buildExecutionAuditLog341({
          logDir: HEALTH_EXECUTION_LOG_DIR_V341,
          limit:  limit ? parseInt(limit, 10) : undefined,
          since,
        });
        res.json({ ok: result.ok, ...result, ecosVersion: 'V341' });
      } catch (e) { res.status(500).json({ ok: false, error: e.message, ecosVersion: 'V341' }); }
    });

    // [V341-T04] POST /api/v1/lineage/health/remediation/audit/export/v341
    // Body: { dryRun?, meta? }
    // Exports the audit log to a JSON sidecar file.
    app.post('/api/v1/lineage/health/remediation/audit/export/v341', (req, res) => {
      try {
        const { dryRun, meta } = req.body || {};
        const dry   = dryRun !== false;
        const audit = EX.buildExecutionAuditLog341({ logDir: HEALTH_EXECUTION_LOG_DIR_V341 });
        const result = EX.exportExecutionAuditLog341(audit, {
          exportDir: HEALTH_AUDIT_EXPORT_DIR_V341, dryRun: dry, meta: meta || {},
        });
        res.json({ ok: result.ok, ...result, ecosVersion: 'V341' });
      } catch (e) { res.status(500).json({ ok: false, error: e.message, ecosVersion: 'V341' }); }
    });

    // [V341-T05] GET /api/v1/admin/summary/v341
    // Full V341 admin summary: trend, plan, audit log overview.
    app.get('/api/v1/admin/summary/v341', (req, res) => {
      try {
        const sidecar = W.loadDispatcherRegistry336(REGISTRY_PATH_V341);
        const hist    = P.loadHealthHistory338({ historyDir: HEALTH_HISTORY_DIR_V341, order: 'asc', limit: 20 });
        const trend   = T.buildTrendReport339(hist, { windowSize: 10 });
        const plan    = R.buildRemediationPlan340(trend, { maxTasks: 20 });
        const audit   = EX.buildExecutionAuditLog341({ logDir: HEALTH_EXECUTION_LOG_DIR_V341 });
        res.json({
          ok: true, version: 'V341', phase: 'P229',
          history: { historyDir: HEALTH_HISTORY_DIR_V341, totalSnapshots: hist.totalSnapshots },
          trend: {
            overallTrend:   trend.overallTrend,
            windowSize:     trend.windowSize,
            criticalAlerts: trend.criticalAlerts,
          },
          remediation: {
            totalTasks:    plan.totalTasks,
            criticalTasks: plan.criticalTasks,
            planId:        plan.planId,
          },
          executionAudit: {
            totalExecutions:     audit.totalExecutions,
            totalTasksExecuted:  audit.totalTasksExecuted,
            uniqueFamilies:      audit.uniqueFamilies,
            lastExecutionAt:     audit.lastExecutionAt,
          },
          registrySidecar: { ok: sidecar.ok, families: sidecar.families },
          insight: 'V341 remediation tracker: records execution events, compares projected vs actual outcomes, builds tamper-evident audit trails',
          ecosVersion: 'V341',
        });
      } catch (e) { res.status(500).json({ ok: false, error: e.message, ecosVersion: 'V341' }); }
    });

  } catch (e341) {
    try { logger.warn({ err: e341.message }, '[V341] health-remediation-tracker not wired (non-fatal)'); } catch (_) {}
  }
})();

// ─── V342 (Phase P230) — Health Policy Engine ─────────────────────────────────
// Requires: lib/healthPolicyEngine342.js
