    app.post('/api/v1/lineage/health/policy/evaluate/v342', (req, res) => {
      try {
        const { windowSize, enabledOnly } = req.body || {};
        const policyFile = require('path').join(HEALTH_POLICY_DIR_V342, 'policies.json');
        const hist   = P.loadHealthHistory338({ historyDir: HEALTH_HISTORY_DIR_V342, order: 'asc' });
        const trend  = T.buildTrendReport339(hist, { windowSize });
        const plan   = R.buildRemediationPlan340(trend);
        const result = PL.evaluatePolicies342(policyFile, trend, { plan, enabledOnly: enabledOnly !== false });
        res.json({ ok: result.ok, ...result, ecosVersion: 'V342' });
      } catch (e) { res.status(500).json({ ok: false, error: e.message, ecosVersion: 'V342' }); }
    });

    // [V342-T03] POST /api/v1/lineage/health/policy/trigger-report/v342
    // Body: { windowSize?, includeNotTriggered? }
    // Builds a structured trigger report from the current policy evaluation.
    app.post('/api/v1/lineage/health/policy/trigger-report/v342', (req, res) => {
      try {
        const { windowSize, includeNotTriggered } = req.body || {};
        const policyFile = require('path').join(HEALTH_POLICY_DIR_V342, 'policies.json');
        const hist   = P.loadHealthHistory338({ historyDir: HEALTH_HISTORY_DIR_V342, order: 'asc' });
        const trend  = T.buildTrendReport339(hist, { windowSize });
        const eval_  = PL.evaluatePolicies342(policyFile, trend);
        const result = PL.buildPolicyTriggerReport342(eval_, { includeNotTriggered: !!includeNotTriggered });
        res.json({ ok: result.ok, ...result, ecosVersion: 'V342' });
      } catch (e) { res.status(500).json({ ok: false, error: e.message, ecosVersion: 'V342' }); }
    });

