      const audit    = EX.buildExecutionAuditLog341({ logDir: HEALTH_EXECUTION_LOG_DIR_V343, limit: 50 });
      const policyFile = path3.join(HEALTH_POLICY_DIR_V343, 'policies.json');
      const policyEval = PL.evaluatePolicies342(fs3.existsSync(policyFile) ? policyFile : [], trend);
