// V360 — Economic Integrity Proof (continuous, signed verification of the core)
// Phase P248 | Author: AI (lead) | Date: 2026-06-02
// Strategic move (chosen from the archive): the durable value is a *verifiable*
// economic substrate (209/447 modules write the audit log; 94 the ledger). The
// audit log shipped verify() but it was never run; conservation/backing held only
// by convention. V360 composes those existing primitives into ONE continuously-
// produced, signed integrity attestation: audit-chain tamper-evidence + ledger
// conservation + 40/40/20 split conservation + reserve backing. Sacred UNTOUCHED
// (R1, read-only verification); zero new npm deps (R6); version-suffixed (…360).
// Endpoints: V360-T01 GET /api/v1/integrity/attest
//            V360-T02 GET /api/v1/integrity/:dimension (chain|conservation|split|backing)
//            V360-T03 GET /api/v1/admin/summary/v360
// ═════════════════════════════════════════════════════════════════════════════
(function _wireEconomicIntegrity360() {
  try {
    const P360 = require('./lib/economicIntegrityProof360.js');
    const AL = require('./lib/auditLog.js');
    const FL = require('./lib/fiatLedger.js');
    let reserve360 = null;
    try { reserve360 = require('./lib/creditReserve268.js').defaultCreditReserve268; } catch (_) {}
    function _ctx360() {
      return {
        ledger: FL.defaultLedger, auditLog: AL.defaultAuditLog, reserve: reserve360,
        hashFn: AL.sha256Hex, canonicalize: AL.canonicalize,
      };
    }

    // [V360-T01] full signed integrity attestation
    app.get('/api/v1/integrity/attest', (req, res) => {
      try {
        const att = P360.assessEconomicIntegrity360(_ctx360());
        if (att.failClosed) { try { logger.error({ integrity: att.summary }, '[V360] ECONOMIC INTEGRITY COMPROMISED'); } catch (_) {} }
        res.status(att.failClosed ? 409 : 200).json({ ok: !att.failClosed, attestation: att, ecosVersion: 'V360' });
      } catch (e) { res.status(500).json({ ok: false, error: e.message, ecosVersion: 'V360' }); }
    });

    // [V360-T02] a single dimension
    app.get('/api/v1/integrity/:dimension', (req, res) => {
      try {
        const c = _ctx360(); let out; const d = req.params.dimension;
        switch (d) {
          case 'chain': out = P360.verifyAuditChain360(c.auditLog); break;
          case 'conservation': out = P360.verifyLedgerConservation360(c.ledger); break;
          case 'split': out = P360.verifySplitConservation360(); break;
          case 'backing': out = P360.verifyReserveBacking360(c.reserve); break;
          default: return res.status(404).json({ ok: false, error: 'unknown dimension; use chain|conservation|split|backing', ecosVersion: 'V360' });
        }
        res.json({ ok: true, dimension: d, result: out, ecosVersion: 'V360' });
      } catch (e) { res.status(500).json({ ok: false, error: e.message, ecosVersion: 'V360' }); }
    });

    // [V360-T03] summary
    app.get('/api/v1/admin/summary/v360', (req, res) => {
      try {
        const att = P360.assessEconomicIntegrity360(_ctx360());
        res.json({ ok: true, version: 'V360', phase: 'P248', feature: 'economic-integrity-proof',
          overallIntegrity: att.overallIntegrity, failClosed: att.failClosed, summary: att.summary,
          attestationHash: att.attestationHash,
          thesis: 'turn the auditable-economy claim from convention into a continuously-produced, signed proof',
          ecosVersion: 'V360' });
      } catch (e) { res.status(500).json({ ok: false, error: e.message, ecosVersion: 'V360' }); }
    });
  } catch (e360) {
    try { logger.warn({ err: e360.message }, '[V360] economic integrity not wired (non-fatal)'); } catch (_) {}
  }
})();

// ═════════════════════════════════════════════════════════════════════════════
// V361 — Integrity Load-Bearing (gate, schedule, persisted-chain, export)
// Phase P249 | Author: AI (lead) | Date: 2026-06-03
// Strategic move (chosen from the V360 hand-off): V360 PRODUCED a continuously
// signed integrity attestation but nothing required it — a `compromised` proof
// was advisory. V361 makes it LOAD-BEARING: callers gate ledger mutation on it,
// the attestation itself is appended to the audit log on a schedule (self-
// referential trust), the DB-persisted chain is verified (durable storage
// tamper-evidence, not only in-memory), and a portable signed envelope lets a
// B2B counterparty independently re-verify. Sacred UNTOUCHED (R1), zero new
// npm deps (R3/R6), every new identifier suffixed …361 (R2).
// Endpoints: V361-T01 POST /api/v1/integrity/gate
//            V361-T02 POST /api/v1/integrity/schedule/:action  (start|stop|trigger|status)
//            V361-T03 GET  /api/v1/integrity/persisted
//            V361-T04 GET  /api/v1/integrity/export
//            V361-T05 GET  /api/v1/admin/summary/v361
// ═════════════════════════════════════════════════════════════════════════════
(function _wireIntegrityLoadBearing361() {
  try {
    const LB361 = require('./lib/economicIntegrityLoadBearing361.js');
    const AL = require('./lib/auditLog.js');
    const FL = require('./lib/fiatLedger.js');
    let reserve361 = null;
    try { reserve361 = require('./lib/creditReserve268.js').defaultCreditReserve268; } catch (_) {}
    let auditRepo361 = null;
    try { auditRepo361 = require('./db/auditRepo.js'); } catch (_) {}

    function _ctx361() {
      return {
        ledger: FL.defaultLedger, auditLog: AL.defaultAuditLog, reserve: reserve361,
        hashFn: AL.sha256Hex, canonicalize: AL.canonicalize,
      };
    }

    // Singleton scheduler — created lazily on first start.
    let _scheduler361 = null;
    function _scheduler() {
      if (!_scheduler361) {
        _scheduler361 = LB361.scheduleIntegrityAttestation361(_ctx361(), {
          intervalMs: Number(process.env.ECOS_INTEGRITY_INTERVAL_MS_361) || LB361.DEFAULT_ATTEST_INTERVAL_MS_361,
        });
      }
      return _scheduler361;
    }

    // [V361-T01] gate: callers POST before economic mutation
    app.post('/api/v1/integrity/gate', (req, res) => {
      try {
        const strict = !!(req.body && req.body.requireFullProof);
        const g = LB361.requireIntegrityVerified361(_ctx361(), { requireFullProof: strict });
        if (!g.allowed) {
          try { logger.error({ reason: g.reason }, '[V361] INTEGRITY GATE HALT'); } catch (_) {}
          return res.status(409).json({ ok: false, allowed: false, reason: g.reason, attestation: g.attestation, ecosVersion: 'V361' });
        }
        res.json({ ok: true, allowed: true, reason: g.reason, attestation: g.attestation, ecosVersion: 'V361' });
      } catch (e) { res.status(500).json({ ok: false, error: e.message, ecosVersion: 'V361' }); }
    });

    // [V361-T02] periodic-attestation control plane
    app.post('/api/v1/integrity/schedule/:action', (req, res) => {
      try {
        const s = _scheduler(); const action = req.params.action;
        let result;
        switch (action) {
          case 'start':   result = { started: s.start(),   running: s.isRunning() }; break;
          case 'stop':    result = { stopped: s.stop(),    running: s.isRunning() }; break;
          case 'trigger': result = { attestation: s.triggerNow(), appendedIndex: s.lastAppendedIndex }; break;
          case 'status':  result = { running: s.isRunning(), runs: s.runs, intervalMs: s.intervalMs, lastAttestation: s.lastAttestation, lastAppendedIndex: s.lastAppendedIndex }; break;
          default: return res.status(404).json({ ok: false, error: 'unknown action; use start|stop|trigger|status', ecosVersion: 'V361' });
        }
        res.json({ ok: true, action, result, ecosVersion: 'V361' });
      } catch (e) { res.status(500).json({ ok: false, error: e.message, ecosVersion: 'V361' }); }
    });

    // [V361-T03] persisted (DB-backed) chain verification
    app.get('/api/v1/integrity/persisted', async (req, res) => {
      try {
        const out = await LB361.verifyPersistedAuditChain361(auditRepo361);
        const httpStatus = (out.valid === false) ? 409 : 200;
        res.status(httpStatus).json({ ok: out.valid !== false, result: out, ecosVersion: 'V361' });
      } catch (e) { res.status(500).json({ ok: false, error: e.message, ecosVersion: 'V361' }); }
    });

    // [V361-T04] portable external attestation envelope + recipe
    app.get('/api/v1/integrity/export', (req, res) => {
      try {
        const out = LB361.buildExternalAttestation361(_ctx361());
        res.json({ ok: true, envelope: out.envelope, recipe: out.recipe, ecosVersion: 'V361' });
      } catch (e) { res.status(500).json({ ok: false, error: e.message, ecosVersion: 'V361' }); }
    });

    // [V361-T05] admin summary
    app.get('/api/v1/admin/summary/v361', (req, res) => {
      try {
        const g = LB361.requireIntegrityVerified361(_ctx361());
        const s = _scheduler361;
        res.json({
          ok: true, version: 'V361', phase: 'P249', feature: 'integrity-load-bearing',
          gate: { allowed: g.allowed, reason: g.reason },
          attestation: g.attestation,
          scheduler: s ? { running: s.isRunning(), runs: s.runs, intervalMs: s.intervalMs } : { running: false },
          persistedChainAvailable: !!auditRepo361,
          thesis: 'turn integrity from advisory observation into a load-bearing requirement (gate, schedule, persisted, export)',
          ecosVersion: 'V361',
        });
      } catch (e) { res.status(500).json({ ok: false, error: e.message, ecosVersion: 'V361' }); }
    });
  } catch (e361) {
    try { logger.warn({ err: e361.message }, '[V361] integrity load-bearing not wired (non-fatal)'); } catch (_) {}
  }
})();

