    let reserve362 = null;
    try { reserve362 = require('./lib/creditReserve268.js').defaultCreditReserve268; } catch (_) {}
    let auditRepo362 = null;
    try { auditRepo362 = require('./db/auditRepo.js'); } catch (_) {}

    function _ctx362() {
      return {
        ledger: FL.defaultLedger, auditLog: AL.defaultAuditLog, reserve: reserve362,
        auditRepo: auditRepo362,
        hashFn: AL.sha256Hex, canonicalize: AL.canonicalize,
      };
    }

