// The missing foundation before a real-money pilot: identities are now OWNED by an
// ed25519 keypair. id = sha256(pubkey)[0:16] (anti-spoof); claims are nonce-sequenced
// (anti-replay), signed over (semanticRoot‖nonce‖id) (anti-transplant), PoW-gated on
// creation (anti-sybil), and tombstoned on revoke (no zombies). Pure JS, Node builtin
// crypto only — NO new npm deps (R6). Every accepted claim is appended to the sacred
// audit log, so identity is tamper-evident and covered by the V360/V372 proofs.
// Endpoints: V391-T01 POST /api/v1/identity/execute
//            V391-T02 GET  /api/v1/identity/:id
//            V391-T03 GET  /api/v1/identity/pow/params
//            V391-T04 GET  /api/v1/admin/summary/v391
// ═════════════════════════════════════════════════════════════════════════════
(function _wireSovereignIdentity391() {
  try {
    const SI = require('./lib/sovereignIdentity391.js');
    let auditLog391 = null;
    try { auditLog391 = require('./lib/auditLog.js').defaultAuditLog; } catch (_) {}
    const _vm391 = new SI.SovereignIdentityVM391({
      audit: auditLog391 ? (type, payload) => { try { auditLog391.append(type, payload); } catch (_) {} } : null,
    });

    // [V391-T01] verify + apply a signed identity claim (create/update/revoke)
    app.post('/api/v1/identity/execute', (req, res) => {
      try {
        const b = req.body || {};
        if (!b.claim || !b.signature) return res.status(400).json({ ok: false, error: 'claim and signature required', code: 'BAD_REQUEST', ecosVersion: 'V391' });
        const out = _vm391.execute(b.claim, b.signature, b.rawPubkey);
        res.json({ ok: true, result: out, ecosVersion: 'V391' });
      } catch (e) { res.status((e && e.statusCode) || 500).json({ ok: false, error: e.message, code: e.code || 'ERROR', ecosVersion: 'V391' }); }
    });

    // [V391-T02] identity status (never returns private material)
    app.get('/api/v1/identity/:id', (req, res) => {
      const s = _vm391.status(req.params.id);
      if (!s.exists) return res.status(404).json({ ok: false, error: 'not found', code: 'NOT_FOUND', ecosVersion: 'V391' });
      res.json({ ok: true, identity: s, ecosVersion: 'V391' });
    });

    // [V391-T03] PoW parameters (so clients can mine before create)
    app.get('/api/v1/identity/pow/params', (req, res) => {
      res.json({ ok: true, difficulty: SI.POW_DIFFICULTY_391, scheme: 'sha256(id‖nonce) leading-zero bytes', ecosVersion: 'V391' });
    });

    // [V391-T04] summary
    app.get('/api/v1/admin/summary/v391', (req, res) => {
      res.json({ ok: true, version: 'V391', phase: 'P279', feature: 'sovereign-identity',
        defends: ['spoofing', 'replay', 'context-transplant', 'sybil(PoW)', 'tombstone', 'forged-signature'],
        auditChained: !!auditLog391, registry: _vm391.stats(),
        thesis: 'identities are cryptographically owned; actions are signed and audit-chained → we know who acted',
        ecosVersion: 'V391' });
    });
  } catch (e391) {
    try { logger.warn({ err: e391.message }, '[V391] sovereign identity not wired (non-fatal)'); } catch (_) {}
  }
})();

