        const b = req.body || {};
        if (!b.actorId || !b.claim || !b.signature || !b.receiptData) {
          return res.status(400).json({ ok: false, error: 'actorId, claim, signature, receiptData required', code: 'BAD_REQUEST', ecosVersion: 'V393' });
        }
