// ─────────────────────────────────────────────────────────────────────────────
// V415 — Live Chat Turn Pipeline (assess+adjust every response BEFORE the user sees it)
// Wires assessTurn414 into the live chat pipeline: every draft response is
// assessed and auto-adjusted (hedge/route/trim/de-flatten) before delivery.
// Endpoints: V415-T01 POST /api/v1/chat/turn
//            V415-T02 POST /api/v1/chat/session/start
//            V415-T03 GET  /api/v1/chat/session/:id/summary
//            V415-T04 GET  /api/v1/admin/summary/v415
// ─────────────────────────────────────────────────────────────────────────────
(() => {
  try {
    const wire415 = require('./lib/conversationPipeline415.js');
    // wire415 is the module itself (not a patch-style function here; we wire inline
    // so V414 mesh+audit refs are available in scope)
    const {
      runTurn415,
      createSession415,
      PIPELINE_VERSION_415,
    } = require('./lib/conversationPipeline415.js');

    const _sessions415 = new Map();
    const _SESSION_LIMIT_415 = 2000;
    function _evict415() { if (_sessions415.size >= _SESSION_LIMIT_415) { const k = _sessions415.keys().next().value; _sessions415.delete(k); } }

    // shared audit hook if available
    const _audit415 = (typeof defaultAuditLog !== 'undefined' && defaultAuditLog && typeof defaultAuditLog.append === 'function')
      ? (type, data) => { try { defaultAuditLog.append(type, data); } catch (_) {} }
      : null;

    // [V415-T01] full assess+adjust pipeline for a single chat turn
    app.post('/api/v1/chat/turn', (req, res) => { // V415-T01
      try {
        const b = req.body || {};
        if (!b.userMessage)   return res.status(400).json({ ok: false, error: 'userMessage required',   code: 'BAD_ARGS', ecosVersion: 'V415' });
        if (!b.draftResponse) return res.status(400).json({ ok: false, error: 'draftResponse required', code: 'BAD_ARGS', ecosVersion: 'V415' });
        let conv = null, loop = null;
        if (b.sessionId) {
          if (!_sessions415.has(b.sessionId)) { _evict415(); const s = createSession415({ id: b.sessionId, goal: b.goal }); _sessions415.set(b.sessionId, s); }
          const s = _sessions415.get(b.sessionId); conv = s.conversation; loop = s.improvementLoop;
        }
        const result = runTurn415({ userMessage: b.userMessage, draftResponse: b.draftResponse, conversation: conv, improvementLoop: loop || undefined, audit: _audit415, maxSentences: b.maxSentences || 12 });
        res.json(Object.assign({ ok: true, ecosVersion: 'V415' }, result));
      } catch (e) { res.status(500).json({ ok: false, error: e.message, ecosVersion: 'V415' }); }
    });

    // [V415-T02] create/start a named multi-turn session
    app.post('/api/v1/chat/session/start', (req, res) => { // V415-T02
      try {
        const b = req.body || {};
        const id = b.sessionId || ('auto415_' + Date.now());
        _evict415();
        const s = createSession415({ id, goal: b.goal });
        _sessions415.set(id, s);
        res.status(201).json({ ok: true, sessionId: id, goal: b.goal || null, ecosVersion: 'V415' });
      } catch (e) { res.status(500).json({ ok: false, error: e.message, ecosVersion: 'V415' }); }
    });

    // [V415-T03] session conversation state + improvement loop report
    app.get('/api/v1/chat/session/:id/summary', (req, res) => { // V415-T03
      try {
        const s = _sessions415.get(req.params.id);
        if (!s) return res.status(404).json({ ok: false, error: 'session not found', ecosVersion: 'V415' });
        res.json(Object.assign({ ok: true, ecosVersion: 'V415' }, s.summary()));
      } catch (e) { res.status(500).json({ ok: false, error: e.message, ecosVersion: 'V415' }); }
    });

    // [V415-T04] summary
    app.get('/api/v1/admin/summary/v415', (_req, res) => { // V415-T04
      res.json({ ok: true, version: 'V415', phase: 'P303', pipelineVersion: PIPELINE_VERSION_415,
        feature: 'live chat turn pipeline — assessTurn414 wired into every response before the user sees it',
        activeSessions: _sessions415.size,
        endpoints: ['POST /api/v1/chat/turn [T01]', 'POST /api/v1/chat/session/start [T02]', 'GET /api/v1/chat/session/:id/summary [T03]', 'GET /api/v1/admin/summary/v415 [T04]'],
        ecosVersion: 'V415' });
    });
  } catch (e415) {
    try { logger.warn({ err: e415.message }, '[V415] live chat pipeline not wired (non-fatal)'); } catch (_) {}
  }
})();

