//   V548-T04  GET  /api/v1/admin/summary/v548
// ═══════════════════════════════════════════════════════════════
(function _wirePolicyLog548() {
  try {
    const pLog548  = require('./lib/deepHealthPolicyLog548.js');
    const gate547  = require('./lib/orchestratorPolicyGate547.js');
    const policy546 = require('./lib/deepHealthPolicy546.js');

    // Seed the log with current policy state (snapshot on startup)
    try {
      const snap = policy546.getPolicy546({});
      pLog548.recordDecision548({
        decision:  snap.decision,
        score:     snap.score,
        trend:     snap.trend,
        reasoning: snap.reasoning,
        source:    'startup-snapshot',
        blocked:   snap.decision !== 'AUTO',
      });
    } catch (_) { /* non-fatal */ }

    // [V548-T01] GET /api/v1/health/policy-log
    app.get('/api/v1/health/policy-log', (req, res) => {
      try {
        const log = pLog548.getLog548();
        res.json({ ok: true, ecosVersion: 'V548', count: log.length, entries: log });
      } catch (e) {
        res.status(500).json({ ok: false, error: e.message, ecosVersion: 'V548' });
      }
    });

    // [V548-T02] GET /api/v1/health/policy-log/summary
    app.get('/api/v1/health/policy-log/summary', (req, res) => {
      try {
        // Append a live reading before returning summary
        try {
          const live = policy546.getPolicy546({});
          pLog548.recordDecision548({
            decision:  live.decision,
            score:     live.score,
            trend:     live.trend,
            reasoning: live.reasoning,
            source:    'live-probe',
            blocked:   live.decision !== 'AUTO',
          });
        } catch (_) {}
        const summary = pLog548.getLogSummary548();
        res.json({ ok: true, ecosVersion: 'V548', ...summary });
      } catch (e) {
        res.status(500).json({ ok: false, error: e.message, ecosVersion: 'V548' });
      }
    });

    // [V548-T03] POST /api/v1/health/policy-log/record
    // Body: { decision, score, trend, reasoning, source }
    app.post('/api/v1/health/policy-log/record', (req, res) => {
      try {
        const body = req.body || {};
        const allowed = ['AUTO', 'SUPERVISED', 'MANUAL'];
        if (!allowed.includes(body.decision)) {
          return res.status(400).json({
            ok: false,
            error: `decision must be one of: ${allowed.join(', ')}`,
            ecosVersion: 'V548',
          });
        }
        pLog548.recordDecision548({
          decision:  body.decision,
          score:     typeof body.score === 'number' ? body.score : 0,
          trend:     body.trend     || 'unknown',
          reasoning: body.reasoning || '',
          source:    body.source    || 'api',
          blocked:   body.decision !== 'AUTO',
        });
        res.json({ ok: true, ecosVersion: 'V548', totalRecorded: pLog548.getLog548().length });
      } catch (e) {
        res.status(500).json({ ok: false, error: e.message, ecosVersion: 'V548' });
      }
    });

    // [V548-T04] GET /api/v1/admin/summary/v548
    app.get('/api/v1/admin/summary/v548', (req, res) => {
      try {
        const summary = pLog548.getLogSummary548();
        const gateStatus = gate547.getPolicyStatus547 ? gate547.getPolicyStatus547() : null;
        res.json({
          ok:          true,
          ecosVersion: 'V548',
          version:     '548.0.0',
          phase:       'P275',
          built:       new Date().toISOString(),
          description: 'deepHealthPolicyLog548 — ring buffer of 50 policy decisions with trend analysis',
          log:         summary,
          gateStatus,
          sacred:      { fiatLedger: '563e9b1f9e67091a5b6527c0a92568e5', auditLog: 'e5a5c2c27801d2d03991bc8e5a1df8cb' },
          endpoints: [
            'GET  /api/v1/health/policy-log',
            'GET  /api/v1/health/policy-log/summary',
            'POST /api/v1/health/policy-log/record',
            'GET  /api/v1/admin/summary/v548',
          ],
          next: 'V549: wire recordDecision548 into gatePlan547 so every gate call auto-logs.',
        });
      } catch (e) {
        res.status(500).json({ ok: false, error: e.message, ecosVersion: 'V548' });
      }
    });

  } catch (e548) {
    try { logger.warn({ err: e548.message }, '[V548] policyLog not active (non-fatal)'); } catch (_) {}
  }
})();

